function h($s) { return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8'); }
function out($a, $c = 200) { http_response_code($c); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store'); echo json_encode($a); exit; }
function db() {
    static $p = null;
    if (!$p) { $p = new PDO('mysql:host=' . DB_HOST . ';dbname=' . DB_NAME . ';charset=utf8mb4', DB_USER, DB_PASS, array(PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC)); }
    return $p;
}
function q($sql, $a = array()) {
    if (!empty($GLOBALS['CO_UID']) && strpos($sql, 'owner=?') !== false && preg_match('/\bchats\b/', $sql)) list($sql, $a) = co_sql($sql, $a);
    $s = db()->prepare($sql); $s->execute($a); return $s;
}
function co_sql($sql, $a) {   /* hamkor admin: chats jadvalidagi «owner=?» -> egasi yoki hamkor admini (faqat joriy foydalanuvchi uchun) */
    $parts = explode('?', $sql); if (count($parts) - 1 !== count($a)) return array($sql, $a);
    $out = $parts[0]; $na = array(); $uid = (string)$GLOBALS['CO_UID'];
    foreach (array_values($a) as $i => $v) {
        if ((string)$v === $uid && preg_match('/(\b[a-z_]+\.)?owner=$/', $out, $mm) && (empty($mm[1]) || $mm[1] === 'c.')) {
            $al = empty($mm[1]) ? '' : 'c.';
            $out = substr($out, 0, -strlen($al . 'owner=')) . '(' . $al . 'owner=? OR ' . $al . 'id IN (SELECT chat_ref FROM chat_admins WHERE user_id=?))'; $na[] = $v; $na[] = $v;
        } else { $out .= '?'; $na[] = $v; }
        $out .= $parts[$i + 1];
    }
    return array($out, $na);
}
/* Migratsiya bayroqlari (mig_*) har so'rovda bitta so'rov bilan o'qiladi, qolgan sozlamalar avvalgidek bevosita */
function mig_flags($set = null) {
    static $m = null;
    if ($m === null) { $m = array(); try { foreach (q("SELECT k FROM settings WHERE k LIKE 'mig\\_%' AND v='1'")->fetchAll(PDO::FETCH_COLUMN) as $x) $m[$x] = 1; } catch (Exception $e) {} }
    if ($set !== null) $m[$set] = 1;
    return $m;
}
function memo_key($k) { return preg_match('/^(nk|sm|vs|sec|lv|lo|pt|bn|lb|g|sv|sh|pay|sms|rp|pg|mn|price|rz|hw|car|wxu|rm|faq)_/', $k) === 1; }
function memo_get($k, $set = false, $v = null) { static $c = array(); if ($set) { $c[$k] = $v; return null; } return array_key_exists($k, $c) ? array($c[$k]) : null; }
function setting($k, $d = '') {
    if (strncmp($k, 'mig_', 4) === 0) { $m = mig_flags(); return isset($m[$k]) ? '1' : $d; }
    $mm = memo_key($k); if ($mm && ($h = memo_get($k)) !== null) return $h[0] === false ? $d : $h[0];
    $v = q('SELECT v FROM settings WHERE k=?', array($k))->fetchColumn(); if ($mm) memo_get($k, true, $v); return $v === false ? $d : $v;
}
function setset($k, $v) { q('INSERT INTO settings (k,v) VALUES (?,?) ON DUPLICATE KEY UPDATE v=VALUES(v)', array($k, (string)$v)); if (strncmp($k, 'mig_', 4) === 0 && (string)$v === '1') mig_flags($k); if (memo_key($k)) memo_get($k, true, (string)$v); }
function menu_flags() { return array('bal' => setting('mn_bal', '1') === '1', 'ads' => setting('mn_ads', '1') === '1'); }
/* azo_dat.txt: /start bosganlar ID si faylga qo'shib boriladi, admin «Yuklash» bilan bazaga oladi */
function azo_file_ids() {
    $f = __DIR__ . '/azo_dat.txt'; $ids = array();
    if (is_file($f)) foreach (preg_split('/\R/', (string)file_get_contents($f)) as $l) { $l = trim($l); if ($l !== '' && ctype_digit($l) && strlen($l) <= 15) $ids[$l] = 1; }
    return array_map('strval', array_keys($ids));
}
function azo_file_add($id) {
    $id = (string)(int)$id; if ($id === '0') return;
    $f = __DIR__ . '/azo_dat.txt';
    $h = @fopen($f, 'c+'); if (!$h) return;
    if (flock($h, LOCK_EX)) {
        $txt = stream_get_contents($h);
        if (!preg_match('/(^|\R)' . $id . '(\R|$)/', (string)$txt)) {
            fseek($h, 0, SEEK_END);
            fwrite($h, ($txt !== '' && !preg_match('/\R$/', $txt) ? "\n" : '') . $id . "\n");
        }
        flock($h, LOCK_UN);
    }
    fclose($h);
}
function azo_file_stat() {
    $ids = azo_file_ids(); $in = 0;
    try { foreach (array_chunk($ids, 1000) as $ch) $in += (int)q('SELECT COUNT(*) FROM azo_import WHERE id IN (' . implode(',', array_fill(0, count($ch), '?')) . ')', $ch)->fetchColumn(); } catch (Exception $e) {}
    return array('file' => count($ids), 'wait' => count($ids) - $in);
}
function azo_n() { try { return (int)q('SELECT COUNT(*) FROM azo_import')->fetchColumn(); } catch (Exception $e) { return 0; } }
function subs_n() { try { return (int)q('SELECT COUNT(*) FROM (SELECT id FROM users WHERE blocked=0 UNION SELECT id FROM azo_import WHERE id NOT IN (SELECT id FROM users WHERE blocked=1)) t')->fetchColumn(); } catch (Exception $e) { return (int)q('SELECT COUNT(*) FROM users WHERE blocked=0')->fetchColumn(); } }
function is_admin($id) { return in_array((string)$id, array_map('trim', explode(',', ADMIN_IDS)), true); }
function http($url, $post = null) {
    $c = curl_init($url);
    curl_setopt_array($c, array(CURLOPT_RETURNTRANSFER => 1, CURLOPT_TIMEOUT => 15, CURLOPT_FOLLOWLOCATION => 1, CURLOPT_USERAGENT => 'Mozilla/5.0 TartibOn'));
    if ($post !== null) { curl_setopt($c, CURLOPT_POST, 1); curl_setopt($c, CURLOPT_POSTFIELDS, $post); }
    $r = curl_exec($c); $ok = curl_errno($c) === 0 && curl_getinfo($c, CURLINFO_HTTP_CODE) < 400; curl_close($c);
    return $ok ? $r : false;
}
function tg($m, $p = array()) { $r = http('https://api.telegram.org/bot' . BOT_TOKEN . '/' . $m, $p); return $r ? json_decode($r, true) : array('ok' => false); }

/* Bir vaqtda ko'p xabar: curl_multi bilan parallel. 429 bo'lsa retry_after kutib, bir marta qayta urinadi. */
function tg_multi($method, $items) {
    $run = function ($list) use ($method) {
        $mh = curl_multi_init(); $hs = array();
        foreach ($list as $k => $p) {
            $p = quiet_p($method, $p);
            $c = curl_init('https://api.telegram.org/bot' . BOT_TOKEN . '/' . $method);
            curl_setopt_array($c, array(CURLOPT_POST => 1, CURLOPT_POSTFIELDS => json_encode($p), CURLOPT_HTTPHEADER => array('Content-Type: application/json'), CURLOPT_RETURNTRANSFER => 1, CURLOPT_TIMEOUT => 25, CURLOPT_CONNECTTIMEOUT => 6));
            curl_multi_add_handle($mh, $c); $hs[$k] = $c;
        }
        do { $st = curl_multi_exec($mh, $act); if ($act) curl_multi_select($mh, 0.5); } while ($act && $st === CURLM_OK);
        $res = array();
        foreach ($hs as $k => $c) { $r = curl_multi_getcontent($c); $res[$k] = $r ? json_decode($r, true) : array('ok' => false, 'description' => 'tarmoq xatosi'); curl_multi_remove_handle($mh, $c); curl_close($c); }
        curl_multi_close($mh);
        return $res;
    };
    $res = $run($items); $retry = array(); $wait = 0;
    foreach ($res as $k => $r) if (empty($r['ok']) && isset($r['error_code']) && (int)$r['error_code'] === 429) { $retry[$k] = $items[$k]; $wait = max($wait, isset($r['parameters']['retry_after']) ? (int)$r['parameters']['retry_after'] : 1); }
    if ($retry && $wait <= 8) { sleep($wait + 1); foreach ($run($retry) as $k => $r) $res[$k] = $r; }
    return $res;
}
