function install() {
    $t = array(
        "users (id BIGINT UNSIGNED PRIMARY KEY, username VARCHAR(64) NOT NULL DEFAULT '', name VARCHAR(190) NOT NULL DEFAULT '', phone VARCHAR(32) NULL, phone_at DATETIME NULL, blocked TINYINT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, last_seen DATETIME NOT NULL)",
        "rates (id INT AUTO_INCREMENT PRIMARY KEY, cur CHAR(3) NOT NULL, bank VARCHAR(60) NOT NULL, kind VARCHAR(10) NOT NULL DEFAULT 'bank', buy DECIMAL(14,2) NULL, sell DECIMAL(14,2) NULL, official DECIMAL(14,2) NULL, prev_buy DECIMAL(14,2) NULL, prev_sell DECIMAL(14,2) NULL, prev_official DECIMAL(14,2) NULL, source VARCHAR(255) NOT NULL DEFAULT '', manual TINYINT NOT NULL DEFAULT 0, measured_at DATETIME NULL, fetched_at DATETIME NOT NULL, UNIQUE KEY u (cur,bank))",
        "rate_history (id INT AUTO_INCREMENT PRIMARY KEY, cur CHAR(3) NOT NULL, bank VARCHAR(60) NOT NULL, buy DECIMAL(14,2) NULL, sell DECIMAL(14,2) NULL, official DECIMAL(14,2) NULL, source VARCHAR(255) NOT NULL, at DATETIME NOT NULL, KEY k (cur,bank,at))",
        "chats (id INT AUTO_INCREMENT PRIMARY KEY, owner BIGINT UNSIGNED NOT NULL, chat_id BIGINT NOT NULL, username VARCHAR(64) NOT NULL, ctype VARCHAR(10) NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'pending', auto_on TINYINT NOT NULL DEFAULT 0, interval_h SMALLINT NOT NULL DEFAULT 3, curs VARCHAR(40) NOT NULL DEFAULT 'USD,EUR,RUB', show_buy TINYINT NOT NULL DEFAULT 1, show_sell TINYINT NOT NULL DEFAULT 1, send_a TINYINT NOT NULL DEFAULT 1, send_b TINYINT NOT NULL DEFAULT 0, dp_on TINYINT NOT NULL DEFAULT 0, dp_date DATE NULL, blocked TINYINT NOT NULL DEFAULT 0, last_post_at DATETIME NULL, last_sig CHAR(32) NULL, created_at DATETIME NOT NULL, UNIQUE KEY u (owner,chat_id), FOREIGN KEY (owner) REFERENCES users(id) ON DELETE CASCADE)",
        "post_logs (id INT AUTO_INCREMENT PRIMARY KEY, chat_id INT NOT NULL, ok TINYINT NOT NULL, info VARCHAR(255) NOT NULL DEFAULT '', at DATETIME NOT NULL, KEY k (at))",
        "audit_logs (id INT AUTO_INCREMENT PRIMARY KEY, admin BIGINT UNSIGNED NOT NULL, action VARCHAR(40) NOT NULL, detail TEXT, at DATETIME NOT NULL)",
        "settings (k VARCHAR(60) PRIMARY KEY, v TEXT)"
    );
    foreach ($t as $x) db()->exec('CREATE TABLE IF NOT EXISTS ' . $x . ' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
    pr_install(); guard_install(); ext_install();
}

/* ---------- KURS MANBALARI (adapterlar) ---------- */
function same_num($a, $b) {
    if ($a === null || $a === '') return $b === null || $b === '';
    if ($b === null || $b === '') return false;
    return abs((float)$a - (float)$b) < 0.005;
}
function save_rate($cur, $bank, $kind, $buy, $sell, $off, $src, $manual, $meas) {
    $o = q('SELECT * FROM rates WHERE cur=? AND bank=?', array($cur, $bank))->fetch();
    $now = date('Y-m-d H:i:s');
    if (!$o) {
        q('INSERT INTO rates (cur,bank,kind,buy,sell,official,source,manual,measured_at,fetched_at) VALUES (?,?,?,?,?,?,?,?,?,?)', array($cur, $bank, $kind, $buy, $sell, $off, $src, $manual, $meas, $now));
    } else {
        $ch = !same_num($o['buy'], $buy) || !same_num($o['sell'], $sell) || !same_num($o['official'], $off);
        q('UPDATE rates SET prev_buy=IF(?,buy,prev_buy), prev_sell=IF(?,sell,prev_sell), prev_official=IF(?,official,prev_official), kind=?, buy=?, sell=?, official=?, source=?, manual=?, measured_at=?, fetched_at=? WHERE id=?', array($ch ? 1 : 0, $ch ? 1 : 0, $ch ? 1 : 0, $kind, $buy, $sell, $off, $src, $manual, $meas, $now, $o['id']));   /* MySQL SET chapdan o'ngga: oldingi qiymat yangisidan oldin saqlanadi */
        if (!$ch) return;
    }
    q('INSERT INTO rate_history (cur,bank,buy,sell,official,source,at) VALUES (?,?,?,?,?,?,?)', array($cur, $bank, $buy, $sell, $off, $src, $now));
}
/* Kurs manbasi: avval to'g'ridan-to'g'ri, ulanmasa — ochiq «ko'prik» xizmatlari orqali (hosting O'zbekiston saytlariga chiqa olmasa).
   To'g'ridan-to'g'ri ulanish ishlamasa, soatiga bir marta qayta sinaladi; oxirgi ishlagan ko'prik birinchi sinaladi. */
function relays() {
    $l = array(); foreach (preg_split('/\R/', (string)setting('relays', "allorigins|https://api.allorigins.win/raw?url={enc}\ncorsproxy|https://corsproxy.io/?url={enc}\njina|https://r.jina.ai/{raw}")) as $x) { $p = explode('|', trim($x), 2); if (count($p) === 2) $l[$p[0]] = $p[1]; }
    return $l;
}
function json_pick($s) {   /* ko'prik matn ichiga o'ragan bo'lsa ham JSON ni ajratib oladi */
    if (is_array(json_decode($s, true))) return $s;
    $a = strpos($s, '['); $b = strrpos($s, ']'); if ($a === false || $b === false || $b <= $a) return null;
    $j = substr($s, $a, $b - $a + 1); return is_array(json_decode($j, true)) ? $j : null;
}
function relay_get($url, $json = false) {   /* asosiy (to'g'ridan-to'g'ri) yo'l ishlamaganda — zaxira ko'priklar */
    $why = array(); $rl = relays(); $pref = setting('relay_ok', ''); if (isset($rl[$pref])) $rl = array($pref => $rl[$pref]) + $rl;
    foreach ($rl as $n => $tpl) {
        list($r, $e) = mkb_http(strtr($tpl, array('{enc}' => rawurlencode($url), '{raw}' => $url))); if ($r !== null && $json) $r = json_pick($r);
        if ($r !== null && $r !== '') { setset('relay_ok', $n); return array($r, $n, ''); }
        $why[] = $n . ': ' . ($e !== '' ? $e : 'javob yaroqsiz');
    }
    return array(null, '', implode('; ', $why));
}
function cbu_sane($cur, $v) {   /* ko'prikdan kelgan qiymat avvalgisidan 5% dan ko'p farq qilsa — qabul qilinmaydi */
    if ($cur !== 'USD') return true;
    if ($v < 5000 || $v > 50000) return false;
    $o = q("SELECT official FROM rates WHERE cur='USD' AND bank='Markaziy bank'")->fetchColumn();
    return !$o || abs($v - (float)$o) / (float)$o <= 0.05;
}
function cbu_xml($s) {   /* CBU XML (arkhiv-kursov-valyut/xml/) -> JSON bilan bir xil ko'rinish */
    $a = stripos((string)$s, '<arrayofcbu'); if ($a === false) return null;
    $x = @simplexml_load_string(substr($s, $a), 'SimpleXMLElement', LIBXML_NOCDATA | LIBXML_NONET); if (!$x) return null;
    $o = array(); foreach ($x->CBU as $c) $o[] = array('Ccy' => (string)$c->Ccy, 'Nominal' => (string)$c->Nominal, 'Rate' => (string)$c->Rate, 'Diff' => (string)$c->Diff, 'Date' => (string)$c->Date);
    return $o ? $o : null;
}
function cbu_save($j, $u) {   /* CBU JSON -> rates (asl usul) */
    global $CUR; $n = 0;
    foreach ($j as $x) {
        if (!isset($x['Ccy']) || !isset($CUR[$x['Ccy']])) continue;
        $nom = max(1, (float)$x['Nominal']); $v = round((float)$x['Rate'] / $nom, 2);
        $d = DateTime::createFromFormat('d.m.Y', (string)$x['Date']);
        if ($v > 0) { save_rate($x['Ccy'], 'Markaziy bank', 'official', null, null, $v, $u, 0, $d ? $d->format('Y-m-d 00:00:00') : null); $n++;
            if (isset($x['Diff']) && is_numeric($x['Diff'])) q('UPDATE rates SET prev_official=? WHERE cur=? AND bank=?', array(round($v - (float)$x['Diff'] / $nom, 2), $x['Ccy'], 'Markaziy bank')); }
    }
    return $n;
}
function fetch_cbu() {
    global $CUR; $j = null; $why = array(); @set_time_limit(180);
    /* 1) asosiy yo'l — 22.10 dagi ishlagan asl kod bilan harfma-harf bir xil so'rov (o'sha manzil, o'sha sozlamalar, o'sha User-Agent) */
    $u = 'https://cbu.uz/uz/arkhiv-kursov-valyut/json/';
    $c = curl_init($u);
    curl_setopt_array($c, array(CURLOPT_RETURNTRANSFER => 1, CURLOPT_TIMEOUT => 15, CURLOPT_FOLLOWLOCATION => 1, CURLOPT_USERAGENT => 'Mozilla/5.0 UsdPremium'));
    $r = curl_exec($c); $no = curl_errno($c); $code = (int)curl_getinfo($c, CURLINFO_HTTP_CODE); $ce = curl_error($c); curl_close($c);
    $j = $no === 0 && $code < 400 ? json_decode((string)$r, true) : null; if (!is_array($j) || !$j) $j = null;
    if (!$j) {
        $why[] = 'cbu.uz: ' . ($no ? $ce : ($code >= 400 ? 'HTTP ' . $code : 'JSON emas'));
        if ($no !== 28 && $no !== 7 && $no !== 6) {   /* ulanish bo'lsa-yu javob noto'g'ri bo'lsa — boshqa til manzillari; ulanmasa (timeout) qayta urinish befoyda */
            foreach (array('https://cbu.uz/ru/arkhiv-kursov-valyut/json/', 'https://cbu.uz/oz/arkhiv-kursov-valyut/json/') as $u) {
                list($r, $e) = mkb_http($u); $j = $r !== null ? json_decode($r, true) : null;
                if (is_array($j) && $j) break;
                $why[] = $e !== '' ? $e : 'JSON emas'; $j = null;
            }
            if (!$j) {   /* JSON ishlamasa — o'sha cbu.uz ning XML manzili */
                $u = 'https://cbu.uz/uz/arkhiv-kursov-valyut/xml/'; list($r, $e) = mkb_http($u); $j = $r !== null ? cbu_xml($r) : null;
                if (!$j) $why[] = 'XML: ' . ($e !== '' ? $e : 'XML emas');
            }
        }
    }
    if (is_array($j)) { if (cbu_save($j, $u)) { setset('cbu_src', strpos($u, '/xml/') ? 'cbu.uz XML' : 'cbu.uz'); return ''; } return 'CBU: valyutalar topilmadi'; }
    /* 2) zaxira — xuddi shu cbu.uz JSON API, ko'prik orqali (qiymat tekshiriladi) */
    $u = 'https://cbu.uz/uz/arkhiv-kursov-valyut/json/';
    list($r, $via, $e) = relay_get($u, true); $j = $r !== null ? json_decode($r, true) : null;
    if (is_array($j)) {
        $usd = null; foreach ($j as $x) if (isset($x['Ccy'], $x['Rate']) && $x['Ccy'] === 'USD') $usd = round((float)$x['Rate'] / max(1, (float)$x['Nominal']), 2);
        if ($usd && cbu_sane('USD', $usd) && cbu_save($j, $u)) { setset('cbu_src', 'cbu.uz (' . $via . ' orqali)'); return ''; }
        $why[] = 'ko\'prik: USD kursi shubhali';
    } else $why[] = $e;
    $u = 'https://cbu.uz/uz/arkhiv-kursov-valyut/xml/';   /* ko'prik orqali XML */
    list($r, $via, $e) = relay_get($u); $j = $r !== null ? cbu_xml($r) : null;
    if (is_array($j)) {
        $usd = null; foreach ($j as $x) if ($x['Ccy'] === 'USD') $usd = round((float)$x['Rate'] / max(1, (float)$x['Nominal']), 2);
        if ($usd && cbu_sane('USD', $usd) && cbu_save($j, $u)) { setset('cbu_src', 'cbu.uz XML (' . $via . ' orqali)'); return ''; }
    }
    /* 3) zaxira — Milliy bank (nbu.uz) JSON: Markaziy bank rasmiy kursi (cb_price) */
    list($r, $e) = mkb_http('https://nbu.uz/uz/exchange-rates/json/'); $via = '';
    if ($r === null || json_pick($r) === null) { list($r, $via, $e2) = relay_get('https://nbu.uz/uz/exchange-rates/json/', true); if ($r === null) $e = trim($e . '; ' . $e2, '; '); }
    $nb = $r !== null ? json_decode((string)json_pick($r), true) : null; $rows = array();
    if (is_array($nb)) foreach ($nb as $x) {
        $cc = isset($x['code']) ? (string)$x['code'] : ''; $v = isset($x['cb_price']) ? round((float)str_replace(array(' ', ','), array('', '.'), (string)$x['cb_price']), 2) : 0;
        if (isset($CUR[$cc]) && $v > 0) $rows[$cc] = array($v, $x);
    }
    if (isset($rows['USD']) && cbu_sane('USD', $rows['USD'][0])) {
        foreach ($rows as $cc => $rw) { $d = isset($rw[1]['date']) ? DateTime::createFromFormat('d.m.Y', substr((string)$rw[1]['date'], 0, 10)) : false;
            save_rate($cc, 'Markaziy bank', 'official', null, null, $rw[0], 'https://nbu.uz', 0, $d ? $d->format('Y-m-d 00:00:00') : null); }
        setset('cbu_src', 'nbu.uz' . ($via !== '' ? ' (' . $via . ' orqali)' : '') . ' — zaxira'); return '';
    }
    $why[] = 'nbu.uz: ' . ($e !== '' ? $e : 'USD kursi topilmadi');
    return 'CBU: javob olinmadi (' . mb_substr(implode(' | ', array_unique(array_filter($why))), 0, 400) . ')';
}
function fetch_all() {
    $err = array();   /* Markaziy bank (cbu.uz) bu versiyada ishlatilmaydi — faqat banklarning olish/sotish kursi */
    try { q("DELETE FROM rates WHERE kind='official'"); } catch (Exception $e) {}
    try { xb_fetch(); } catch (Exception $e) {}
    try { q("DELETE FROM rates WHERE bank LIKE '%NBU%'"); } catch (Exception $e) {}
    setset('last_try', date('Y-m-d H:i:s'));
    if (count($err) < 1) setset('last_ok', date('Y-m-d H:i:s'));
    setset('last_err', implode('; ', $err));
    return $err;
}
/* ---------- Mikrokreditbank: USD olish/sotish kursi bank saytidan avtomatik ---------- */
define('MKB_URLS', "https://mkbank.uz/uz/\nhttps://mkbank.uz/ru/\nhttps://mkbank.uz/");
function mkb_http($url) {
    $c = curl_init($url);
    curl_setopt_array($c, array(CURLOPT_RETURNTRANSFER => 1, CURLOPT_TIMEOUT => 15, CURLOPT_FOLLOWLOCATION => 1, CURLOPT_ENCODING => '',
        CURLOPT_USERAGENT => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36',
        CURLOPT_HTTPHEADER => array('Accept: text/html,application/json;q=0.9,*/*;q=0.8', 'Accept-Language: uz,ru;q=0.8,en;q=0.6')));
    $r = curl_exec($c); $code = (int)curl_getinfo($c, CURLINFO_HTTP_CODE); $err = curl_error($c); curl_close($c);
    if ($r === false || $code >= 400) return array(null, $err !== '' ? $err : 'HTTP ' . $code);
    return array((string)$r, '');
}
function mkb_num($s) {
    $s = preg_replace('/[\s\x{00A0}\x{202F}]/u', '', $s);
    if (preg_match('/^\d{1,2}[.,]\d{3}([.,]\d{1,2})?$/', $s)) $s = preg_replace('/^(\d{1,2})[.,](\d{3})/', '$1$2', $s);   /* 12,950 yoki 12.950 — minglik ajratgich */
    return (float)str_replace(',', '.', $s);
}
/* sahifadan USD qatorini topib, rasmiy kursga yaqin ikkita sonni (olish/sotish) oladi; mos kelmasa — xato matni */
function mkb_parse($html, $ref) {
    $lo = $ref ? $ref * 0.93 : 9000; $hi = $ref ? $ref * 1.07 : 20000;
    $text = html_entity_decode(preg_replace('/<[^>]*>/', ' ', preg_replace('#<(script|style)\b[^>]*>.*?</\1>#si', ' ', $html)), ENT_QUOTES, 'UTF-8');   /* teglar o'rniga bo'shliq: qo'shni raqamlar yopishmasin */
    foreach (array($text, $html) as $src) {
        if (!preg_match_all('/USD|AQSH\s+dollari|Доллар\s+США|US\s+Dollar/iu', $src, $mm, PREG_OFFSET_CAPTURE)) continue;
        foreach ($mm[0] as $m) {
            $win = substr($src, $m[1], 700);
            if (!preg_match_all('/(?<![\d.,])\d{1,2}[\s\x{00A0}\x{202F}.,]?\d{3}(?:[.,]\d{1,2})?(?![\d])/u', $win, $nn)) continue;
            $v = array();
            foreach ($nn[0] as $x) { $f = mkb_num($x); if ($f >= $lo && $f <= $hi) $v[] = $f; if (count($v) === 2) break; }
            if (count($v) < 2) continue;
            $buy = min($v); $sell = max($v);
            if ($sell - $buy <= ($ref ?: 12000) * 0.04) return array($buy, $sell);
        }
    }
    return 'sahifada USD olish/sotish kursi topilmadi';
}
function mkb_state() {
    $r = q("SELECT bank,buy,sell,source,manual,COALESCE(measured_at,fetched_at) AS at FROM rates WHERE cur='USD' AND kind='bank' AND (bank LIKE '%ikrokredit%' OR bank LIKE '%MKB%') LIMIT 1")->fetch();
    return array('on' => setting('mkb_on', '1') === '1', 'urls' => (string)setting('mkb_urls', MKB_URLS), 'int' => (int)setting('mkb_int', '15'),
        'ok_at' => (string)setting('mkb_ok_at', ''), 'err' => (string)setting('mkb_err', ''), 'src' => (string)setting('mkb_src', ''), 'rate' => $r ?: null);
}
function mkb_fetch($force = false) {
    if (!$force && setting('mkb_on', '1') !== '1') return 'o\'chiq';
    if (!$force && time() - (int)setting('mkb_try', '0') < max(5, (int)setting('mkb_int', '15')) * 60) return 'kutish';
    setset('mkb_try', (string)time());
    $ref = q("SELECT official FROM rates WHERE cur='USD' AND kind='official' LIMIT 1")->fetchColumn(); $ref = $ref ? (float)$ref : null;
    $row = q("SELECT bank FROM rates WHERE cur='USD' AND kind='bank' AND (bank LIKE '%ikrokredit%' OR bank LIKE '%MKB%') LIMIT 1")->fetchColumn();
    $name = $row ?: 'Mikrokreditbank'; $last = 'manba ko\'rsatilmagan';
    foreach (preg_split('/\R/', (string)setting('mkb_urls', MKB_URLS)) as $u) {
        $u = trim($u); if (!preg_match('#^https?://#i', $u)) continue;
        list($html, $e) = mkb_http($u); $via = '';   /* asosiy yo'l — asl usul */
        if ($html === null) {
            $last = parse_url($u, PHP_URL_HOST) . ': ' . $e;
            if (isset($rly)) continue; $rly = 1;   /* zaxira: ko'prik orqali (bir marta) */
            list($html, $via, $e2) = relay_get($u); if ($html === null) { $last .= '; ' . $e2; continue; }
        }
        $r = mkb_parse($html, $ref);
        if (is_string($r)) { $last = parse_url($u, PHP_URL_HOST) . ': ' . $r; continue; }
        save_rate('USD', $name, 'bank', $r[0], $r[1], null, $u, 0, date('Y-m-d H:i:s'));
        setset('mkb_ok_at', date('Y-m-d H:i:s')); setset('mkb_err', ''); setset('mkb_src', $u . ($via !== '' ? ' (' . $via . ' orqali)' : ''));
        return 'OK ' . $r[0] . '/' . $r[1];
    }
    setset('mkb_err', date('d.m H:i') . ' — ' . mb_substr($last, 0, 200));
    return 'XATO: ' . $last;
}
