function logo_key($bank) {   /* bank nomi -> logotip kaliti */
    $m = array('mikrokredit|mkb' => 'mkb', 'turon' => 'turon', 'agro' => 'agro', 'apex' => 'apex', 'ipoteka' => 'ipoteka', 'milliy|nbu' => 'nbu', 'tenge' => 'tenge',
        'hamkor' => 'hamkor', 'anor' => 'anor', 'garant' => 'garant', 'hayot' => 'hayot', 'asaka' => 'asaka', 'infin' => 'infin', 'universal' => 'universal',
        'sqb|sanoat' => 'sqb', 'alliance' => 'aab', 'brb|qishloq' => 'brb', 'trast' => 'trast', 'orient' => 'ofb', 'saderat' => 'saderat', 'aloqa' => 'aloqa',
        'davr' => 'davr', 'poytaxt' => 'poytaxt', 'ipak' => 'ipak', 'xalq' => 'xalq', 'octo|ravnaq' => 'octo', 'kapital' => 'kapital', 'kdb' => 'kdb');
    foreach ($m as $re => $k) if (preg_match('/' . $re . '/i', $bank)) return $k;
    return '';
}
function px_logo(&$rows, $H, $x, $y, $bank) {   /* 48x48 logotipni (x,y) chap-yuqori burchakka chizadi; topilmasa false */
    $d = logo_data(); $k = logo_key($bank); if ($k === '' || !isset($d[$k])) return false;
