        if ($b[1] == $bb) $rr(590, $y + 12, 140, 46, 23, $white); if ($b[2] == $bs) $rr(780, $y + 12, 140, 46, 23, $white);
        $T('B30', n0($b[1]), 660, $y + 46, $b[1] == $bb ? array(22, 163, 74) : array(198, 255, 214), 'c');
