/* Kurs imzosi: 'a' — dollar rasmiy kursi + Mikrokreditbank, 'b' — Markaziy bank valyutalari */
function rates_sig($part) {
    $s = '';
    foreach (rates_data() as $r) {
        $o = $r['official'] ? round($r['official']['official'], 2) : '';
        if ($part === 'a' && $r['code'] === 'USD') {
            $s .= 'U' . $o;
            foreach ($r['banks'] as $b) if ($b['src'] !== 'qo\'lda kiritilgan' || preg_match('/mikrokredit|mkb|turon/i', $b['bank'])) $s .= $b['bank'] . round($b['buy'], 2) . '/' . round($b['sell'], 2);
        }
        if ($part === 'b') $s .= $r['code'] . $o;
    }
    return md5($s);
}
/* Kurs postlari faqat narx o'zgarganda: 'a' va 'b' alohida kuzatiladi (vaqt oralig'i bo'yicha yuborilmaydi).
   Yangi ulangan chat birinchi postni darrov oladi; yoqilgan/yangilangan chat avval joriy narxni eslab qoladi. */
/* Telegram aniq «bot chiqarilgan / chat yo'q / huquq yo'q» desa — chat to'xtatiladi (har 5 daqiqada behuda urinmasin; ilovada «Bot administrator emas» ko'rinadi) */
/* ---------- Muammo ogohlantirishi: cron to'xtasa, bank kursi olinmasa, kanal botni chiqarsa — adminlarga darhol xabar ---------- */
function alert_admins($key, $bad, $msg_bad, $msg_ok) {   /* bir muammo haqida 6 soatda bir marta; tiklansa — «tiklandi» */
    if (setting('al_on', '1') !== '1') return;
    $k = 'al_' . $key; $t = (int)setting($k, '0');
    if ($bad) { if (time() - $t >= 6 * 3600) { notify_admins("🚨 " . $msg_bad); setset($k, (string)time()); } }
    elseif ($t) { notify_admins("✅ " . $msg_ok); q('DELETE FROM settings WHERE k=?', array($k)); }
}
function alert_run() {   /* ikkala cron va webhook chaqiradi — bittasi to'xtasa, boshqasi xabar beradi (2 daqiqada bir marta tekshiriladi) */
    if ((int)setting('al_tick', '0') > time() - 120) return; setset('al_tick', (string)time());
    $age = function ($k) { $v = (string)setting($k, ''); return $v === '' ? -1 : time() - strtotime($v); };
    $w = $age('cron_watch_at');   /* hech qachon ishlamagan bo'lsa (cron hali qo'yilmagan) — xabar yo'q */
    if ($w >= 0) alert_admins('cronw', $w > 15 * 60, "Kurs cron'i (har 5 daqiqa) " . round($w / 60) . " daqiqadan beri ishlamayapti — kurslar yangilanmaydi, kanalga kurs xabari ketmaydi.\nHostingdagi Cron'ni tekshiring.", "Kurs cron'i yana ishlayapti.");
    $m = $age('cron_min_at');
    if ($m >= 0) alert_admins('cronm', $m > 10 * 60, "Daqiqalik cron " . round($m / 60) . " daqiqadan beri ishlamayapti — namoz, ob-havo, tongi xabar va bank kurslari to'xtadi.\nHostingdagi Cron'ni tekshiring.", "Daqiqalik cron yana ishlayapti.");
    $L = xb_list(); $st = xb_st(); $bad = array();
    foreach (xb_on() as $id) if (isset($L[$id]) && !empty($st[$id]['err']) && (empty($st[$id]['ok_at']) || strtotime($st[$id]['ok_at']) < time() - 2 * 3600)) $bad[] = $L[$id][0];
    alert_admins('bank', (bool)$bad, "Bank kursi 2 soatdan beri olinmayapti: " . implode(', ', $bad) . "\nAdmin panel → Bank kurslari → «Banklarni tekshirish».", "Bank kurslari yana olinyapti.");
}
function chat_alert($title, $why) {   /* kanal/guruh botni chiqardi yoki huquqini oldi — xabarlar to'xtadi */
    if (setting('al_on', '1') !== '1') return;
    notify_admins("⚠️ " . $title . ": " . $why . " — bu chatga xabarlar to'xtadi.\nBotni qayta administrator qilinsa, o'zi tiklanadi.");
}
function chat_lost($id, $desc) {
    if (preg_match('/kicked|not a member|chat not found|have no rights|not enough rights to send|need administrator rights|CHAT_WRITE_FORBIDDEN|CHAT_ADMIN_REQUIRED|deactivated/i', (string)$desc))
        if (q("UPDATE chats SET status='noperm', auto_on=0 WHERE id=? AND status='approved'", array($id))->rowCount() === 1)
            chat_alert((string)q('SELECT username FROM chats WHERE id=?', array($id))->fetchColumn(), 'bot xabar yubora olmayapti (' . mb_substr((string)$desc, 0, 80) . ')');
}
function cron_post() {
    try { alert_run(); } catch (Exception $e) {}
    $n = 0; $SIG = array('a' => rates_sig('a'));
    foreach (q("SELECT * FROM chats WHERE status='approved' AND blocked=0 AND paused<" . time() . "")->fetchAll() as $c) {
        $new = $c['last_post_at'] === null && !empty($c['auto_on']);
        $set = array('a' => $c['sig_a'], 'b' => $c['sig_b']); $send = array();
        foreach ($SIG as $k => $sig) {
            if (empty($c['auto_on']) || empty($c['send_' . $k])) { $set[$k] = null; continue; }   /* o'chiq: qayta yoqilganda darrov yubormasin */
            if ($new || ($set[$k] !== null && $set[$k] !== $sig)) $send[] = $k;
            $set[$k] = $sig;
        }
        if (!$send) {
            if ($set['a'] !== $c['sig_a'] || $set['b'] !== $c['sig_b']) q('UPDATE chats SET sig_a=?, sig_b=? WHERE id=?', array($set['a'], $set['b'], $c['id']));
            continue;
        }
        $claim = q('UPDATE chats SET last_post_at=NOW(), sig_a=?, sig_b=? WHERE id=? AND (last_post_at IS NULL OR last_post_at <= NOW() - INTERVAL ? MINUTE)',
              array($set['a'], $set['b'], $c['id'], MIN_GAP_MIN));
        if ($claim->rowCount() !== 1) continue;
        $e = send_chat($c, $send);
        q('INSERT INTO post_logs (chat_id,ok,info,at) VALUES (?,?,?,NOW())', array($c['id'], $e === '' ? 1 : 0, $e));
        if ($e !== '') chat_lost($c['id'], $e);
        if ($e !== '') q('UPDATE chats SET last_post_at=?, sig_a=?, sig_b=? WHERE id=?', array($c['last_post_at'], $c['sig_a'], $c['sig_b'], $c['id']));   /* xato: keyingi tickda qayta urinadi */
        $n++; usleep(300000);
    }
    return $n;
}

