function ev_val($k, $d, $def) { $v = setting($k . $d, null); if ($v !== null) return (string)$v; $v = setting($k, null); return $v !== null ? (string)$v : $def; }   /* kunlik qiymat → eski umumiy qiymat → standart */
function ev_item($d = 0) {
