    $vr = ev_val('ev_v', $d, ''); $ar = ev_val('ev_a', $d, '');
    $ref = dp_ref($vr);
    if ($ref) { $p = array('from_chat_id' => $ref[0], 'message_id' => $ref[1]); if ($txt !== '') { $p['caption'] = mb_substr($txt, 0, 1024); $p['parse_mode'] = 'HTML'; } return array('copyMessage', $p, $ar); }
    if ($txt === '') return null;
    return array('sendMessage', array('text' => mb_substr($txt, 0, 4096), 'parse_mode' => 'HTML', 'disable_web_page_preview' => true), $ar);
}
function ev_cfg() {
    global $DAYS;
    $r = array('on' => setting('ev_on', '1') === '1', 'time' => setting('ev_time', '21:30'), 'last' => setting('ev_last', ''),
        'n' => (int)q("SELECT COUNT(*) FROM chats WHERE ev_on=1 AND status='approved' AND blocked=0")->fetchColumn(), 'days' => array());
    foreach ($DAYS as $d => $nm) $r['days'][] = array('d' => $d, 'name' => $nm, 'o' => setting('ev_o' . $d, '1') === '1', 'v' => ev_val('ev_v', $d, ''), 'a' => ev_val('ev_a', $d, ''), 't' => ev_val('ev_t', $d, ev_def($d)));
    return $r;
}
function ev_run() {
    if (setting('ev_on', '1') !== '1') return 'o\'chiq';
    $today = date('Y-m-d'); $start = strtotime($today . ' ' . setting('ev_time', '21:30'));
    if (time() < $start || time() > $start + 2 * 3600) return 0;
    if (setting('ev_o' . date('N'), '1') !== '1') return 0;   /* shu kun o'chirilgan */
    $it = ev_item((int)date('N')); if (!$it) return 0;
    @set_time_limit(120); $n = 0;
    $rows = q("SELECT id,chat_id FROM chats WHERE ev_on=1 AND status='approved' AND blocked=0 AND paused<" . time() . " AND (ev_date IS NULL OR ev_date<?) AND (ev_days IS NULL OR SUBSTRING(ev_days, ?, 1)='1') ORDER BY id LIMIT 100", array($today, (int)date('N')))->fetchAll();
    foreach (array_chunk($rows, 20) as $i => $ch) {
        if ($i) sleep(1);
        $items = array();
        foreach ($ch as $c) if (q('UPDATE chats SET ev_date=? WHERE id=? AND (ev_date IS NULL OR ev_date<?)', array($today, $c['id'], $today))->rowCount() === 1) $items[$c['id']] = array('chat_id' => $c['chat_id']) + $it[1];
        if (!$items) continue;
        foreach (dp_sendi($it, $items) as $id => $r) {
            $ok = !empty($r['ok']);
            q('INSERT INTO post_logs (chat_id,ok,info,at) VALUES (?,?,?,NOW())', array($id, $ok ? 1 : 0, mb_substr('tungi xabar' . ($ok ? '' : ': ' . (isset($r['description']) ? $r['description'] : 'yuborilmadi')), 0, 255)));
            if (!$ok && isset($r['description'])) chat_lost($id, $r['description']);
            if ($ok) $n++;
        }
    }
    if ($n) setset('ev_last', date('d.m H:i'));
    return $n;
}
/* ---------- OB-HAVO OGOHLANTIRISHI: kuchli shamol, jazirama, qattiq sovuq, do'l, kuchli qor/jala — ob-havo yoqilgan chatlarga ---------- */
function wa_run() {
    if (setting('wa_on', '1') !== '1') return 'o\'chiq';
    $today = date('Y-m-d'); if (setting('wa_date', '') === $today) return 0;
    $start = strtotime($today . ' ' . setting('wx_time', '06:00'));
    if (time() < $start + 600 || time() > $start + 4 * 3600) return 0;   /* ob-havo postidan 10 daqiqa keyin */
    if (time() - (int)setting('wa_try', '0') < 900) return 0; setset('wa_try', (string)time());
    global $WX_CITY; $la = array(); $lo = array(); foreach ($WX_CITY as $pp) { $la[] = $pp[0]; $lo[] = $pp[1]; }
    $r = http(setting('wx_api', WX_API) . '?latitude=' . implode(',', $la) . '&longitude=' . implode(',', $lo) . '&daily=weather_code,temperature_2m_max,temperature_2m_min,wind_gusts_10m_max,precipitation_sum,snowfall_sum&wind_speed_unit=ms&timezone=Asia%2FTashkent&forecast_days=1');
    $j = $r ? json_decode($r, true) : null; if (is_array($j) && isset($j['daily'])) $j = array($j); if (!is_array($j)) return 'xato';
    setset('wa_date', $today);
    $A = array('wind' => array(), 'heat' => array(), 'cold' => array(), 'hail' => array(), 'snow' => array(), 'rain' => array()); $i = 0;
    foreach ($WX_CITY as $nm => $pp) {
        $x = isset($j[$i]['daily']) ? $j[$i]['daily'] : array(); $i++;
        $g = isset($x['wind_gusts_10m_max'][0]) ? (float)$x['wind_gusts_10m_max'][0] : 0; $hi = isset($x['temperature_2m_max'][0]) ? (float)$x['temperature_2m_max'][0] : 0; $lo2 = isset($x['temperature_2m_min'][0]) ? (float)$x['temperature_2m_min'][0] : 0;
        $code = isset($x['weather_code'][0]) ? (int)$x['weather_code'][0] : 0; $sn = isset($x['snowfall_sum'][0]) ? (float)$x['snowfall_sum'][0] : 0; $pr = isset($x['precipitation_sum'][0]) ? (float)$x['precipitation_sum'][0] : 0;
        if ($g >= 17) $A['wind'][] = $nm . ' (' . round($g) . ' m/s)';
        if ($hi >= 40) $A['heat'][] = $nm . ' +' . round($hi) . '°';
        if ($lo2 <= -15) $A['cold'][] = $nm . ' ' . round($lo2) . '°';
        if (in_array($code, array(95, 96, 99), true)) $A['hail'][] = $nm;
        if ($sn >= 10) $A['snow'][] = $nm . ' (' . round($sn) . ' sm)';
        elseif ($pr >= 20) $A['rain'][] = $nm . ' (' . round($pr) . ' mm)';
    }
    $L = array('wind' => "🌪 Kuchli shamol", 'heat' => "🥵 Jazirama issiq", 'cold' => "🥶 Qattiq sovuq", 'hail' => "⛈ Momaqaldiroq / do'l", 'snow' => "❄️ Kuchli qor", 'rain' => "🌧 Kuchli jala");
    $t = "⚠️ <b>Ob-havo ogohlantirishi</b> — " . date('d.m.Y') . "\n"; $any = false;
    foreach ($L as $k => $lb) if ($A[$k]) { $t .= "\n" . $lb . ': ' . implode(', ', $A[$k]); $any = true; }
    if (!$any) return 0;
    $t .= "\n\nEhtiyot bo'ling, yaqinlaringizni ham ogohlantiring! 🙏\n#ObHavo #TartibOn"; $n = 0;
    $rows = q("SELECT id,chat_id FROM chats WHERE wx_on=1 AND status='approved' AND blocked=0 AND paused<" . time() . " ORDER BY id LIMIT 300")->fetchAll();
    foreach (array_chunk($rows, 20) as $k2 => $ch) {
        if ($k2) sleep(1); $items = array(); foreach ($ch as $c) $items[$c['id']] = array('chat_id' => $c['chat_id'], 'text' => $t, 'parse_mode' => 'HTML');
        foreach (tg_multi('sendMessage', $items) as $id => $rr) if (!empty($rr['ok'])) $n++; elseif (isset($rr['description'])) chat_lost($id, $rr['description']);
    }
    setset('wa_last', date('d.m H:i') . ' · ' . $n . ' ta chat');
    return $n;
}
/* ---------- 1/24: postni N soatdan keyin o'chirish ---------- */
function autodel_add($chat, $mid, $h) { if ($mid && $h > 0) q('INSERT INTO autodel (chat_id,msg_id,del_at) VALUES (?,?,?)', array($chat, (int)$mid, time() + (int)$h * 3600)); }
function autodel_run() {
    $n = 0; foreach (q('SELECT id, chat_id, msg_id FROM autodel WHERE del_at<=? ORDER BY del_at LIMIT 60', array(time()))->fetchAll() as $r)
        if (q('DELETE FROM autodel WHERE id=?', array($r['id']))->rowCount() === 1) { pr_call('deleteMessage', array('chat_id' => $r['chat_id'], 'message_id' => $r['msg_id'])); $n++; }
    return $n;
}
