function bt_next($k, $from = null) {   /* $from dan boshlab eng yaqin sana (Y-m-d); hijriy bayram sanasi kiritilmagan bo'lsa — '' */
    $BT = $GLOBALS['BT']; $from = $from ?: date('Y-m-d'); $r = $BT[$k][1];
    if ($r === 'fri') { $t = strtotime($from); return date('Y-m-d', date('N', $t) == 5 ? $t : strtotime('next friday', $t)); }
    if ($r === '') { $d = (string)setting('bt_d_' . $k, ''); return $d !== '' && $d >= $from ? $d : ''; }
    $y = (int)substr($from, 0, 4); $d = $y . '-' . $r; return $d >= $from ? $d : ($y + 1) . '-' . $r;
}
function bt_today() {   /* bugun yuboriladigan tabrik: bayram bo'lsa — bayram, aks holda Juma */
    $t = date('Y-m-d'); $j = null;
    foreach ($GLOBALS['BT'] as $k => $x) {
        if (setting('bt_o_' . $k, '1') !== '1' || bt_next($k, $t) !== $t) continue;
        if ($k === 'juma') $j = $k; else return $k;
    }
    return $j;
}
function bt_item($k) {   /* array(metod, parametrlar) — chat_id ni chaqiruvchi qo'shadi */
    $y = (int)date('Y'); $txt = (string)setting('bt_t_' . $k, bt_def($k));
    $txt = trim(strtr($txt, array('{sana}' => date('d.m.Y'), '{bayram}' => $GLOBALS['BT'][$k][0], '{yil}' => $y, '{yosh}' => $y - 1991, '{hijriy}' => strpos($txt, '{hijriy}') !== false ? hijri_today() : '')));
    $ref = dp_ref(setting('bt_v_' . $k, ''));
    if ($ref) {
        $p = array('from_chat_id' => $ref[0], 'message_id' => $ref[1]);
        if ($txt !== '') { $p['caption'] = mb_substr($txt, 0, 1024); $p['parse_mode'] = 'HTML'; }
        return array('copyMessage', $p, (string)setting('bt_a_' . $k, ''));
    }
    if ($txt === '') return null;
    return array('sendMessage', array('text' => mb_substr($txt, 0, 4096), 'parse_mode' => 'HTML', 'disable_web_page_preview' => true), (string)setting('bt_a_' . $k, ''));
}
function bt_cfg() {
    $r = array('on' => setting('bt_on', '1') === '1', 'time' => setting('bt_time', '08:00'), 'last' => setting('bt_last', ''), 'items' => array(),
        'n' => (int)q("SELECT COUNT(*) FROM chats WHERE bt_on=1 AND status='approved' AND blocked=0")->fetchColumn());
    foreach ($GLOBALS['BT'] as $k => $x) $r['items'][] = array('k' => $k, 'name' => $x[0], 'fix' => $x[1], 'next' => bt_next($k), 'o' => setting('bt_o_' . $k, '1') === '1',
        'v' => setting('bt_v_' . $k, ''), 'a' => setting('bt_a_' . $k, ''), 't' => setting('bt_t_' . $k, bt_def($k)), 'd' => setting('bt_d_' . $k, ''));
    return $r;
}
function bt_run() {
    if (setting('bt_on', '1') !== '1') return 'o\'chiq';
    $today = date('Y-m-d'); $start = strtotime($today . ' ' . setting('bt_time', '08:00'));
    if (time() < $start || time() > $start + 3 * 3600) return 0;   /* belgilangan vaqtdan keyin 3 soat ichida */
    $k = bt_today(); if (!$k) return 0; $it = bt_item($k); if (!$it) return 0;
    @set_time_limit(120); $n = 0;
    $rows = q("SELECT id,chat_id FROM chats WHERE bt_on=1 AND status='approved' AND blocked=0 AND paused<" . time() . " AND (bt_date IS NULL OR bt_date<?) ORDER BY id LIMIT 100", array($today))->fetchAll();
    foreach (array_chunk($rows, 20) as $i => $ch) {
        if ($i) sleep(1);
        $items = array();
        foreach ($ch as $c) if (q('UPDATE chats SET bt_date=? WHERE id=? AND (bt_date IS NULL OR bt_date<?)', array($today, $c['id'], $today))->rowCount() === 1) $items[$c['id']] = array('chat_id' => $c['chat_id']) + $it[1];
        if (!$items) continue;
        foreach (dp_sendi($it, $items) as $id => $r) {
            $ok = !empty($r['ok']);
            q('INSERT INTO post_logs (chat_id,ok,info,at) VALUES (?,?,?,NOW())', array($id, $ok ? 1 : 0, mb_substr('bayram tabrigi' . ($ok ? '' : ': ' . (isset($r['description']) ? $r['description'] : 'yuborilmadi')), 0, 255)));
            if (!$ok && isset($r['description'])) chat_lost($id, $r['description']);
            if ($ok) $n++;
        }
    }
    if ($n) setset('bt_last', date('d.m H:i') . ' · ' . $GLOBALS['BT'][$k][0]);
    return $n;
}

/* ---------- OB-HAVO: 12 viloyat markazi bo'yicha kunlik ob-havo (open-meteo.com — bepul, kalitsiz) + kanal/guruhlarga alohida post ---------- */
define('WX_API', 'https://api.open-meteo.com/v1/forecast');
define('WX_WIN_H', 3);   /* belgilangan vaqtdan keyin shuncha soat ichida yuboriladi */
define('DEF_WX_HEAD', "🌤 <b>Bugungi ob-havo</b> — {sana}\nO'zbekiston viloyatlari bo'yicha");
define('DEF_WX_FOOT', "#ObHavo #TartibOn");
$WX_CITY = array(   /* viloyat => array(kenglik, uzunlik) — viloyat markazi shahri */
    'Toshkent' => array(41.311, 69.279), 'Andijon' => array(40.783, 72.344), 'Namangan' => array(40.998, 71.672), 'Farg\'ona' => array(40.384, 71.786),
    'Sirdaryo' => array(40.490, 68.781), 'Jizzax' => array(40.116, 67.842), 'Samarqand' => array(39.654, 66.960), 'Navoiy' => array(40.084, 65.379),
    'Buxoro' => array(39.768, 64.421), 'Qashqadaryo' => array(38.861, 65.790), 'Surxondaryo' => array(37.224, 67.278), 'Xorazm' => array(41.550, 60.631));
function wx_icon($c) {   /* WMO ob-havo kodi => belgi */
    if ($c === 0) return '☀️'; if ($c === 1 || $c === 2) return '🌤'; if ($c === 3) return '☁️'; if ($c === 45 || $c === 48) return '🌫';
    if ($c >= 51 && $c <= 57) return '🌦'; if (($c >= 61 && $c <= 67) || ($c >= 80 && $c <= 82)) return '🌧';
    if (($c >= 71 && $c <= 77) || $c === 85 || $c === 86) return '🌨'; if ($c >= 95) return '⛈'; return '🌡';
}
function wx_desc($c) {
    if ($c === 0) return 'Ochiq'; if ($c === 1 || $c === 2) return 'Biroz bulutli'; if ($c === 3) return 'Bulutli'; if ($c === 45 || $c === 48) return 'Tuman';
    if ($c >= 51 && $c <= 57) return 'Shivalama'; if (($c >= 61 && $c <= 67) || ($c >= 80 && $c <= 82)) return 'Yomg\'ir';
    if (($c >= 71 && $c <= 77) || $c === 85 || $c === 86) return 'Qor'; if ($c >= 95) return 'Momaqaldiroq'; return '';
}
function wx_t($v) { $v = (int)$v; return ($v > 0 ? '+' : '') . $v . '°'; }
/* Bugungi ma'lumot: kuniga bir marta olinadi, xato bo'lsa 3 daqiqadan keyin qayta urinadi. Olinmasa null */
function wx_data() {
    global $WX_CITY;
    $today = date('Y-m-d'); $c = json_decode((string)setting('wx_cache', ''), true);
    if (is_array($c) && isset($c['d'], $c['rows']) && $c['d'] === $today) return $c['rows'];
    if (time() - (int)setting('wx_try', '0') < 180) return null;
    setset('wx_try', time());
    $la = array(); $lo = array(); foreach ($WX_CITY as $p) { $la[] = $p[0]; $lo[] = $p[1]; }
    $r = http(setting('wx_api', WX_API) . '?latitude=' . implode(',', $la) . '&longitude=' . implode(',', $lo) . '&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=Asia%2FTashkent&forecast_days=1');
    $j = $r ? json_decode($r, true) : null; if (is_array($j) && isset($j['daily'])) $j = array($j);
    $rows = array(); $i = 0;
    foreach ($WX_CITY as $nm => $p) {
        $x = isset($j[$i]['daily']) ? $j[$i]['daily'] : null; $i++;
        if (!$x || !isset($x['temperature_2m_min'][0], $x['temperature_2m_max'][0])) return null;
        $code = isset($x['weather_code'][0]) ? (int)$x['weather_code'][0] : -1;
        $rows[] = array('n' => $nm, 'c' => $code, 'i' => wx_icon($code), 'd' => wx_desc($code), 'lo' => (int)round($x['temperature_2m_min'][0]), 'hi' => (int)round($x['temperature_2m_max'][0]),
            'p' => isset($x['precipitation_probability_max'][0]) ? (int)$x['precipitation_probability_max'][0] : null);
    }
    setset('wx_cache', json_encode(array('d' => $today, 'rows' => $rows), JSON_UNESCAPED_UNICODE));
    return $rows;
}
function wx_cap() {
    $sana = array('{sana}' => date('d.m.Y'));
    $h = trim(strtr((string)setting('wx_head', DEF_WX_HEAD), $sana)); $f = trim(strtr((string)setting('wx_foot', DEF_WX_FOOT), $sana));
    return mb_substr(trim($h . ($h !== '' && $f !== '' ? "\n\n" : '') . $f), 0, 1024);
}
/* Ob-havo belgisi (rasm uchun, emoji o'rniga chiziladi) */
function png_wx_icon($t, $c, $cx, $cy) {
    $dot = $t['dot']; $rr = $t['rr']; $tri = $t['tri'];
    $sun = array(255, 184, 28); $lt = array(196, 205, 222); $dk = array(150, 162, 186); $bl = array(47, 124, 246);
    $cloud = function ($x, $y, $col) use ($dot, $rr) { $dot($x - 9, $y + 2, 11, $col); $dot($x + 5, $y - 4, 14, $col); $rr($x - 20, $y + 2, 40, 12, 6, $col); };
    $sunf = function ($x, $y, $r) use ($dot, $sun) { for ($i = 0; $i < 8; $i++) { $a = $i * M_PI / 4; $dot($x + cos($a) * ($r + 7), $y + sin($a) * ($r + 7), 2.6, $sun); } $dot($x, $y, $r, $sun); };
    if ($c === 0) { $sunf($cx, $cy, 12); return; }
    if ($c === 1 || $c === 2) { $sunf($cx - 7, $cy - 7, 9); $cloud($cx + 4, $cy + 6, $lt); return; }
    if ($c === 45 || $c === 48) { foreach (array(-10, 0, 10) as $k => $o) $rr($cx - 18 + $k * 3, $cy + $o - 3, 36 - $k * 6, 6, 3, $dk); return; }
    if ($c === 3 || $c < 0) { $cloud($cx, $cy, $c === 3 ? $dk : $lt); return; }
    $cloud($cx, $cy - 6, $dk);
    if ($c >= 95) { $tri($cx - 8, $cy + 17, false, $sun, 0.8); return; }
    if (($c >= 71 && $c <= 77) || $c === 85 || $c === 86) { foreach (array(-11, 0, 11) as $o) $dot($cx + $o, $cy + 17, 3.2, array(120, 170, 240)); return; }
    if ($c >= 51 && $c <= 57) { foreach (array(-6, 6) as $o) $dot($cx + $o, $cy + 16, 2.6, $bl); return; }
    foreach (array(-11, 0, 11) as $o) $rr($cx + $o - 1.5, $cy + 11, 3, 10, 1.5, $bl);
}
function png_weather($R) {
    $W = 1000; $CW = 428; $CH = 104; $G = 16; $H = 236 + (int)ceil(count($R) / 2) * ($CH + $G) + 86;
    $rows = array_fill(0, $H, str_repeat(chr(239) . chr(239) . chr(244), $W));
    $t = px_tools($rows, $W, $H); $rr = $t['rr']; $T = $t['T']; $dot = $t['dot'];
    $navy = array(15, 27, 61); $gray = array(123, 136, 168); $blue = array(47, 124, 246); $bg = array(241, 243, 248);
    $deg = function ($x, $y, $r, $c) use ($dot, $bg) { $dot($x, $y, $r, $c); $dot($x, $y, $r * 0.5, $bg); };
    $rr(24, 24, 952, $H - 48, 44, array(255, 255, 255));
    $T('IM24', 'OB-HAVO  ·  ' . date('d.m.Y'), 64, 96, $gray);
    $T('IB58', 'Bugungi ob-havo', 64, 168, $navy);
    $rr(64, 190, 96, 7, 3, $blue);
    foreach ($R as $i => $x) {
        $x0 = 64 + ($i % 2) * ($CW + $G); $y0 = 226 + intdiv($i, 2) * ($CH + $G);
        $rr($x0, $y0, $CW, $CH, 24, $bg);
        png_wx_icon($t, isset($x['c']) ? (int)$x['c'] : -1, $x0 + 44, $y0 + 50);
        $T('IS30', $x['n'], $x0 + 86, $y0 + 48, array(51, 61, 88));
        $T('IM24', $x['d'], $x0 + 86, $y0 + 82, $gray);
        $xr = $x0 + $CW - 28;   /* kunduzgi (katta) va tungi (kichik) harorat — ustma-ust, uzun nomlarga tegmaydi */
        $T('IB40', (string)$x['hi'], $xr - 16, $y0 + 56, $navy, 'r'); $deg($xr - 7, $y0 + 29, 6, $navy);
        $T('IM24', 'tunda ' . $x['lo'], $xr - 12, $y0 + 86, $gray, 'r'); $deg($xr - 5, $y0 + 69, 3.6, $gray);
    }
    $T('IM24', "O'zbekiston viloyatlari bo'yicha", 64, $H - 54, $gray);
    px_stamp($t, 920, $H - 40);
    return px_png($rows, $W, $H);
}
/* Rasmni yuborish: birinchisi yuklanadi, keyingilariga file_id; HTML xato bo'lsa oddiy matn bilan qayta */
function wx_photo($chat, $png, $cap, &$fid) {
    $send = function ($cp, $pm) use ($chat, $png, &$fid) {
        $r = $fid ? pr_call('sendPhoto', array('chat_id' => $chat, 'photo' => $fid) + ($cp !== '' ? array('caption' => $cp) + ($pm ? array('parse_mode' => 'HTML') : array()) : array()))
            : tg_photo($chat, $png, $cp, 'png', $pm ? 'HTML' : '');
        if (!empty($r['ok']) && !$fid && !empty($r['result']['photo'])) { $p = end($r['result']['photo']); $fid = $p['file_id']; }
        return $r;
    };
    $r = $send($cap, true);
    if (empty($r['ok']) && isset($r['description']) && stripos($r['description'], 'parse entities') !== false) $r = $send(html_entity_decode(strip_tags($cap), ENT_QUOTES, 'UTF-8'), false);
    return $r;
}
function wx_cfg() {
    return array('on' => setting('wx_on', '1') === '1', 'time' => setting('wx_time', '07:00'), 'head' => setting('wx_head', DEF_WX_HEAD), 'foot' => setting('wx_foot', DEF_WX_FOOT),
        'last' => setting('wx_last', ''), 'n' => (int)q("SELECT COUNT(*) FROM chats WHERE wx_on=1 AND status='approved' AND blocked=0")->fetchColumn());
}
function cron_weather() {
    if (setting('wx_on', '1') !== '1') return 0;
    $today = date('Y-m-d'); $start = strtotime($today . ' ' . setting('wx_time', '07:00'));
    if (time() < $start || time() > $start + WX_WIN_H * 3600) return 0;
    $rows = q("SELECT id,chat_id,owner FROM chats WHERE wx_on=1 AND status='approved' AND blocked=0 AND paused<" . time() . " AND (wx_date IS NULL OR wx_date<?) ORDER BY id LIMIT 100", array($today))->fetchAll();
    if (!$rows) return 0;
    $d = wx_data(); if (!$d) return 'kutilmoqda';   /* API javob bermadi — keyingi daqiqalarda qayta */
    $png = png_weather($d); $cap = wx_cap(); $fid = null; $n = 0; @set_time_limit(120);
    foreach ($rows as $c) {
        if (q('UPDATE chats SET wx_date=? WHERE id=? AND (wx_date IS NULL OR wx_date<?)', array($today, $c['id'], $today))->rowCount() !== 1) continue;
        $r = wx_photo($c['chat_id'], $png, owner_cap($c['owner'], 'w', $cap, array('{sana}' => date('d.m.Y'))), $fid); $ok = !empty($r['ok']);
        q('INSERT INTO post_logs (chat_id,ok,info,at) VALUES (?,?,?,NOW())', array($c['id'], $ok ? 1 : 0, mb_substr('ob-havo' . ($ok ? '' : ': ' . (isset($r['description']) ? $r['description'] : 'yuborilmadi')), 0, 255)));
        if (!$ok && isset($r['description'])) chat_lost($c['id'], $r['description']);
        if ($ok) $n++;
        usleep(200000);
    }
    if ($n) setset('wx_last', date('Y-m-d H:i'));
    return $n;
}

/* ---------- KROSSVORD VIKTORINA: guruhga savol + javob kataklari, birinchi to'g'ri javobga ochko, reyting ---------- */
/* Vaqtlar unix soniyada saqlanadi (PHP va MySQL vaqt zonalari farq qilsa ham hisob buzilmaydi). Bir guruhda bir vaqtda bitta faol savol: UNIQUE(chat_id, act). */
$QZ_SUBJ = array();   /* eski tekis fanlar ro'yxati — endi bo'limlar daraxti: quiz_tree() */
define('QZ_ANS_MAX', 64);   /* bundan uzun xabarlar javob sifatida ko'rilmaydi */
function quiz_install() {
    db()->exec("CREATE TABLE IF NOT EXISTS quiz_questions (id INT AUTO_INCREMENT PRIMARY KEY, cat VARCHAR(80) NOT NULL DEFAULT '', subject VARCHAR(120) NOT NULL, level TINYINT NOT NULL DEFAULT 1, question TEXT NOT NULL, answer VARCHAR(100) NOT NULL,
        alts TEXT NULL, opts TEXT NULL, note VARCHAR(500) NOT NULL DEFAULT '', letters SMALLINT NOT NULL DEFAULT 0, qhash CHAR(32) NOT NULL, used INT NOT NULL DEFAULT 0, created_at INT NOT NULL DEFAULT 0,
        UNIQUE KEY uq_hash (qhash), KEY k_subj (subject), KEY k_cat (cat)) DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS quiz_settings (chat_id BIGINT NOT NULL PRIMARY KEY, enabled TINYINT NOT NULL DEFAULT 0, subject VARCHAR(40) NOT NULL DEFAULT '', interval_min INT NOT NULL DEFAULT 10,
        answer_sec INT NOT NULL DEFAULT 60, points INT NOT NULL DEFAULT 10, next_at INT NOT NULL DEFAULT 0, last_err VARCHAR(255) NOT NULL DEFAULT '', updated_at INT NOT NULL DEFAULT 0) DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS quiz_sessions (id INT AUTO_INCREMENT PRIMARY KEY, chat_id BIGINT NOT NULL, question_id INT NOT NULL, subject VARCHAR(40) NOT NULL, message_id BIGINT NULL, points INT NOT NULL,
        started_at INT NOT NULL, ends_at INT NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'active', act TINYINT NULL DEFAULT 1, winner_id BIGINT NULL, winner_name VARCHAR(128) NULL, won_at INT NULL, finished_at INT NULL,
        UNIQUE KEY uq_act (chat_id, act), KEY k_st (status, ends_at), KEY k_chat (chat_id, id)) DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS quiz_participants (chat_id BIGINT NOT NULL, user_id BIGINT NOT NULL, name VARCHAR(128) NOT NULL DEFAULT '', username VARCHAR(64) NOT NULL DEFAULT '',
        points INT NOT NULL DEFAULT 0, correct INT NOT NULL DEFAULT 0, answered INT NOT NULL DEFAULT 0, win_at INT NULL, last_at INT NOT NULL DEFAULT 0,
        PRIMARY KEY (chat_id, user_id), KEY k_rank (chat_id, points), KEY k_user (user_id)) DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS quiz_answers (id INT AUTO_INCREMENT PRIMARY KEY, session_id INT NOT NULL, chat_id BIGINT NOT NULL, user_id BIGINT NOT NULL, answer VARCHAR(100) NOT NULL DEFAULT '',
        tries INT NOT NULL DEFAULT 1, correct TINYINT NOT NULL DEFAULT 0, points INT NOT NULL DEFAULT 0, at INT NOT NULL,
        UNIQUE KEY uq_su (session_id, user_id), KEY k_chat_at (chat_id, at), KEY k_at (at), KEY k_user (user_id)) DEFAULT CHARSET=utf8mb4");
    if (!(int)q('SELECT COUNT(*) FROM quiz_questions')->fetchColumn()) quiz_seed();
}
