/* ---------- DAROMAD VA XAVFSIZLIK: pullik kanal, promo-kod, reklama birjasi, reyting, to'lov cheki, monitoring, 2FA ---------- */
function promo_get($code, $uid, $what) {   /* [foiz, xato] — $what: 'ads' | 'auc' | 'boost' */
    $code = strtoupper(trim((string)$code)); if ($code === '') return array(0, '');
    $p = q('SELECT * FROM promo_codes WHERE code=?', array($code))->fetch();
    if (!$p || ($p['until'] && (int)$p['until'] < time())) return array(0, 'Promo-kod topilmadi yoki muddati tugagan');
    if ($p['scope'] !== 'all' && $p['scope'] !== $what) return array(0, 'Bu promo-kod bu xizmatga amal qilmaydi');
    if ($p['max_uses'] && (int)$p['used'] >= (int)$p['max_uses']) return array(0, 'Promo-kod limiti tugagan');
    if (q('SELECT 1 FROM promo_uses WHERE code=? AND user_id=?', array($code, $uid))->fetchColumn()) return array(0, 'Siz bu promo-koddan foydalangansiz');
    return array((int)$p['pct'], '');
}
function promo_use($code, $uid) {
    $code = strtoupper(trim((string)$code)); if ($code === '') return;
    if (q('INSERT IGNORE INTO promo_uses (code,user_id,at) VALUES (?,?,?)', array($code, $uid, time()))->rowCount()) q('UPDATE promo_codes SET used=used+1 WHERE code=?', array($code));
}
function pay_from($uid, $sum) { $ok = q('UPDATE users SET balance=balance-? WHERE id=? AND balance>=?', array($sum, $uid, $sum))->rowCount() === 1; if ($ok) bal_low_later($uid); return $ok; }

/* ---------- TO'LOV CHEGARALARI ---------- */
function bal_contact() { $v = trim((string)setting('bal_contact', '')); return $v !== '' ? $v : trim((string)setting('support_user', '')); }
function pay_set($k, $d = '') { return trim((string)setting($k, $d)); }
function pay_min() { return max(1000, (int)setting('pay_amin', (string)PAY_MIN)); }
function pay_max() { return min(100000000, max(pay_min(), (int)setting('pay_amax', (string)PAY_MAX))); }
function pay_ms() { return (int)round(microtime(true) * 1000); }
function pay_log($p, $req, $res) {
    try {
        q('INSERT INTO pay_log (prov,req,res,at) VALUES (?,?,?,NOW())', array($p, mb_substr((string)$req, 0, 1500), mb_substr((string)$res, 0, 1000)));
        if (mt_rand(1, 40) === 1) q('DELETE FROM pay_log WHERE at < NOW() - INTERVAL 30 DAY');
    } catch (Exception $e) {}
}
/* To'lov muvaffaqiyatli bo'lganda balansga bir marta qo'shish. Qaytaradi: true (hozir qo'shildi) / false (allaqachon yoki mumkin emas) */
/* ---------- NAKRUTKA: prm4u.com (SMM panel, API v2) orqali obunachi / ko'rish / reaksiya ---------- */
function nk_cfg() {
    $u = defined('NK_API_URL') ? (string)NK_API_URL : (string)setting('nk_url', 'https://prm4u.com/api/v2');
    $k = defined('NK_API_KEY') ? (string)NK_API_KEY : (string)setting('nk_key', '');
    return array(trim($u), trim($k));
}
function nk_url_ok($u) { return (bool)preg_match('~^(https://[A-Za-z0-9.-]+(:\d+)?(/\S*)?|http://(127\.0\.0\.1|localhost)(:\d+)?(/\S*)?)$~', $u); }
/* Provayderga so'rov. sure=true — so'rov provayderga yetib bormagani/aniq rad etilgani; sure=false — natija noma'lum (tarmoq uzilishi, 5xx) */
function nk_call($p, $t = 25) { $r = nk_call_raw($p, $t); if (isset($p['action']) && $p['action'] === 'add') sec_health('nk', !sec_fail_nk($r), isset($r['err']) ? (string)$r['err'] : ''); return $r; }
function nk_call_raw($p, $t = 25) {
    $c = nk_cfg();
    if ($c[1] === '') return array('ok' => false, 'err' => 'API kalit kiritilmagan', 'sure' => true);
    if (!nk_url_ok($c[0])) return array('ok' => false, 'err' => 'API manzil noto\'g\'ri (https:// bilan boshlanishi kerak)', 'sure' => true);
    $p['key'] = $c[1];
    $ch = curl_init($c[0]);
    curl_setopt_array($ch, array(CURLOPT_RETURNTRANSFER => 1, CURLOPT_POST => 1, CURLOPT_POSTFIELDS => http_build_query($p), CURLOPT_TIMEOUT => $t, CURLOPT_CONNECTTIMEOUT => 10, CURLOPT_FOLLOWLOCATION => 0, CURLOPT_USERAGENT => 'Mozilla/5.0 TartibOn', CURLOPT_SSL_VERIFYPEER => 1));
    $r = curl_exec($ch); $no = curl_errno($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
    if ($no !== 0 || $r === false) return array('ok' => false, 'err' => 'Provayder bilan aloqa yo\'q', 'sure' => in_array($no, array(6, 7, 35, 51, 58, 60, 77), true));
    $j = json_decode($r, true);
    if ($j === null) return array('ok' => false, 'err' => 'Provayder javobi tushunarsiz (HTTP ' . $code . ')', 'sure' => $code >= 400 && $code < 500);
    if (is_array($j) && isset($j['error'])) return array('ok' => false, 'err' => mb_substr(trim(strip_tags((string)$j['error'])), 0, 160), 'sure' => true);
    return array('ok' => true, 'j' => $j);
}
function nk_usd() {
    $m = (float)setting('nk_usd', '0'); if ($m > 0) return $m;
    try { $r = (float)q("SELECT MAX(sell) FROM rates WHERE cur='USD' AND kind='bank'")->fetchColumn(); } catch (Exception $e) { $r = 0; }
    return $r > 1000 ? $r : 0;
}
function nk_mk($s) { return ($s['mk'] !== null && $s['mk'] !== '') ? (float)$s['mk'] : (float)setting('nk_mk', '40'); }
function nk_p1000($s, $uid = 0) { $u = nk_usd(); if ($u <= 0) return 0; return (int)(ceil((float)$s['rate'] * $u * (1 + nk_mku($s, $uid) / 100) / 10) * 10); }
function nk_price($s, $qty, $uid = 0) { $u = nk_usd(); if ($u <= 0) return 0; return max(100, (int)(ceil((float)$s['rate'] / 1000 * $qty * $u * (1 + nk_mku($s, $uid) / 100) * (1 - nk_disc($qty) / 100) / 10) * 10)); }
function nk_plats() {
    /* kod => [nom, ruxsat etilgan domenlar, @username shabloni (regex), havola shabloni, faqat @bilan] */
    return array(
        'tg' => array('✈️ Telegram', array('t.me', 'telegram.me', 'telegram.dog'), '/^[A-Za-z][A-Za-z0-9_]{3,31}$/', 'https://t.me/%s', false),
        'ig' => array('📸 Instagram', array('instagram.com'), '/^[A-Za-z0-9._]{1,30}$/', 'https://www.instagram.com/%s/', false),
        'yt' => array('▶️ YouTube', array('youtube.com', 'youtu.be'), '/^[A-Za-z0-9._-]{3,40}$/', 'https://www.youtube.com/@%s', true),
        'tt' => array('🎵 TikTok', array('tiktok.com', 'vm.tiktok.com', 'vt.tiktok.com'), '/^[A-Za-z0-9._]{2,24}$/', 'https://www.tiktok.com/@%s', false),
        'fb' => array('👍 Facebook', array('facebook.com', 'fb.com', 'fb.watch'), '/^[A-Za-z0-9.]{5,50}$/', 'https://www.facebook.com/%s', false),
        'x'  => array('𝕏 Twitter', array('x.com', 'twitter.com'), '/^[A-Za-z0-9_]{1,15}$/', 'https://x.com/%s', false),
        'th' => array('🧵 Threads', array('threads.net', 'threads.com'), '/^[A-Za-z0-9._]{1,30}$/', 'https://www.threads.net/@%s', false),
        'vk' => array('🔷 VK', array('vk.com', 'vk.ru'), '/^[A-Za-z0-9._]{3,32}$/', 'https://vk.com/%s', false),
        'sp' => array('🎧 Spotify', array('open.spotify.com', 'spotify.com'), '', '', false),
        'tw' => array('🎮 Twitch', array('twitch.tv'), '/^[A-Za-z0-9_]{4,25}$/', 'https://www.twitch.tv/%s', false),
    );
}
function nk_link($plat, $raw) {
    $P = nk_plats(); if (!isset($P[$plat])) return false;
    if (!is_scalar($raw)) return false;
    $raw = trim((string)$raw); if ($raw === '' || mb_strlen($raw) > 300 || preg_match('/\s/u', $raw)) return false;
    if ($raw[0] === '@' || !preg_match('~^https?://~i', $raw)) {
        $n = ltrim($raw, '@'); $c = $P[$plat];
        if ($c[2] !== '' && (!$c[4] || $raw[0] === '@') && preg_match($c[2], $n)) return sprintf($c[3], $n);
        return false;
    }
    $h = parse_url($raw, PHP_URL_HOST); if (!$h) return false; $h = preg_replace('/^(www|m)\./', '', strtolower($h));
    return in_array($h, $P[$plat][1], true) ? $raw : false;
}
function nk_st($ps) {
    $s = strtolower(trim((string)$ps));
    if ($s === 'completed') return 'done';
    if ($s === 'partial') return 'part';
    if (in_array($s, array('canceled', 'cancelled', 'refunded', 'fail', 'failed', 'error'), true)) return 'cancel';
    return 'wait';
}
/* ---------- XAVFSIZLIK VA BARQARORLIK: tezlik chegarasi, provayder holati, qaytarish nazorati, zaxira nusxa, tozalash ---------- */
function sec_conf() {
    static $c = null;
    if ($c === null) {
        $c = array('wl' => array(), 'rl' => 120, 'slow' => 700);
        try { foreach (q("SELECT k,v FROM settings WHERE k IN ('sec_wl','sec_rl','sec_slow')")->fetchAll() as $r) { if ($r['k'] === 'sec_rl') $c['rl'] = max(30, min(5000, (int)$r['v'])); elseif ($r['k'] === 'sec_slow') $c['slow'] = max(20, (int)$r['v']); else foreach (explode(',', (string)$r['v']) as $x) { $x = (int)trim($x); if ($x > 0) $c['wl'][$x] = 1; } } } catch (Exception $e) {}
    }
    return $c;
}
function sec_trusted($uid) { $c = sec_conf(); return isset($c['wl'][(int)$uid]) || is_admin($uid); }
/* Bir foydalanuvchi daqiqasiga sec_rl tadan ko'p so'rov yubora olmaydi (bot/hujumdan himoya) */
function sec_rate($uid) {
    if (sec_trusted($uid)) return;
    $w = (int)floor(time() / 60); $n = 0;
    try {
        q('INSERT INTO sec_rl (uid,w,n) VALUES (?,?,1) ON DUPLICATE KEY UPDATE n=n+1', array($uid, $w));
        $n = (int)q('SELECT n FROM sec_rl WHERE uid=? AND w=?', array($uid, $w))->fetchColumn();
        if (mt_rand(1, 300) === 1) q('DELETE FROM sec_rl WHERE w < ?', array($w - 5));
    } catch (Exception $e) { return; }
    if ($n > sec_conf()['rl']) { header('Retry-After: 30'); out(array('ok' => false, 'error' => 'Juda ko\'p so\'rov. Bir oz kutib, qayta urinib ko\'ring'), 429); }
}
function sec_aud($uid, $act, $det) { try { q('INSERT INTO audit_logs (admin,action,detail,at) VALUES (?,?,?,NOW())', array($uid, mb_substr($act, 0, 40), mb_substr($det, 0, 480))); } catch (Exception $e) {} }
/* Admin harakatlari jurnali: o'qish emas, o'zgartirish so'rovlari; maxfiy maydonlar yozilmaydi */
function sec_audit_req($uid, $a, $in) {
    if ($_SERVER['REQUEST_METHOD'] !== 'POST' || preg_match('/(get|list|find|view|stats?|log|search|balance|sync|load|info)$/i', $a)) return;
    $d = array(); foreach ($in as $k => $v) { if (preg_match('/key|token|pass|secret|pin|hash/i', (string)$k)) { $d[$k] = '***'; continue; } $d[$k] = is_scalar($v) ? mb_substr((string)$v, 0, 60) : '[…]'; }
    sec_aud($uid, 'a:' . $a, json_encode($d, JSON_UNESCAPED_UNICODE));
}
/* ---- provayder holati: ketma-ket 3 ta xatodan keyin xizmat 10 daqiqaga o'zi to'xtaydi ---- */
function sec_pname($p) { return $p === 'nk' ? 'Nakrutka (prm4u)' : 'eSIM (5sim)'; }
function sec_health($p, $ok, $err = '') {
    $fk = 'sh_' . $p . '_f'; $uk = 'sh_' . $p . '_u'; $nk = 'sh_' . $p . '_n';
    try {
        if ($ok) {
            if ((int)setting($fk, '0') > 0) { setset($fk, '0'); setset($uk, '0'); }
            if (setting($nk, '') === '1') { setset($nk, '0'); notify_admins('✅ ' . sec_pname($p) . ' provayderi qayta ishlayapti — xizmat yoqildi.'); }
            return;
        }
        $n = (int)setting($fk, '0') + 1; setset($fk, (string)$n);
        if ($n >= 3) {
            setset($uk, (string)(time() + 600));
            if (setting($nk, '') !== '1') { setset($nk, '1'); notify_admins('⛔ ' . sec_pname($p) . ': provayder ketma-ket ' . $n . ' marta xato berdi — xizmat 10 daqiqaga avtomatik to\'xtatildi (' . mb_substr($err, 0, 120) . '). Provayder hisobi va API kalitni tekshiring. Admin → 🛡 Xavfsizlik bo\'limidan qayta yoqish mumkin.'); }
        }
    } catch (Exception $e) {}
}
function sec_fail_nk($r) { return empty($r['ok']) && preg_match('/aloqa yo|tushunarsiz|kalit|fund|balance|credit|money|auth|denied|forbidden|not enough|insufficient|api key|invalid key/i', isset($r['err']) ? $r['err'] : ''); }
function sec_fail_sm($r) {
    if (!empty($r['ok'])) return false;
    $code = isset($r['code']) ? (int)$r['code'] : 0;
    return $code === 0 || $code >= 500 || $code === 401 || $code === 403 || preg_match('/not enough user balance|balance|aloqa|tushunarsiz/i', (isset($r['err']) ? $r['err'] : '') . ' ' . (isset($r['body']) ? $r['body'] : ''));
}
function sec_down($p) { return (int)setting('sh_' . $p . '_u', '0') > time(); }
/* [ochiqmi, mijozga ko'rinadigan xabar] */
function sec_svc($p) {
    if (setting('sv_' . $p . '_off', '0') === '1') { $m = trim((string)setting('sv_' . $p . '_msg', '')); return array(false, $m !== '' ? $m : 'Xizmat vaqtincha to\'xtatilgan'); }
    if (sec_down($p)) return array(false, 'Provayder bilan aloqa vaqtincha uzilgan, tez orada tiklanadi. Hozircha buyurtma berib bo\'lmaydi, pulingiz yechilmaydi.');
    return array(true, '');
}
/* eSIMni qayta-qayta olib bekor qiladiganlar: 24 soatda sec_vs_abuse tadan ko'p bekor bo'lsa, vaqtincha cheklanadi */
function sec_vs_abuse($uid) {
    if (sec_trusted($uid)) return false;
    $lim = max(2, (int)setting('sec_vs_abuse', '5'));
    $n = (int)q("SELECT COUNT(*) FROM vs_ord WHERE uid=? AND st='cancel' AND err NOT LIKE 'Provayder%' AND err<>'Almashtirildi' AND created > NOW() - INTERVAL 24 HOUR", array($uid))->fetchColumn();
    if ($n < $lim) return false;
    $k = 'sec_ab_' . $uid . '_' . date('Ymd');
    if (setting($k, '') !== '1') { setset($k, '1'); notify_admins('🚨 eSIM: foydalanuvchi ' . $uid . ' 24 soatda ' . $n . ' ta raqamni bekor qildi/ishlatmadi — 24 soatga cheklandi. Zarur bo\'lsa Admin → 🛡 Xavfsizlik → oq ro\'yxatga qo\'shing.'); }
    return true;
}
/* ---- zaxira nusxa: toza PHP bilan SQL (gzip), serverda 7 ta saqlanadi; Telegramga maxfiy kalitlarsiz nusxa ---- */
function sec_bk_dir() {
    $d = __DIR__ . '/backups';
    if (!is_dir($d)) @mkdir($d, 0755, true);
    if (is_dir($d) && !is_file($d . '/.htaccess')) { @file_put_contents($d . '/.htaccess', "<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n<IfModule !mod_authz_core.c>\nDeny from all\n</IfModule>\n"); @file_put_contents($d . '/index.html', ''); }
    return $d;
}
function sec_dump($path, $mask) {
    if (!function_exists('gzopen')) return false;
    $gz = @gzopen($path, 'wb6'); if (!$gz) return false;
    $pdo = db(); @set_time_limit(180);
    gzwrite($gz, "-- TartibOn zaxira nusxasi " . date('Y-m-d H:i:s') . "\nSET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n");
    foreach ($pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN) as $t) {
        if (!preg_match('/^[A-Za-z0-9_]+$/', $t) || $t === 'sec_rl') continue;
        $cr = $pdo->query('SHOW CREATE TABLE `' . $t . '`')->fetch(PDO::FETCH_NUM);
        gzwrite($gz, "DROP TABLE IF EXISTS `$t`;\n" . $cr[1] . ";\n");
        for ($off = 0; ; $off += 400) {
            $rows = $pdo->query('SELECT * FROM `' . $t . '` LIMIT 400 OFFSET ' . $off)->fetchAll(PDO::FETCH_ASSOC);
            if (!$rows) break;
            $cols = '`' . implode('`,`', array_keys($rows[0])) . '`'; $vals = array();
            foreach ($rows as $r) {
                if ($mask && $t === 'settings' && preg_match('/key|token|secret|pass|pin/i', (string)$r['k'])) $r['v'] = '';
                $vals[] = '(' . implode(',', array_map(function ($v) use ($pdo) { if ($v === null) return 'NULL'; $v = (string)$v; return mb_check_encoding($v, 'UTF-8') ? $pdo->quote($v) : '0x' . bin2hex($v); }, $r)) . ')';
            }
            gzwrite($gz, 'INSERT INTO `' . $t . '` (' . $cols . ') VALUES ' . implode(",\n", $vals) . ";\n");
            if (count($rows) < 400) break;
        }
    }
    gzwrite($gz, "SET FOREIGN_KEY_CHECKS=1;\n"); gzclose($gz);
    return true;
}
function sec_bk_files() {
    $o = array(); $d = sec_bk_dir();
    foreach (glob($d . '/tb_*.sql.gz') ?: array() as $f) $o[] = array('name' => basename($f), 'size' => (int)filesize($f), 'at' => date('d.m H:i', filemtime($f)), 't' => filemtime($f));
    usort($o, function ($a, $b) { return $b['t'] - $a['t']; });
    return $o;
}
function sec_backup_run($force = false) {
    $day = date('Ymd');
    if (!$force) {
        if (setting('sec_bk_on', '1') !== '1') return 'o\'chiq';
        if ((int)date('G') < 3 || setting('sec_bk_day', '') === $day) return 0;
    }
    if (!(int)q("SELECT GET_LOCK('kp_bk', 0)")->fetchColumn()) return 'band';
    $res = 'xato';
    try {
        setset('sec_bk_day', $day);
        $d = sec_bk_dir(); $f = $d . '/tb_' . date('Ymd_His') . '_' . bin2hex(random_bytes(4)) . '.sql.gz';
        if (!sec_dump($f, false)) { setset('sec_bk_info', 'Xato: zaxira yaratilmadi (zlib/ruxsat)'); notify_admins('⚠️ Zaxira nusxa olinmadi (zlib yoki papka ruxsati). Hosting yordamiga murojaat qiling.'); $res = 'xato'; }
        else {
            $fs = sec_bk_files(); foreach (array_slice($fs, 7) as $x) @unlink($d . '/' . $x['name']);
            $sz = (int)filesize($f); $info = 'OK · ' . round($sz / 1048576, 2) . ' MB'; $res = 'ok ' . round($sz / 1048576, 2) . 'MB';
            if (setting('sec_bk_tg', '1') === '1') {
                $tf = $d . '/tg_' . bin2hex(random_bytes(4)) . '.sql.gz';
                if (sec_dump($tf, true) && filesize($tf) <= 45 * 1048576) {
                    $data = file_get_contents($tf); $sent = 0;
                    foreach (array_map('trim', explode(',', ADMIN_IDS)) as $id) if ($id !== '') { $r = tg_doc($id, $data, 'tartibon_zaxira_' . date('Y-m-d') . '.sql.gz', '🗄 Zaxira nusxa (maxfiy kalitlarsiz). Tiklash: gunzip < fayl | mysql ...'); if (!empty($r['ok'])) $sent++; }
                    $info .= $sent ? ' · Telegramga yuborildi' : ' · Telegramga yuborilmadi';
                } else $info .= ' · Telegram uchun juda katta (serverda saqlandi)';
                @unlink($tf);
            }
            setset('sec_bk_info', $info); setset('sec_bk_at', date('Y-m-d H:i:s'));
        }
    } catch (Exception $e) { setset('sec_bk_info', 'Xato: ' . mb_substr($e->getMessage(), 0, 100)); }
    q("SELECT RELEASE_LOCK('kp_bk')");
    return $res;
}
/* ---- eski jurnallarni tozalash (kuniga bir marta) ---- */
function sec_clean() {
    $day = date('Ymd'); if (setting('sec_cl_day', '') === $day) return 0;
    setset('sec_cl_day', $day); $n = 0;
    foreach (array("DELETE FROM sec_slow WHERE at < NOW() - INTERVAL 30 DAY", "DELETE FROM pay_log WHERE at < NOW() - INTERVAL 30 DAY", "DELETE FROM sms_in WHERE at < NOW() - INTERVAL 90 DAY", "DELETE FROM audit_logs WHERE at < NOW() - INTERVAL 400 DAY", "DELETE FROM sec_rl WHERE w < " . ((int)floor(time() / 60) - 10), "DELETE FROM settings WHERE k LIKE 'sec\\_ab\\_%' AND k NOT LIKE '%" . $day . "'") as $sql) { try { $n += q($sql)->rowCount(); } catch (Exception $e) {} }
    return 'tozalandi: ' . $n;
}
function sec_find_user($qs) {
    $qs = trim((string)$qs); if ($qs === '') return false;
    if (preg_match('/^\d{3,15}$/', $qs)) return q('SELECT id,name,username,blocked FROM users WHERE id=?', array((int)$qs))->fetch();
    return q('SELECT id,name,username,blocked FROM users WHERE username=?', array(ltrim($qs, '@')))->fetch();
}
/* ---------- BALANS: ko'p karta, bonuslar, sovg'a balansi, kam balans eslatmasi, chek eslatmasi ---------- */
/* Kartalar: id 0 — asosiy («Karta va narxlar»), 1.. — qo'shimcha. Har bir karta alohida yoqiladi/o'chiriladi */
function pay_cards() {
    $o = array(); $p = (string)setting('pay_card', ''); $pd = preg_replace('/\D/', '', $p);
    if ($p !== '') $o[] = array('id' => 0, 'card' => $p, 'holder' => (string)setting('pay_holder', ''), 'c4' => strlen($pd) >= 4 ? substr($pd, -4) : (string)setting('sms_card4', ''), 'on' => setting('pay_card_on', '1') === '1');
    $x = json_decode((string)setting('pay_cards_x', ''), true);
    if (is_array($x)) foreach (array_values($x) as $i => $c) { if (!is_array($c) || empty($c['card'])) continue; $d = preg_replace('/\D/', '', (string)$c['card']); $o[] = array('id' => $i + 1, 'card' => trim(chunk_split($d, 4, ' ')), 'holder' => isset($c['holder']) ? (string)$c['holder'] : '', 'c4' => substr($d, -4), 'on' => !empty($c['on'])); }
    return $o;
}
function pay_active() { return array_values(array_filter(pay_cards(), function ($c) { return $c['on']; })); }
function pay_first() { $a = pay_active(); return $a ? $a[0] : null; }
/* Yangi to'lov uchun karta: faol kartalar navbat bilan beriladi (yuk bir kartaga tushmaydi) */
function tp_remind() {
    if (time() - (int)setting('tp_rem_at', '0') < 1800) return 0;
    $r = q("SELECT COUNT(*) c, MIN(created_at) m FROM topups WHERE status='pending' AND created_at < NOW() - INTERVAL 15 MINUTE")->fetch();
    if ((int)$r['c'] === 0) return 0;
    setset('tp_rem_at', (string)time());
    $t = ''; if ((int)$r['c'] > 0) $t .= '🧾 ' . (int)$r['c'] . ' ta to\'lov cheki tasdiqlanmagan (eng eskisi ' . max(1, (int)round((time() - strtotime($r['m'])) / 60)) . ' daqiqa). ';
    notify_admins('⏳ ' . trim($t) . 'Admin → To\'lovlar bo\'limini oching.');
    return 'eslatma';
}
/* ---- bonuslar: birinchi to'ldirish va katta summaga ---- */
function bn_cfg() {
    $t = json_decode((string)setting('bn_tiers', '[[200000,2],[500000,3],[1000000,5]]'), true); $o = array();
    if (is_array($t)) foreach ($t as $r) if (is_array($r) && count($r) === 2 && (int)$r[0] > 0 && (float)$r[1] > 0) $o[] = array((int)$r[0], (float)$r[1]);
    usort($o, function ($a, $b) { return $a[0] - $b[0]; });
    return array('on' => setting('bn_on', '1') === '1', 'first' => (float)setting('bn_first', '5'), 'tiers' => $o, 'cap' => (int)setting('bn_cap', '100000'));
}
function bn_pct($p) { return rtrim(rtrim(number_format($p, 2, '.', ''), '0'), '.'); }
function bonus_calc($uid, $amt, $excl = 0) {
    $c = bn_cfg(); if (!$c['on'] || $amt <= 0) return array(0, ''); $pct = 0; $why = array();
    if ($c['first'] > 0 && (int)q("SELECT COUNT(*) FROM topups WHERE user_id=? AND status='approved' AND id<>?", array($uid, $excl))->fetchColumn() === 0 && !dev_got($uid, 'first')) { $pct += $c['first']; $why[] = 'birinchi to\'ldirish +' . bn_pct($c['first']) . '%'; }
    $tp = 0; foreach ($c['tiers'] as $t) if ($amt >= $t[0]) $tp = $t[1];
    if ($tp > 0) { $pct += $tp; $why[] = 'katta summa +' . bn_pct($tp) . '%'; }
    $b = (int)floor($amt * $pct / 100); if ($c['cap'] > 0) $b = min($b, $c['cap']);
    return array($b, implode(' · ', $why));
}
/* Tranzaksiya ichida chaqiriladi: balansga bonus qo'shadi, jurnalga yozadi */
function bonus_give($uid, $amt, $excl = 0) {
    $r = bonus_calc($uid, $amt, $excl);
    if ($r[0] > 0) { q('UPDATE users SET balance=balance+?, bonus=bonus+? WHERE id=?', array($r[0], $r[0], $uid)); q('INSERT INTO bonus_log (uid,kind,amount,ref,note,at) VALUES (?,?,?,?,?,NOW())', array($uid, 'topup', $r[0], (int)$excl, mb_substr($r[1], 0, 100))); }
    return $r;
}
function bonus_tell($uid, $r) { nk_tell($uid, '🎁 Bonus: +' . money($r[0]) . ' (' . $r[1] . ')'); }
/* Bonus xizmatlarda sarflanmaguncha yechib yoki sovg'a qilib bo'lmaydi (bonus orqali pul chiqarishning oldini oladi) */
function bonus_locked($uid) {
    try {
        $b = (int)q('SELECT bonus FROM users WHERE id=?', array($uid))->fetchColumn(); if ($b <= 0) return 0;
        $sp = (int)q('SELECT COALESCE(SUM(price-refunded),0) FROM nk_ord WHERE uid=?', array($uid))->fetchColumn() + (int)q('SELECT COALESCE(SUM(price-refunded),0) FROM vs_ord WHERE uid=?', array($uid))->fetchColumn();
        return max(0, $b - $sp);
    } catch (Exception $e) { return 0; }
}
function bonus_info($uid) {
    $c = bn_cfg(); if (!$c['on']) return ''; $p = array();
    try { if ($c['first'] > 0 && (int)q("SELECT COUNT(*) FROM topups WHERE user_id=? AND status='approved'", array($uid))->fetchColumn() === 0) $p[] = 'Birinchi to\'ldirishga +' . bn_pct($c['first']) . '% bonus'; } catch (Exception $e) {}
    foreach ($c['tiers'] as $t) $p[] = number_format($t[0], 0, '', ' ') . ' so\'mdan +' . bn_pct($t[1]) . '%';
    return implode(' · ', $p);
}
/* ---- kam balans eslatmasi (xarid qilingach, javob yuborilgandan keyin) ---- */
function bal_low($uid) {
    try {
        if (setting('lb_on', '1') !== '1') return;
        $b = (int)q('SELECT balance FROM users WHERE id=?', array($uid))->fetchColumn(); $min = max(0, (int)setting('lb_min', '5000'));
        if ($b >= $min) { q('DELETE FROM bal_rem WHERE uid=?', array($uid)); return; }
        $r = q('SELECT at FROM bal_rem WHERE uid=?', array($uid))->fetchColumn();
        if ($r && time() - (int)$r < max(1, (int)setting('lb_days', '3')) * 86400) return;
        q('REPLACE INTO bal_rem (uid,at) VALUES (?,?)', array($uid, time()));
        tg('sendMessage', array('chat_id' => $uid, 'text' => '💡 Balansingizda ' . money($b) . ' qoldi. Xizmatlardan uzilishsiz foydalanish uchun balansni to\'ldiring.', 'reply_markup' => json_encode(array('inline_keyboard' => array(array(array('text' => '➕ Balansni to\'ldirish', 'web_app' => array('url' => APP_URL))))))));
    } catch (Exception $e) {}
}
function bal_low_later($uid) { register_shutdown_function('bal_low', (int)$uid); }
function gift_cfg() { return array('on' => setting('g_on', '1') === '1', 'min' => max(100, (int)setting('g_min', '1000')), 'max' => max(1000, (int)setting('g_max', '5000000')), 'day' => max(1000, (int)setting('g_day', '10000000')), 'fee' => max(0, min(20, (float)setting('g_fee', '0')))); }
/* ---------- HISOBOTLAR: kunlik/oylik daromad, prognoz, top mijozlar, manba (UTM), sekin so'rovlar, bugungi ishlar ---------- */
function rp_shift() {   /* PHP va MySQL soat farqi (soat zonalari mos kelmasa ham sana chegaralari to'g'ri bo'lishi uchun) */
    static $s = null;
    if ($s === null) { try { $s = (int)(round((time() - strtotime((string)q('SELECT NOW()')->fetchColumn())) / 900) * 900); } catch (Exception $e) { $s = 0; } }
    return $s;
}
function rp_db($ts) { return date('Y-m-d H:i:s', $ts - rp_shift()); }
function rp_src($uid, $src) {
    $src = trim((string)$src); if (!preg_match('/^[A-Za-z0-9_-]{1,40}$/', $src)) return;
    try { q("UPDATE users SET src=? WHERE id=? AND src=''", array($src, (int)$uid)); } catch (Exception $e) {}
}
function rp_src_text($uid, $text) { if (preg_match('/^\/start(?:@\w+)?\s+(\S+)/', (string)$text, $m)) rp_src($uid, $m[1]); }
function sec_slow_log($a) {
    $ms = (int)round((microtime(true) - (isset($GLOBALS['T0']) ? $GLOBALS['T0'] : microtime(true))) * 1000);
    if ($ms < sec_conf()['slow']) return;
    try { q('INSERT INTO sec_slow (a,ms,at) VALUES (?,?,NOW())', array(mb_substr($a, 0, 40), $ms)); } catch (Exception $e) {}
}
/* [t0, t1) oralig'idagi ko'rsatkichlar (t0/t1 — PHP vaqt tamg'alari) */
function rp_data($t0, $t1) {
    $a = rp_db($t0); $b = rp_db($t1); $o = array();
    $one = function ($sql, $p = null) use ($a, $b) { return q($sql, $p === null ? array($a, $b) : $p)->fetch(PDO::FETCH_NUM); };
    $r = $one("SELECT COUNT(*), COALESCE(SUM(amount),0) FROM topups WHERE status='approved' AND decided_at>=? AND decided_at<?"); $o['tp_n'] = (int)$r[0]; $o['tp'] = (int)$r[1];
    $r = $one("SELECT COALESCE(SUM(amount),0) FROM topups WHERE status='approved' AND flag LIKE 'avto:%' AND decided_at>=? AND decided_at<?"); $o['tp_auto'] = (int)$r[0];
    $r = $one("SELECT COUNT(*), COALESCE(SUM(amount),0) FROM withdrawals WHERE status='approved' AND decided_at>=? AND decided_at<?"); $o['wd_n'] = (int)$r[0]; $o['wd'] = (int)$r[1];
    $r = $one("SELECT COUNT(*), COALESCE(SUM(o.price-o.refunded),0), COALESCE(SUM(COALESCE(o.cost, o.qty/1000*s.rate)),0) FROM nk_ord o LEFT JOIN nk_svc s ON s.id=o.sid WHERE o.created>=? AND o.created<? AND o.st IN ('wait','done','part','unk')"); $o['nk_n'] = (int)$r[0]; $o['nk_rev'] = (int)$r[1]; $usd = nk_usd(); $o['nk_cost'] = (int)round((float)$r[2] * $usd); $o['nk_profit'] = $o['nk_rev'] - $o['nk_cost'];
    $r = $one("SELECT COALESCE(SUM(refunded),0) FROM nk_ord WHERE created>=? AND created<?"); $o['nk_ref'] = (int)$r[0];
    $r = $one("SELECT COUNT(*), COALESCE(SUM(price-refunded),0), COALESCE(SUM(pcost),0) FROM vs_ord WHERE created>=? AND created<? AND st IN ('got','wait','unk')"); $o['vs_n'] = (int)$r[0]; $o['vs_rev'] = (int)$r[1]; $o['vs_cost'] = (int)round((float)$r[2] * max(0, vs_rate())); $o['vs_profit'] = $o['vs_rev'] - $o['vs_cost'];
    $r = $one("SELECT COALESCE(SUM(refunded),0) FROM vs_ord WHERE created>=? AND created<?"); $o['vs_ref'] = (int)$r[0];
    $r = $one("SELECT COALESCE(SUM(fee),0) FROM auc_orders WHERE paid=1 AND dispute<>3 AND decided_at>=? AND decided_at<?", array($t0, $t1)); $o['auc'] = (int)$r[0];
    $r = $one("SELECT COALESCE(SUM(price),0) FROM ad_orders WHERE status IN ('done','sending') AND decided_at>=? AND decided_at<?"); $o['ads'] = (int)$r[0];
    $r = $one("SELECT COALESCE(SUM(amount),0) FROM bonus_log WHERE at>=? AND at<?"); $o['bonus'] = (int)$r[0];
    $r = $one("SELECT COUNT(*), COALESCE(SUM(fee),0) FROM gift_log WHERE at>=? AND at<?"); $o['gift_n'] = (int)$r[0]; $o['gift_fee'] = (int)$r[1];
    $r = $one("SELECT COUNT(*) FROM users WHERE created_at>=? AND created_at<?"); $o['users'] = (int)$r[0];
    $o['profit'] = $o['nk_profit'] + $o['vs_profit'] + $o['auc'] + $o['ads'] + $o['gift_fee'] - $o['bonus'];
    return $o;
}
function rp_money($n) { return ($n < 0 ? '−' : '') . number_format(abs((int)$n), 0, '', ' ') . ' so\'m'; }
function rp_text($d, $title) {
    $t = $title . "\n\n💰 Kirim: " . rp_money($d['tp']) . ' (' . $d['tp_n'] . " ta" . ($d['tp'] ? ', shundan avto: ' . rp_money($d['tp_auto']) : '') . ")\n➖ Yechildi: " . rp_money($d['wd']) . ' (' . $d['wd_n'] . " ta)\n\n";
    $t .= '🚀 Nakrutka: ' . $d['nk_n'] . ' ta · tushum ' . rp_money($d['nk_rev']) . ' · foyda ' . rp_money($d['nk_profit']) . "\n";
    $t .= '📲 eSIM: ' . $d['vs_n'] . ' ta · tushum ' . rp_money($d['vs_rev']) . ' · foyda ' . rp_money($d['vs_profit']) . "\n";
    if ($d['auc'] || $d['ads'] || $d['gift_fee']) $t .= '🤝 Birja komissiyasi: ' . rp_money($d['auc']) . ' · E\'lonlar: ' . rp_money($d['ads']) . ' · Sovg\'a komissiyasi: ' . rp_money($d['gift_fee']) . "\n";
    $t .= '🎁 Bonus xarajati: ' . rp_money($d['bonus']) . "\n↩️ Qaytarilgan: " . rp_money($d['nk_ref'] + $d['vs_ref']) . "\n\n";
    $t .= '📈 Taxminiy sof foyda: ' . rp_money($d['profit']) . "\n👤 Yangi foydalanuvchi: " . $d['users'];
    return $t;
}
function rp_prov_text() {
    $o = ''; try {
        $c = json_decode((string)setting('nk_bal_c', ''), true); if (is_array($c) && !empty($c['ok'])) $o .= "\nprm4u balansi: " . ($c['cur'] === 'USD' ? '$' : '') . number_format((float)$c['balance'], 2) . ' ' . ($c['cur'] !== 'USD' ? $c['cur'] : '');
        $s = json_decode((string)setting('sm_bal_c', ''), true); if (is_array($s) && !empty($s['ok'])) $o .= "\n5sim balansi: " . number_format((float)$s['balance'], 2) . ' ' . sm_cur();
    } catch (Exception $e) {}
    return $o;
}
function rp_day($ts = null) { $ts = $ts ?: time(); $t0 = strtotime(date('Y-m-d 00:00:00', $ts)); return array($t0, $t0 + 86400); }
function rp_csv($y, $m) {
    $rows = array(array('Sana', 'Kirim n', 'Kirim', 'Yechildi', 'Nakrutka tushum', 'Nakrutka xarajat', 'Virtual tushum', 'Virtual xarajat', 'Birja komissiya', 'Elon', 'Sovga komissiya', 'Bonus', 'Foyda'));
    $tot = array_fill(0, 12, 0); $n = (int)date('t', strtotime("$y-$m-01"));
    for ($d = 1; $d <= $n; $d++) {
        $t0 = strtotime(sprintf('%04d-%02d-%02d 00:00:00', $y, $m, $d)); $r = rp_data($t0, $t0 + 86400);
        $v = array($r['tp_n'], $r['tp'], $r['wd'], $r['nk_rev'], $r['nk_cost'], $r['vs_rev'], $r['vs_cost'], $r['auc'], $r['ads'], $r['gift_fee'], $r['bonus'], $r['profit']);
        foreach ($v as $i => $x) $tot[$i] += $x;
        $rows[] = array_merge(array(sprintf('%04d-%02d-%02d', $y, $m, $d)), $v);
    }
    $rows[] = array_merge(array('JAMI'), $tot);
    return csv_make($rows);
}
function rp_send_csv($chat, $y, $m) { return tg_doc($chat, rp_csv($y, $m), sprintf('tartibon_hisobot_%04d-%02d.csv', $y, $m), '🧾 ' . sprintf('%04d-%02d', $y, $m) . ' oylik hisobot (soliq/hisobchi uchun)'); }
function rp_daily() {
    if (setting('rp_on', '1') !== '1') return 'o\'chiq';
    $today = date('Y-m-d'); $out = array();
    if ((int)date('j') === 1 && date('H') >= '09' && setting('rp_mon', '') !== date('Y-m')) {
        setset('rp_mon', date('Y-m')); $pm = strtotime('-1 month'); $y = (int)date('Y', $pm); $m = (int)date('n', $pm);
        foreach (array_map('trim', explode(',', ADMIN_IDS)) as $id) if ($id !== '') rp_send_csv($id, $y, $m);
        $out[] = 'oylik CSV';
    }
    if (date('H:i') >= setting('rp_time', '23:30') && setting('rp_day', '') !== $today) {
        if (!(int)q("SELECT GET_LOCK('kp_rp', 0)")->fetchColumn()) return 'band';
        setset('rp_day', $today); $r = rp_day();
        notify_admins(rp_text(rp_data($r[0], $r[1]), '📊 Kunlik hisobot — ' . date('d.m.Y')) . rp_prov_text());
        q("SELECT RELEASE_LOCK('kp_rp')"); $out[] = 'kunlik';
    }
    return $out ? implode(', ', $out) : 0;
}
/* ---- provayder balansi prognozi: so'nggi 7 kun sarfiga qarab necha kunga yetishi ---- */
function rp_prog($p) {
    try {
        if ($p === 'nk') {
            $b = json_decode((string)setting('nk_bal_c', ''), true); if (!is_array($b) || empty($b['ok'])) return null;
            $sp = (float)q("SELECT COALESCE(SUM(COALESCE(o.cost, o.qty/1000*s.rate)),0) FROM nk_ord o LEFT JOIN nk_svc s ON s.id=o.sid WHERE o.created > NOW() - INTERVAL 7 DAY AND o.st IN ('wait','done','part','unk')")->fetchColumn();
            $bal = (float)$b['balance'];
        } else {
            $b = json_decode((string)setting('sm_bal_c', ''), true); if (!is_array($b) || empty($b['ok'])) return null;
            $sp = (float)q("SELECT COALESCE(SUM(pcost),0) FROM vs_ord WHERE created > NOW() - INTERVAL 7 DAY AND st IN ('got','wait','unk')")->fetchColumn();
            $bal = (float)$b['balance'];
        }
        return array('spent7' => round($sp, 2), 'days' => $sp > 0 ? (int)floor($bal / ($sp / 7)) : null);
    } catch (Exception $e) { return null; }
}
function rp_prog_run() {
    $lim = (int)setting('pg_days', '3'); if ($lim <= 0 || (int)date('G') < (int)setting('pg_from', '9') || setting('pg_day', '') === date('Y-m-d')) return 0;
    setset('pg_day', date('Y-m-d')); $t = '';
    foreach (array('nk' => 'prm4u (Nakrutka)', 'vs' => '5sim (eSIM)') as $k => $n) { $r = rp_prog($k); if ($r && $r['days'] !== null && $r['days'] < $lim) $t .= "\n• " . $n . ': hozirgi sarfda taxminan ' . $r['days'] . ' kunga yetadi'; }
    if ($t !== '') { notify_admins('⚠️ Provayder balansini to\'ldiring:' . $t); return 'ogohlantirish'; }
    return 0;
}
/* ---- bugungi ishlar ---- */
function tod_items() {
    $it = array(); $add = function ($k, $ic, $t, $n, $note = '') use (&$it) { if ($n > 0) $it[] = array('k' => $k, 'ic' => $ic, 't' => $t, 'n' => (int)$n, 'note' => $note); };
    $c = function ($sql, $p = array()) { try { return (int)q($sql, $p)->fetchColumn(); } catch (Exception $e) { return 0; } };
    $add('topups', '🧾', 'Tasdiqlanmagan to\'lov cheklari', $c("SELECT COUNT(*) FROM topups WHERE status='pending'"));
    $add('wd', '➖', 'Pul yechish so\'rovlari', $c("SELECT COUNT(*) FROM withdrawals WHERE status='pending'"));
    $add('disp', '⚖️', 'Nizolar (reklama birjasi)', $c("SELECT COUNT(*) FROM auc_orders WHERE dispute=1 AND paid=0"));
    $add('ads', '📢', 'E\'lon buyurtmalari', $c("SELECT COUNT(*) FROM ad_orders WHERE status IN ('pending','sending')"));
    $add('unk', '🔍', 'Holati noma\'lum buyurtmalar (Nakrutka)', $c("SELECT COUNT(*) FROM nk_ord WHERE st='unk'"), 'Provayder panelida tekshirib, «Qaytarish» yoki «Yuborilgan» ni bosing');
    $add('unkv', '🔍', 'Holati noma\'lum buyurtmalar (eSIM)', $c("SELECT COUNT(*) FROM vs_ord WHERE st='unk'"), '5sim panelida tekshiring');
    foreach (array('nk' => array('nk_bal_c', 'prm4u', 'nk_low', '5'), 'vs' => array('sm_bal_c', '5sim', 'sm_low', '3')) as $k => $x) {
        $b = json_decode((string)setting($x[0], ''), true); if (is_array($b) && !empty($b['ok']) && (float)$b['balance'] < (float)setting($x[2], $x[3])) $add('plow', '💰', $x[1] . ' balansi past', 1, number_format((float)$b['balance'], 2));
        $pg = rp_prog($k); $lim = (int)setting('pg_days', '3'); if ($pg && $pg['days'] !== null && $pg['days'] < $lim) $add('plow', '📉', $x[1] . ' balansi ' . $pg['days'] . ' kunga yetadi', 1);
        if (sec_down($k)) $add('pdown', '⛔', sec_pname($k) . ': avto-to\'xtatilgan', 1);
    }
    $dg = count(dev_groups(50)); if ($dg > 0) $add('dev', '🕵️', 'Bir qurilmadan bir nechta akkaunt (30 kun)', $dg, 'Hisobotlar bo\'limida ko\'ring; bonus suiiste\'moli bo\'lsa bloklang');
    $add('subs', '🔐', 'Pullik kanal: 3 kun ichida tugaydigan obunalar', $c("SELECT COUNT(*) FROM pc_subs WHERE until BETWEEN ? AND ? AND kicked=0", array(time(), time() + 3 * 86400)));
    $bk = strtotime((string)setting('sec_bk_at', '')) ?: 0; if (setting('sec_bk_on', '1') === '1' && time() - $bk > 2 * 86400) $add('bk', '🗄', 'Zaxira nusxa 2 kundan beri olinmagan', 1);
    $cm = strtotime((string)setting('cron_min_at', '')) ?: 0; if (time() - $cm > 900) $add('cron', '⏱', 'Cron ishlamayapti (15 daqiqadan beri signal yo\'q)', 1);
    return $it;
}
/* ---------- NAKRUTKA: hajm chegirmasi, umumiy buyurtma funksiyasi, takroriy buyurtmalar ---------- */
function nk_vol() {
    $t = json_decode((string)setting('nk_vol', '[[10000,5]]'), true); $o = array();
    if (is_array($t)) foreach ($t as $r) if (is_array($r) && count($r) === 2 && (int)$r[0] > 0 && (float)$r[1] > 0 && (float)$r[1] <= 50) $o[] = array((int)$r[0], (float)$r[1]);
    usort($o, function ($a, $b) { return $a[0] - $b[0]; });
    return $o;
}
function nk_disc($qty) { $d = 0; foreach (nk_vol() as $t) if ($qty >= $t[0]) $d = $t[1]; return $d; }
/* Buyurtma berish (oddiy buyurtma, savat va takroriy buyurtma uchun umumiy). Qaytaradi: ok, st (HTTP kodi), error, id, price, check, need_topup */
function nk_do_order($uid, $s, $qty, $link, $dup = true) {
    $price = nk_price($s, $qty, $uid); if ($price <= 0) return array('ok' => false, 'st' => 503, 'error' => 'Narx hisoblanmadi, keyinroq urinib ko\'ring');
    if ((int)q('SELECT COUNT(*) FROM nk_ord WHERE uid=? AND created > NOW() - INTERVAL 1 DAY', array($uid))->fetchColumn() >= (int)setting('nk_day', '20')) return array('ok' => false, 'st' => 429, 'error' => 'Bir kunda buyurtmalar soni chegarasiga yetdingiz');
    if ($dup && (int)q('SELECT COUNT(*) FROM nk_ord WHERE uid=? AND sid=? AND link=? AND created > NOW() - INTERVAL 60 SECOND', array($uid, $s['id'], $link))->fetchColumn() > 0) return array('ok' => false, 'st' => 429, 'error' => 'Bu buyurtma hozirgina berilgan');
    $pdo = db(); $oid = 0;
    try {
        $pdo->beginTransaction();
        if (q('UPDATE users SET balance=balance-? WHERE id=? AND balance>=?', array($price, $uid, $price))->rowCount() !== 1) { $pdo->rollBack(); return array('ok' => false, 'st' => 402, 'error' => 'Balans yetarli emas', 'need_topup' => true); }
        q("INSERT INTO nk_ord (uid,sid,pid,plat,title,link,qty,price,st,created,upd) VALUES (?,?,?,?,?,?,?,?,'new',NOW(),NOW())", array($uid, $s['id'], $s['pid'], $s['plat'], $s['title'], $link, $qty, $price));
        $oid = (int)$pdo->lastInsertId(); $pdo->commit(); bal_low_later($uid);
    } catch (Exception $e) { if ($pdo->inTransaction()) $pdo->rollBack(); return array('ok' => false, 'st' => 500, 'error' => 'Xatolik, qayta urinib ko\'ring'); }
    $r = nk_call(array('action' => 'add', 'service' => (int)$s['pid'], 'link' => $link, 'quantity' => $qty), 30);
    if ($r['ok'] && is_array($r['j']) && isset($r['j']['order']) && (int)$r['j']['order'] > 0) {
        q("UPDATE nk_ord SET st='wait', pstat='Pending', porder=?, upd=NOW() WHERE id=? AND st='new'", array((int)$r['j']['order'], $oid));
        return array('ok' => true, 'id' => $oid, 'price' => $price);
    }
    if (!$r['ok'] && $r['sure']) {
        nk_refund($oid, $price, 'fail', 'Rad etildi');
        q('UPDATE nk_ord SET err=? WHERE id=?', array(mb_substr($r['err'], 0, 250), $oid));
        if (preg_match('/fund|balance|credit|money|key|auth|denied|forbidden/i', $r['err'])) notify_admins('⚠️ Nakrutka: provayder buyurtmani rad etdi — «' . $r['err'] . '». Provayderdagi hisob yoki API kalitni tekshiring.');
        return array('ok' => false, 'st' => 422, 'error' => 'Buyurtma qabul qilinmadi: ' . $r['err'] . '. Pul balansingizga qaytarildi.');
    }
    q("UPDATE nk_ord SET st='unk', err=?, upd=NOW() WHERE id=? AND st='new'", array(mb_substr($r['ok'] ? 'Javobda buyurtma raqami yo\'q' : $r['err'], 0, 250), $oid));
    notify_admins('🔍 Nakrutka: buyurtma #' . $oid . ' holati noma\'lum (' . ($r['ok'] ? 'javob tushunarsiz' : $r['err']) . '). Provayder panelida tekshiring, so\'ng ilovada «Qaytarish» yoki «Yuborilgan» ni bosing.');
    return array('ok' => true, 'id' => $oid, 'price' => $price, 'check' => true);
}
function nk_every_name($d) { return $d == 1 ? 'har kuni' : ($d == 7 ? 'har hafta' : ($d == 30 ? 'har oy' : 'har ' . (int)$d . ' kunda')); }
/* Takroriy buyurtmalar: vaqti kelganlar avtomatik beriladi (daqiqalik cron) */
function nk_sub_run() {
    if (setting('nk_on', '1') !== '1' || nk_cfg()[1] === '' || nk_usd() <= 0 || !sec_svc('nk')[0]) return 0;
    $rows = q("SELECT * FROM nk_sub WHERE st='on' AND next_at <= ? ORDER BY next_at LIMIT 20", array(time()))->fetchAll(); $n = 0;
    foreach ($rows as $r) {
        if (q('UPDATE nk_sub SET next_at=? WHERE id=? AND next_at=? AND st=\'on\'', array(time() + 300, $r['id'], $r['next_at']))->rowCount() !== 1) continue;
        $s = q('SELECT * FROM nk_svc WHERE id=? AND act=1', array($r['sid']))->fetch();
        if (!$s) { q("UPDATE nk_sub SET st='pause' WHERE id=?", array($r['id'])); nk_tell($r['uid'], '⏸ Takroriy buyurtma to\'xtatildi: xizmat hozir mavjud emas.'); continue; }
        $res = nk_do_order($r['uid'], $s, (int)$r['qty'], $r['link'], false);
        if ($res['ok']) {
            $left = (int)$r['left_n'] - 1; $n++;
            if ($left <= 0) q("UPDATE nk_sub SET st='done', left_n=0, last_id=?, fails=0 WHERE id=?", array($res['id'], $r['id']));
            else q('UPDATE nk_sub SET next_at=?, left_n=?, last_id=?, fails=0 WHERE id=?', array(time() + (int)$r['every_d'] * 86400, $left, $res['id'], $r['id']));
            nk_tell($r['uid'], '🔁 Takroriy buyurtma #' . $res['id'] . ' berildi (' . $s['title'] . ' · ' . $r['qty'] . ' ta, ' . money($res['price']) . ').' . ($left > 0 ? ' Yana ' . $left . ' marta ' . nk_every_name($r['every_d']) . '.' : ' Bu oxirgisi edi.'));
        } elseif ($res['st'] === 402) {
            q("UPDATE nk_sub SET st='pause' WHERE id=?", array($r['id']));
            nk_tell($r['uid'], '⏸ Takroriy buyurtma to\'xtatildi: balans yetmadi. Balansni to\'ldirib, ilovada «Takroriy buyurtmalarim» dan davom ettiring.');
        } else {
            $f = (int)$r['fails'] + 1;
            if ($f >= 3) { q("UPDATE nk_sub SET st='pause', fails=? WHERE id=?", array($f, $r['id'])); nk_tell($r['uid'], '⏸ Takroriy buyurtma 3 marta berilmadi (' . $res['error'] . ') va to\'xtatildi.'); }
            else q('UPDATE nk_sub SET fails=?, next_at=? WHERE id=?', array($f, time() + 3600, $r['id']));
        }
    }
    return $n;
}
