        if (!$c) out(array('ok' => false, 'error' => 'Topilmadi'), 404);
        $sa = !empty($in['send_a']) ? 1 : 0; $sb = !empty($in['send_b']) ? 1 : 0; $sc = isset($in['send_c']) ? (!empty($in['send_c']) ? 1 : 0) : (int)$c['send_c'];
        $auto = (isset($in['auto_on']) ? !empty($in['auto_on']) : true) && $c['status'] === 'approved' && ($sa || $sb) ? 1 : 0;   /* kurs rasmlari tanlanmasa — faqat namoz/ertalabki xabar */
        $iv = isset($in['interval']) ? max(3, min(12, (int)$in['interval'])) : (int)$c['interval_h'];
        $dp = isset($in['dp_on']) ? (!empty($in['dp_on']) ? 1 : 0) : (int)$c['dp_on'];
        $wx = isset($in['wx_on']) ? (!empty($in['wx_on']) ? 1 : 0) : (int)$c['wx_on'];
        $ms = isset($in['ms_on']) ? (!empty($in['ms_on']) ? 1 : 0) : (int)$c['ms_on']; $ev = isset($in['ev_on']) ? (!empty($in['ev_on']) ? 1 : 0) : (int)$c['ev_on']; $kk = isset($in['kk_on']) ? (!empty($in['kk_on']) ? 1 : 0) : (int)$c['kk_on'];
        q('UPDATE chats SET auto_on=?, send_a=?, send_b=?, send_c=?, interval_h=?, dp_on=?, wx_on=?, ms_on=?, ev_on=?, kk_on=?, dp_days=IF(?=1 AND dp_days=\'0000000\',NULL,dp_days) WHERE id=?', array($auto, $sa, $sb, $sc, $iv, $dp, $wx, $ms, $ev, $kk, $dp, $c['id']));
        out(array('ok' => true));
