    if ($a === 'dp_my') {
        $r = array('ok' => true, 'on' => setting('dp_on', '0') === '1', 'time' => setting('dp_time', '06:00'),
            'chats' => q("SELECT id,username,ctype,dp_on FROM chats WHERE owner=? AND status='approved' AND blocked=0 ORDER BY id DESC", array($u['id']))->fetchAll());
        if ($adm) $r['cfg'] = dp_cfg();
        out($r);
    }
    if ($a === 'ev_info') out(array('ok' => true, 'adm' => $adm, 'cfg' => $adm ? ev_cfg() : array('on' => setting('ev_on', '1') === '1', 'time' => setting('ev_time', '21:30')), 'wa' => setting('wa_on', '1') === '1', 'wa_last' => setting('wa_last', '')));
    if ($a === 'ev_test') { $d = $adm && isset($in['d']) ? (int)$in['d'] : (int)date('N'); if ($d < 1 || $d > 7) $d = (int)date('N'); $it = ev_item($d); if (!$it) out(array('ok' => false, 'error' => 'Tungi xabar uchun video ham, matn ham yo\'q'), 422); $r = dp_sendi($it, array(array('chat_id' => $u['id']) + $it[1])); $r = $r[0]; out(array('vo' => isset($GLOBALS['VO_ERR']) ? $GLOBALS['VO_ERR'] : '', 'ok' => !empty($r['ok']), 'error' => !empty($r['ok']) ? '' : (isset($r['description']) ? $r['description'] . ($adm ? ' (bot baza kanalda administratormi?)' : '') : 'Yuborilmadi'))); }
    if ($a === 'adm_ev' || $a === 'adm_wa' || $a === 'adm_ev_flag') {
        if (!$adm) out(array('ok' => false, 'error' => 'Ruxsat yo\'q'), 403);
        if ($a === 'adm_wa') { setset('wa_on', !empty($in['on']) ? '1' : '0'); out(array('ok' => true, 'wa' => setting('wa_on', '1') === '1')); }
        if ($a === 'adm_ev_flag') {   /* d=0 — butun tungi xabar, d=1..7 — hafta kuni */
