            if ($d === 0) setset('ev_on', $on); elseif (isset($DAYS[$d])) setset('ev_o' . $d, $on); else out(array('ok' => false, 'error' => 'Kun noto\'g\'ri'), 422);
            $audit('tungi_flag', $d . '=' . $on); out(array('ok' => true, 'cfg' => ev_cfg()));
        }
