        if ($a === 'vz_set') {
            $c = q("SELECT id FROM chats WHERE id=? AND owner=? AND status='approved' AND blocked=0", array((int)(isset($in['id']) ? $in['id'] : 0), $u['id']))->fetch(); if (!$c) out(array('ok' => false, 'error' => 'Topilmadi'), 404);
            $cat = (string)(isset($in['cat']) ? $in['cat'] : ''); if (!in_array($cat, $VZC, true)) $cat = 'Boshqa';
            $d = mb_substr(trim(preg_replace('/\s+/u', ' ', (string)(isset($in['desc']) ? $in['desc'] : ''))), 0, 200);
            q('UPDATE chats SET vz_on=?, vz_cat=?, vz_desc=? WHERE id=?', array(!empty($in['on']) ? 1 : 0, $cat, $d, $c['id'])); out(array('ok' => true));
        }
        if ($a === 'vz_list') {
            $cat = (string)(isset($in['cat']) ? $in['cat'] : ''); $w = in_array($cat, $VZC, true) ? ' AND c.vz_cat=' . db()->quote($cat) : '';
            out(array('ok' => true, 'list' => q("SELECT c.id, c.username, c.ctype, c.vz_cat, c.vz_desc, $mem AS members FROM chats c WHERE c.vz_on=1 AND c.status='approved' AND c.blocked=0 AND c.owner <> ?" . $w . " ORDER BY members DESC, c.id DESC LIMIT 150", array($u['id']))->fetchAll()));
        }
        if ($a === 'vz_offer') {
            $fr = q("SELECT c.id, c.chat_id, c.username, c.ctype, $mem AS members FROM chats c WHERE c.id=? AND c.owner=? AND c.status='approved' AND c.blocked=0", array((int)(isset($in['from']) ? $in['from'] : 0), $u['id']))->fetch();
            $to = q("SELECT id, chat_id, username FROM chats WHERE id=? AND vz_on=1 AND status='approved' AND blocked=0", array((int)(isset($in['to']) ? $in['to'] : 0)))->fetch();
            if (!$fr || !$to) out(array('ok' => false, 'error' => 'Kanal topilmadi'), 404);
