                q('INSERT INTO pc_channels (chat_ref,owner,price,descr,on_,d3,d6,d12,trial) VALUES (?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE price=VALUES(price), descr=VALUES(descr), on_=VALUES(on_), d3=VALUES(d3), d6=VALUES(d6), d12=VALUES(d12), trial=VALUES(trial)', array($c['id'], $u['id'], $pr, $d, $on, $dd['d3'], $dd['d6'], $dd['d12'], $tr));
