                WHERE c.ctype IN ('Guruh','Kanal') AND c.status='approved' AND c.blocked=0 AND (" . ($adm ? '1=1' : 'c.owner=? OR c.chat_id IN (SELECT chat_id FROM quiz_participants WHERE user_id=?)') . ') ORDER BY enabled DESC, c.id DESC LIMIT 100',
                $adm ? array() : array($u['id'], $u['id']))->fetchAll();
            $groups = array(); foreach ($G as $g) $groups[] = array('id' => (int)$g['id'], 'name' => $g['username'], 'on' => (int)$g['enabled'], 'ch' => $g['ctype'] === 'Kanal' ? 1 : 0, 'own' => (string)$g['owner'] === (string)$u['id'] ? 1 : 0, 'manage' => $adm || (string)$g['owner'] === (string)$u['id']);
            $sel = isset($in['chat']) ? (int)$in['chat'] : -1;
            if ($sel === -1) $sel = $groups ? $groups[0]['id'] : 0;
            $c = $sel ? $qzc($sel) : null;
            if ($sel && (!$c || !in_array($sel, array_column($groups, 'id'), true))) { $sel = 0; $c = null; }
            $cid = $c ? $c['chat_id'] : 0; $now = time();
            $r = array('ok' => true, 'now' => $now, 'chat' => $sel, 'groups' => $groups, 'tree' => quiz_tree(),
                'pv' => q('SELECT t.id, t.title, COUNT(p.id) n FROM pv_topics t LEFT JOIN pv_questions p ON p.topic_id=t.id AND p.demo=0 GROUP BY t.id, t.title ORDER BY t.sort, t.id')->fetchAll(), 'pvn' => (int)q('SELECT COUNT(*) FROM pv_questions WHERE demo=0')->fetchColumn(), 'counts' => q('SELECT cat, COUNT(*) n FROM quiz_questions GROUP BY cat')->fetchAll(PDO::FETCH_KEY_PAIR), 'admin' => $adm, 'manage' => $c ? $c['manage'] : false);
            if ($c) {
                $cfg = quiz_cfg($cid);
                $r['cfg'] = array('on' => (int)$cfg['enabled'], 'cat' => (string)$cfg['cat'], 'label' => quiz_label((string)$cfg['cat']), 'interval' => (int)$cfg['interval_min'], 'sec' => (int)$cfg['answer_sec'], 'points' => (int)$cfg['points'],
                    'next' => (int)$cfg['next_at'], 'err' => (string)$cfg['last_err'], 'mode' => $cfg['mode'], 'ch' => (int)$cfg['channel'], 'count' => (int)$cfg['q_total'], 'done' => (int)$cfg['q_done'],
                    'src' => $cfg['src'], 'pvt' => (int)$cfg['pv_topic']);
