                $r['link'] = $c['username'] !== '' && $c['username'][0] === '@' ? 'https://t.me/' . substr($c['username'], 1) : '';
                $cur = q("SELECT s.subject, s.points, s.ends_at, s.kind, s.opts, COALESCE(q.question, pq.question) question, COALESCE(q.answer, '') answer FROM quiz_sessions s LEFT JOIN quiz_questions q ON q.id=s.question_id AND s.src='qz' LEFT JOIN pv_questions pq ON pq.id=s.question_id AND s.src='pv' WHERE s.chat_id=? AND s.status='active' AND COALESCE(q.id, pq.id) IS NOT NULL LIMIT 1", array($cid))->fetch();
                if ($cur) {
                    $bx = $cur['kind'] === 'test' ? array('', '📝 Test · variantlardan birini tanlang') : quiz_boxes($cur['answer']);
                    $r['cur'] = array('subject' => $cur['subject'], 'question' => $cur['question'], 'boxes' => $bx[0], 'info' => $bx[1], 'points' => (int)$cur['points'], 'ends' => (int)$cur['ends_at'],
                        'opts' => $cur['kind'] === 'test' ? json_decode((string)$cur['opts'], true) : null);
                }
            }
            $w = $cid ? ' AND s.chat_id=?' : ''; $p = $cid ? array($cid) : array();
            $r['last'] = q("SELECT s.subject, COALESCE(q.question, pq.question) question, COALESCE(q.answer, '') answer, s.src, s.opts, s.correct_opt, s.winner_name, s.points, s.finished_at FROM quiz_sessions s LEFT JOIN quiz_questions q ON q.id=s.question_id AND s.src='qz' LEFT JOIN pv_questions pq ON pq.id=s.question_id AND s.src='pv' WHERE s.status='finished'" . $w . ' ORDER BY s.id DESC LIMIT 5', $p)->fetchAll();
            foreach ($r['last'] as $i => $x) { if ($x['src'] === 'pv') { $O = json_decode((string)$x['opts'], true); $r['last'][$i]['answer'] = isset($O[(int)$x['correct_opt']]) ? (string)$O[(int)$x['correct_opt']] : ''; } unset($r['last'][$i]['opts'], $r['last'][$i]['correct_opt']); }
            $r['subj'] = q("SELECT s.subject, COUNT(*) n, SUM(s.winner_id IS NOT NULL) won FROM quiz_sessions s WHERE s.status='finished'" . $w . ' GROUP BY s.subject ORDER BY n DESC', $p)->fetchAll();
            $me = $cid ? q('SELECT points, correct, answered FROM quiz_participants WHERE chat_id=? AND user_id=?', array($cid, $u['id']))->fetch()
                : q('SELECT SUM(points) points, SUM(correct) correct, SUM(answered) answered FROM quiz_participants WHERE user_id=?', array($u['id']))->fetch();
            $mp = $me ? (int)$me['points'] : 0;
            $place = $cid ? (int)q('SELECT COUNT(*)+1 FROM quiz_participants WHERE chat_id=? AND points>?', array($cid, $mp))->fetchColumn()
                : (int)q('SELECT COUNT(*)+1 FROM (SELECT user_id FROM quiz_participants GROUP BY user_id HAVING SUM(points)>?) t', array($mp))->fetchColumn();
            $r['me'] = array('points' => $mp, 'correct' => $me ? (int)$me['correct'] : 0, 'answered' => $me ? (int)$me['answered'] : 0, 'place' => $mp > 0 ? $place : 0,
