            $r['rank'] = quiz_rank($cid, 'all', 20);
            if ($adm) { $r['qn'] = (int)q('SELECT COUNT(*) FROM quiz_questions')->fetchColumn(); $r['dg'] = setting('quiz_dg', '1') === '1'; }
            out($r);
        }
        if ($a === 'qz_rank') {
            $mode = isset($in['mode']) ? (string)$in['mode'] : 'all'; if (!in_array($mode, array('all', 'day', 'week', 'correct', 'people'), true)) $mode = 'all';
            $cid = 0;
            if (!empty($in['chat'])) {
                $c = $qzc($in['chat']); if (!$c) out(array('ok' => false, 'error' => 'Guruh topilmadi'), 404);
                if (!$c['manage'] && !q('SELECT 1 FROM quiz_participants WHERE chat_id=? AND user_id=?', array($c['chat_id'], $u['id']))->fetchColumn()) out(array('ok' => false, 'error' => 'Ruxsat yo\'q'), 403);
                $cid = $c['chat_id'];
            }
            out(array('ok' => true, 'mode' => $mode, 'rows' => quiz_rank($cid, $mode, $mode === 'people' ? 200 : 50)));
        }
        if (in_array($a, array('qz_set', 'qz_send', 'qz_diag', 'qz_toggle'), true)) {
