            if (!$c) out(array('ok' => false, 'error' => 'Guruh topilmadi'), 404);
            if (!$c['manage']) out(array('ok' => false, 'error' => 'Faqat guruhni qo\'shgan egasi yoki admin boshqaradi'), 403);
            if ($a === 'qz_diag') { $cf = quiz_cfg($c['chat_id']); out(array('ok' => true, 'diag' => quiz_diag($c['chat_id'], $cf['mode']))); }
            if ($a === 'qz_send') { $r = quiz_start($c['chat_id']); out(array('ok' => $r[0], 'error' => $r[1])); }
            if ($a === 'qz_toggle') {   /* «Kanal va guruhlarim» ro'yxatidan: yoqilsa birinchi savol keyingi daqiqada (next_at enabled'dan oldin hisoblanadi) */
                q('INSERT INTO quiz_settings (chat_id,enabled,next_at,updated_at,mode) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE next_at=IF(VALUES(enabled)=1 AND enabled=0, VALUES(next_at), next_at), q_done=IF(VALUES(enabled)=1 AND enabled=0, 0, q_done), round_from=IF(VALUES(enabled)=1 AND enabled=0, VALUES(updated_at), round_from), enabled=VALUES(enabled), updated_at=VALUES(updated_at)',
                    array($c['chat_id'], !empty($in['on']) ? 1 : 0, time(), time(), 'test'));
                out(array('ok' => true));
            }
            $src = isset($in['src']) && $in['src'] === 'pv' ? 'pv' : 'qz'; $pvt = (int)(isset($in['pvt']) ? $in['pvt'] : 0); $cat = '';
            if ($src === 'pv') {
                if ($pvt && !q('SELECT 1 FROM pv_topics WHERE id=?', array($pvt))->fetchColumn()) out(array('ok' => false, 'error' => 'Mavzu topilmadi'), 422);
                if (!(int)q('SELECT COUNT(*) FROM pv_questions WHERE demo=0' . ($pvt ? ' AND topic_id=' . $pvt : ''))->fetchColumn()) out(array('ok' => false, 'error' => 'Tanlangan mavzuda hali Prava savoli yo\'q — boshqasini tanlang'), 422);
            } else {
            $cat = trim((string)(isset($in['cat']) ? $in['cat'] : ''), '/'); if (quiz_path($cat) === null) out(array('ok' => false, 'error' => 'Bo\'lim noto\'g\'ri'), 422);
            if ($cat !== '' && !(int)q('SELECT COUNT(*) FROM quiz_questions WHERE cat=? OR cat LIKE ?', array($cat, $cat . '/%'))->fetchColumn()) out(array('ok' => false, 'error' => '«' . quiz_label($cat) . '» bo\'limida hali savol yo\'q — boshqasini tanlang yoki adminga yozing'), 422);
            }
            $iv = (int)(isset($in['interval']) ? $in['interval'] : 10); $sec = (int)(isset($in['sec']) ? $in['sec'] : 60); $pts = (int)(isset($in['points']) ? $in['points'] : 10);
            if ($iv < 1 || $iv > 1440) out(array('ok' => false, 'error' => 'Interval 1–1440 daqiqa bo\'lsin'), 422);
            if ($sec < 15 || $sec > 600) out(array('ok' => false, 'error' => 'Javob vaqti 15–600 soniya bo\'lsin'), 422);
            if ($pts < 1 || $pts > 1000) out(array('ok' => false, 'error' => 'Ochko 1–1000 bo\'lsin'), 422);
            $on = !empty($in['on']) ? 1 : 0; $old = quiz_cfg($c['chat_id']);
            $mode = 'test';
            $next = $on && !(int)$old['enabled'] ? time() : (int)$old['next_at'];   /* yoqilganda birinchi savol darhol (keyingi cron) */
            $cnt = (int)$old['q_total'];
            if (isset($in['count'])) { $cnt = (int)$in['count']; if ($cnt < 10 || $cnt > 30) out(array('ok' => false, 'error' => 'Savollar soni 10–30 bo\'lsin'), 422); }
            $fresh = $on && !(int)$old['enabled'];   /* yangi o'yin: hisob noldan */
            $qd = $fresh ? 0 : (int)$old['q_done']; $rf = $fresh ? time() : (int)$old['round_from'];
            q('INSERT INTO quiz_settings (chat_id,enabled,cat,interval_min,answer_sec,points,next_at,updated_at,mode,q_total,q_done,round_from,src,pv_topic) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled), cat=VALUES(cat),
                interval_min=VALUES(interval_min), answer_sec=VALUES(answer_sec), points=VALUES(points), next_at=VALUES(next_at), updated_at=VALUES(updated_at), mode=VALUES(mode), q_total=VALUES(q_total), q_done=VALUES(q_done), round_from=VALUES(round_from), src=VALUES(src), pv_topic=VALUES(pv_topic)', array($c['chat_id'], $on, $cat, $iv, $sec, $pts, $next, time(), $mode, $cnt, $qd, $rf, $src, $pvt));
