--g1:linear-gradient(145deg,#7aa8ff,#3b6fe0);--g2:linear-gradient(145deg,#4fe0c0,#10a58f);--g3:linear-gradient(145deg,#ffd166,#ff9f43);--g4:linear-gradient(145deg,#c4a8ff,#7c4dff);--g5:linear-gradient(145deg,#5eead4,#0d9488);--g6:linear-gradient(145deg,#ff9ed0,#ec4899);--g7:linear-gradient(145deg,#ff9a90,#ef4444);--g8:linear-gradient(145deg,#c3b6e0,#8c7aae);--g9:linear-gradient(145deg,#dca0ff,#9b5cf6)}
html.dark{--badb:rgba(251,113,133,.16);--okb:rgba(94,234,212,.14);--warnb:rgba(251,191,36,.14);--bg:#07142a;--cd:#0f2038;--in:#162a46;--tx:#ecfeff;--sub:#8fc7d4;--ln:rgba(255,255,255,.1);--soft:#12395a;--ac:#5eead4;--ac2:#38bdf8;--g:#86efac;--gs:#103a2e;--r:#fb7185;--sw:#2a4162;--sh:0 10px 30px rgba(0,0,0,.35);--btx:#03222b;--h1:#0ea5a4;--h2:#2563eb;--h3:#7c3aed;--t1:#86efac;--t2:#2dd4bf;
--g1:linear-gradient(145deg,#6ccbff,#2563eb);--g2:linear-gradient(145deg,#5eead4,#0d9488);--g3:linear-gradient(145deg,#fde68a,#f59e0b);--g4:linear-gradient(145deg,#c4b5fd,#7c3aed);--g5:linear-gradient(145deg,#67e8f9,#0891b2);--g6:linear-gradient(145deg,#f9a8d4,#db2777);--g7:linear-gradient(145deg,#fda4af,#e11d48);--g8:linear-gradient(145deg,#a5b4c8,#475569);--g9:linear-gradient(145deg,#d8b4fe,#9333ea)}
html:not(.dark){background:linear-gradient(180deg,#fff0e4 0%,#ffe5ee 42%,#eee8ff 100%) fixed}
html.dark{background:radial-gradient(120% 45% at 85% -5%,#0e7490 0%,transparent 60%),radial-gradient(90% 40% at 0% 14%,#5b21b6 0%,transparent 60%),#07142a fixed}
html body{background:transparent;font-family:ui-rounded,"SF Pro Rounded","Nunito",-apple-system,"SF Pro Text",Inter,Roboto,"Segoe UI",Arial,sans-serif;color:var(--tx)}
html .th,html .top{background:transparent}
html #gate,html .md{background:var(--bg)}
html h1{font-weight:900;letter-spacing:-.6px}
/* kartalar */
html .card,html .bk,html .cbf,html .mk,html .rb,html .qa,html .sc,html .hmk,html .hob,html .tq-a,html .tq-st>div,html .stg>div,html .hx-dn,html .ag,html .dwc,html .lr:not(.in),html .gift{border-radius:24px}
html.dark .card,html.dark .bk,html.dark .cbf,html.dark .mk,html.dark .rb,html.dark .qa,html.dark .sc,html.dark .hob,html.dark .tq-a,html.dark .tq-st>div,html.dark .stg>div,html.dark .hx-dn,html.dark .ag,html.dark .lr:not(.in){border:1px solid var(--ln)}
html .lr:not(.in){border-radius:20px}
/* tugmalar */
html .btn{background:linear-gradient(135deg,var(--ac2),var(--ac));color:var(--btx);border-radius:16px;font-weight:800;box-shadow:0 10px 22px color-mix(in srgb,var(--ac) 38%,transparent),inset 0 1px 0 rgba(255,255,255,.35)}
html .btn.s{background:var(--soft);color:var(--ac);box-shadow:none}
html .bkb{color:var(--ac)}
html .chip{background:var(--in);color:var(--ac)}
html .chip.on,html .tb.on{background:linear-gradient(135deg,var(--ac2),var(--ac));color:var(--btx)}
html input:focus,html select:focus,html textarea:focus{border-color:var(--ac);box-shadow:0 0 0 4px color-mix(in srgb,var(--ac) 22%,transparent)}
html input[type=checkbox]:checked,html .sw.on{background:var(--g)}
html .tag{background:var(--soft);color:var(--ac)}
html #toast{background:rgba(35,18,44,.94)}html.dark #toast{background:rgba(3,34,43,.94);border:1px solid var(--ln)}
/* bosh sahifa: hero */
html .tq-hero{border-radius:28px;padding:16px 18px 18px;background:linear-gradient(135deg,var(--h1) 0%,var(--h2) 55%,var(--h3) 115%);box-shadow:0 22px 44px color-mix(in srgb,var(--h2) 42%,transparent);border:1px solid rgba(255,255,255,.18)}
html .tq-hero:before{content:"";position:absolute;right:-50px;top:-60px;width:230px;height:230px;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.4),transparent 68%)}
html .tq-hero:after{content:"";position:absolute;left:-50px;bottom:-80px;width:200px;height:200px;border-radius:50%;background:radial-gradient(circle,rgba(253,224,71,.45),transparent 70%)}
html .tq-hero b{font-size:21px;font-weight:900;letter-spacing:-.5px;line-height:1.15;text-shadow:0 2px 10px rgba(80,20,70,.25)}
html .tq-hero p{font-size:13px}
html .tq-hp{opacity:.28;width:120px;height:120px;right:-8px;top:-6px;z-index:0}
html .tq-st>div{padding:10px 11px}
html .tq-sv b{font-weight:900}
html .hx-dni{width:52px;height:52px;border-radius:0;background:url(?hxd=balans&v=1) center/100% 100% no-repeat;box-shadow:none;filter:drop-shadow(0 6px 10px rgba(0,0,0,.4))}html .hx-dni svg{display:none}
html .hx-c{border-radius:24px;box-shadow:0 14px 28px color-mix(in srgb,var(--h2) 32%,transparent),inset 0 1px 0 rgba(255,255,255,.3)}
html .hx-c.k{background:linear-gradient(120deg,var(--h1),var(--h2))}
html .hx-c.g{background:linear-gradient(120deg,var(--t1),var(--t2));box-shadow:0 14px 28px color-mix(in srgb,var(--t1) 34%,transparent),inset 0 1px 0 rgba(255,255,255,.3)}
html.dark .hx-c.g{color:#04312a}html.dark .hx-c.g .hx-ci{background:rgba(0,0,0,.14)}
/* ikonka kataklari (bosh sahifa, ro'yxatlar, admin) */
html .c1,html .tq-k{background:var(--g1)}html .c2,html .tq-g{background:var(--g2)}html .c3{background:var(--g3)}html .c4{background:var(--g4)}html .c5{background:var(--g5)}html .c6{background:var(--g6)}html .c7{background:var(--g7)}html .c8{background:var(--g8)}html .c9{background:var(--g9)}
html .hx-g .tq-s .tq-i,html .tq-i,html .lr .li,html .sti,html .ti,html .tl{box-shadow:inset 0 2px 3px rgba(255,255,255,.55),inset 0 -3px 6px rgba(0,0,0,.1),0 9px 18px rgba(0,0,0,.14)}
html .hx-g .tq-s .tq-i{border-radius:26%}
html .hx-g .tq-s b{font-weight:700;font-size:11.5px}
html .ai.c1{background:var(--g1)!important}html .ai.c2{background:var(--g2)!important}html .ai.c3{background:var(--g3)!important}html .ai.c4{background:var(--g4)!important}html .ai.c5{background:var(--g5)!important}html .ai.c6{background:var(--g6)!important}html .ai.c7{background:var(--g7)!important}html .ai.c8{background:var(--g8)!important}html .ai.c9{background:var(--g9)!important}
html .ar:not(.bl) .ai{width:34px;height:34px;border-radius:12px;box-shadow:inset 0 2px 3px rgba(255,255,255,.5),0 6px 12px rgba(0,0,0,.12)!important}
