<script>
var tg=window.Telegram.WebApp;tg.ready();tg.expand();try{tg.disableVerticalSwipes()}catch(e){}document.addEventListener('gesturestart',function(e){e.preventDefault()});document.addEventListener('touchmove',function(e){if(e.touches&&e.touches.length>1)e.preventDefault()},{passive:false});function thm(){document.documentElement.classList.add('dark');try{tg.setHeaderColor('#07142a');tg.setBackgroundColor('#07142a')}catch(e){}}thm();try{tg.onEvent('themeChanged',thm)}catch(e){}
var BOTU=<?php echo json_encode(BOT_USERNAME); ?>,R=[],ADM=false,$=function(i){return document.getElementById(i)};
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function f(n){return n==null?'—':Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g,' ')}
function ar(d){return d==null||+d==0?'':(d>0?' <span class="g">▲'+f(Math.abs(d))+'</span>':' <span class="r">▼'+f(Math.abs(d))+'</span>')}
function toast(m){var t=$('toast');t.textContent=m;t.style.display='block';setTimeout(function(){t.style.display='none'},3500)}
function devId(){try{var d=localStorage.getItem('dv');if(!d||!/^[a-f0-9]{16,32}$/.test(d)){var x=new Uint8Array(12);crypto.getRandomValues(x);d=Array.prototype.map.call(x,function(v){return ('0'+v.toString(16)).slice(-2)}).join('');localStorage.setItem('dv',d)}return d}catch(e){return window.__dv||(window.__dv='0123456789abcdef'+Math.random().toString(16).slice(2,10).padEnd(8,'0'))}}
var APC=/^(wallet|nk_list|vs_list|p5_get|rz_get|hw_get)$/,APU=(window.tg&&tg.initDataUnsafe&&tg.initDataUnsafe.user&&tg.initDataUnsafe.user.id)||0;
function offl(on){var e=document.getElementById('offl');if(!e){if(!on)return;e=document.createElement('div');e.id='offl';e.style.cssText='position:fixed;left:0;right:0;top:0;z-index:98;background:#fff4e5;color:#8a5a00;font-size:12px;text-align:center;padding:4px';e.textContent='📴 Internet yo\'q — oxirgi saqlangan ma\'lumot ko\'rsatilmoqda';document.body.appendChild(e)}e.style.display=on?'block':'none'}
function api(a,b){return fetch('?api='+a,{method:'POST',headers:{'X-Init':tg.initData,'X-Dev':devId(),'Content-Type':'application/json'},body:JSON.stringify(b||{})}).then(function(r){return r.json()}).then(function(j){if(j.tfa)return tfa().then(function(ok){return ok?api(a,b):{ok:false}});if(!j.ok&&j.error&&a!=='rates')toast(j.error);if(APC.test(a)&&j.ok){try{localStorage.setItem('ac_'+APU+'_'+a,JSON.stringify(j))}catch(e){}}offl(false);return j}).catch(function(){if(APC.test(a)){try{var c=JSON.parse(localStorage.getItem('ac_'+APU+'_'+a)||'null');if(c&&c.ok){offl(true);c.offline=true;return c}}catch(e){}}toast('Tarmoq xatosi');return{ok:false}})}
function tfa(){return new Promise(function(res){api('tfa_send').then(function(j){if(!j.ok){res(false);return}var o=document.createElement('div');o.style.cssText='position:fixed;inset:0;background:rgba(8,12,20,.55);z-index:99;display:flex;align-items:center;justify-content:center;padding:16px';o.innerHTML='<div class="card" style="width:100%;max-width:360px;margin:0"><b>🔐 Tasdiqlash kodi</b><div class="sub" style="margin:6px 0 10px">Muhim amal uchun botga 6 xonali kod yuborildi. Kodni kiriting (30 daqiqa qayta so\'ralmaydi).</div><input id="tfa_i" type="text" inputmode="numeric" maxlength="6" placeholder="123456" style="font-size:22px;letter-spacing:6px;text-align:center"><div style="display:flex;gap:8px"><button class="btn" id="tfa_y">Tasdiqlash</button><button class="btn s" id="tfa_n" style="flex:none;width:auto">Bekor</button></div></div>';document.body.appendChild(o);var e=$('tfa_i');e.focus();var done=function(v){o.remove();res(v)};$('tfa_n').onclick=function(){done(false)};$('tfa_y').onclick=function(){api('tfa_ok',{code:e.value}).then(function(k){if(k.ok)done(true)})}})})}
var FL={USD:'🇺🇸',EUR:'🇪🇺',RUB:'🇷🇺',GBP:'🇬🇧',CNY:'🇨🇳',KZT:'🇰🇿'},cur=0,ALL=false,LU='',LE='';
function hm(t){return String(t||'').slice(11,16)}
function logo(n){var k=0;for(var i=0;i<n.length;i++)k=(k*31+n.charCodeAt(i))%360;var c=(n.replace(/[^A-Za-zА-Яа-я]/g,'')||'?').charAt(0).toUpperCase();return '<div class="lo" style="background:hsl('+k+',60%,42%)">'+c+'</div>'}
function sel(i){cur=i;ALL=false;draw({})}
function row(b){return '<div class="br">'+logo(b.bank)+'<div class="bn"><b>'+esc(b.bank)+'</b><span>🕒 Yangilangan: '+esc(hm(b.at))+(b.stale?' ⚠️ eskirgan':'')+(b.src==="qo'lda kiritilgan"?' · qo\'lda':'')+'</span></div><div class="pl gg">'+f(b.buy)+'</div><div class="pl pp">'+f(b.sell)+'</div><span class="chv">›</span></div>'}
var CC={USD:'#1d84f2',EUR:'#16a34a',RUB:'#f59e0b',GBP:'#db2777',CNY:'#dc2626',KZT:'#7c3aed'};
function fv(v){return +v>=1000?f(v):f2(v)}
function draw(j){if(j.rates)R=j.rates;if(j.last_ok!==undefined){LU=j.last_ok||'';LE=j.last_err||''}
cur=Math.max(0,R.map(function(x){return x.code}).indexOf('USD'));
var U=null,UM=null,UT=null;R.forEach(function(x){if(x.code==='USD'){U=x.official;x.banks.forEach(function(b){if(/mikrokredit|mkb/i.test(b.bank))UM=b;if(/turon/i.test(b.bank))UT=b})}});
var t='<div class="hero"><button class="rfi" id="rf" aria-label="Yangilash"><span id="rft">⟳</span></button>';
if(U)t+='<div class="hl1">🏛 Markaziy bank · 1 AQSH dollari</div><div class="hb">'+f2(U.official).split(',')[0]+'<small class="hdc">,'+f2(U.official).split(',')[1]+'</small> <small>so\'m</small></div>'+(U.d==null||+U.d==0?'':'<div class="hdl '+(U.d>0?'up2':'dn2')+'">'+(U.d>0?'▲ +':'▼ −')+f2(Math.abs(U.d))+' kechagiga nisbatan</div>');else t+='<div class="hl1">🏦 Banklarda dollar kursi</div>';var BA=[];R.forEach(function(x){if(x.code==='USD')x.banks.forEach(function(b){if(+b.buy>0&&!b.stale&&b.src!=='qo\'lda kiritilgan')BA.push(b)})});BA.sort(function(a,b){return +b.buy-+a.buy});if(BA.length)t+='<div class="hmk"><div class="hmh">Bank<span>Olish · Sotish</span></div>'+BA.map(function(b){return '<div style="display:flex;justify-content:space-between;align-items:center;padding:7px 0;border-top:1px solid #ffffff22"><span>'+esc(b.bank)+'</span><span><b style="color:#7dffb0">'+f(b.buy)+'</b> · <b style="color:#ffb3b3">'+f(b.sell)+'</b></span></div>'}).join('')+'</div>';


