function tqs(){api('chats').then(function(j){TQC=(j.chats||[]).filter(function(c){return c.status==='approved'});var F={tqpr:'send_c',tqwx:'wx_on',tqa:'send_a',tqb:'send_b',tqev:'ev_on'};Object.keys(F).forEach(function(id){var e=$(id);if(e)e.checked=TQC.some(function(c){return c[F[id]]==1})});for(var d=1;d<=7;d++){var e=$('dpd'+d);if(e)e.checked=TQC.some(function(c){return c.dp_on==1&&(!c.dp_days||c.dp_days.charAt(d-1)==='1')});var f=$('evd'+d);if(f)f.checked=TQC.some(function(c){return c.ev_on==1&&(!c.ev_days||c.ev_days.charAt(d-1)==='1')})}})}
function tqf(k,el){var on=el.checked;if(!TQC.length){el.checked=false;toast('Avval kanal yoki guruh qo\'shing');return}api('flag_all',{f:k,on:on?1:0}).then(function(j){if(!j.ok){el.checked=!on;return}var K={ev:['ev_on','Tungi xabar'],pr:['send_c','Namoz vaqtlari'],wx:['wx_on','Ob-havo'],a:['send_a','Dollar kursi'],b:['send_b','Valyutalar']}[k];TQC.forEach(function(c){c[K[0]]=on?1:0});toast(K[1]+(on?' yoqildi ✅':' o\'chirildi'))})}
var DPN=['Dushanba','Seshanba','Chorshanba','Payshanba','Juma','Shanba','Yakshanba'];
function evd(d,el){var on=el.checked;if(!TQC.length){el.checked=false;toast('Avval kanal yoki guruh qo\'shing');return}api('ev_day',{d:d,on:on?1:0}).then(function(j){if(!j.ok){el.checked=!on;return}toast(DPN[d-1]+(on?' yoqildi ✅':' o\'chirildi'));tqs()})}
function dpd(d,el){var on=el.checked;if(!TQC.length){el.checked=false;toast('Avval kanal yoki guruh qo\'shing');return}api('dp_day',{d:d,on:on?1:0}).then(function(j){if(!j.ok){el.checked=!on;return}toast(DPN[d-1]+(on?' yoqildi ✅':' o\'chirildi'));tqs()})}
/* Rasm tagidagi matn: egasi o'zi yozadi yoki namuna ishlatiladi */
var UCD={},UCH={a:'{sana} — bugungi sana.',b:'{sana} — bugungi sana.',c:'{namoz} — namoz nomi, {sana} — sana.',w:'{sana} — bugungi sana.'};
function ucl(k){var e=$('ucw_'+k);if(!e)return;api('ucap',{k:k}).then(function(j){if(!j.ok)return;UCD[k]=j.def;e.innerHTML='<div class="card" style="margin-top:12px"><b>✍️ Rasm tagidagi matn</b><p class="sub" style="margin:4px 0 8px">Kanal va guruhlaringizga yuboriladigan rasm tagiga o\'zingiz yozing. Bo\'sh qoldirsangiz — namuna matn qo\'yiladi. '+UCH[k]+'</p><textarea id="uc_'+k+'" rows="5" maxlength="1000" placeholder="'+esc(j.def)+'">'+esc(j.text)+'</textarea><div style="display:flex;gap:8px;margin-top:8px"><button class="btn" style="flex:1" onclick="ucs(\''+k+'\')">Saqlash</button><button class="btn s" onclick="$(\'uc_'+k+'\').value=UCD[\''+k+'\']">Namunani qo\'yish</button></div><button class="btn s" style="width:100%;margin-top:8px" onclick="smp(\''+k+'\',this)">📩 Namunani o\'zimga yuborish</button><p class="sub" style="margin:6px 2px 0">Bot sizga xuddi kanal/guruhga boradigan rasm va matnni yuboradi.</p></div>'})}
function smp(k,b){var t=$('uc_'+k),go2=function(){if(b)b.disabled=true;api('sample',{k:k}).then(function(j){if(b)b.disabled=false;if(j.ok)toast('Yuborildi ✅ Botdagi chatingizni oching')})};if(t)api('ucap',{k:k,text:t.value}).then(go2);else go2()}
function ucs(k){api('ucap',{k:k,text:$('uc_'+k).value}).then(function(j){if(j.ok)toast(j.text?'Saqlandi ✅':'Namuna matn ishlatiladi ✅')})}
/* Profil: foydalanuvchi qo'shgan kanal va guruhlar — alohida kataklarda */
function mych(){var e=$('mych');if(!e)return;api('chats').then(function(j){if(!j.ok){e.innerHTML='';return}var L=j.chats||[],IC={Kanal:['tq-k','<path d="M21 3 10 14"/><path d="M21 3l-7 18-4-7-7-4z"/>'],Guruh:['tq-g','<circle cx="9" cy="8.2" r="3.2"/><path d="M3.2 19c0-3.3 2.6-5.6 5.8-5.6s5.8 2.3 5.8 5.6"/><circle cx="17.2" cy="9.2" r="2.5"/><path d="M16.4 13.7c2.6.2 4.4 2.2 4.4 5.3"/>']};
e.innerHTML='<div class="row" style="margin:4px 2px 8px"><b>Kanal va guruhlarim</b><span class="sub">'+L.length+' ta</span></div>'+(L.length?'<div class="tq-row" style="margin-bottom:12px">'+L.map(function(c){var ok=c.status==='approved'&&c.blocked!='1',ic=IC[c.ctype]||IC.Kanal;return '<button class="tq-s" onclick="go(\'my\',\''+(c.ctype==='Guruh'?'Guruh':'Kanal')+'\')"><span class="tq-i '+ic[0]+'"><svg viewBox="0 0 24 24">'+ic[1]+'</svg></span><b style="max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(c.username||'—')+'</b><span class="tq-u">'+(c.ctype==='Guruh'?'Guruh':'Kanal')+' · '+(ok?'faol':(c.blocked=='1'?'bloklangan':(CST[c.status]||esc(c.status))))+'</span><span class="tq-ok">'+(ok?'✅':'⚠️')+'</span></button>'}).join('')+'</div>':'<div class="card sub" style="margin-bottom:12px">Hali kanal yoki guruh qo\'shilmagan. Bosh sahifadagi «Kanal qo\'shish» yoki «Guruh qo\'shish» orqali qo\'shing.</div>')})}
function coOpen(id){var e=$('co'+id);e.innerHTML='<div class="sk"></div>';api('co_list',{id:id}).then(function(j){if(j.ok)coDraw(id,j);else e.innerHTML=''})}
function coDraw(id,j){$('co'+id).innerHTML=(j.list.length?j.list.map(function(x){return '<div class="row sub" style="padding:6px 0;border-bottom:1px solid var(--ln)"><span>'+esc(x.name||('ID '+x.user_id))+(x.username?' @'+esc(x.username):'')+'</span>'+(j.own?'<button class="btn s" style="flex:none" onclick="coDel('+id+','+x.user_id+')">🗑</button>':'')+'</div>'}).join(''):'<p class="sub">Hali hamkor admin yo\'q.</p>')+(j.own?'<div style="display:flex;gap:8px;margin-top:8px"><input id="coi'+id+'" placeholder="@username yoki Telegram ID" style="flex:1"><button class="btn s" style="flex:none" onclick="coAdd('+id+')">➕</button></div><p class="sub" style="margin-top:4px">Qo\'shiladigan odam avval botga /start bosgan bo\'lishi kerak.</p>':'<p class="sub">Siz bu yerda hamkor adminsiz.</p>')}
function coAdd(id){var v=$('coi'+id).value.trim();if(!v)return;api('co_add',{id:id,who:v}).then(function(j){if(j.ok){toast('Qo\'shildi ✅');coDraw(id,j)}})}
function coDel(id,uid){cf('Hamkor admin olib tashlansinmi?',function(y){if(y)api('co_del',{id:id,uid:uid}).then(function(j){if(j.ok)coDraw(id,j)})})}
var EVC=null;
function evl(){api('ev_info').then(function(j){if(!j.ok)return;EVC=j;var C=j.cfg,e=$('evtm');if(e)e.textContent='Har kuni '+C.time+' da kanal va guruhlaringizga «Xayrli tun» yuboriladi. Qaysi kunlari yuborilishini tanlang.'+(C.on?'':' (Hozir butunlay o\'chirilgan.)')})}
function evla(){api('ev_info').then(function(j){if(!j.ok)return;EVC=j;var C=j.cfg,b=$('evba');if(!b||!C.days)return;
b.innerHTML='<p class="sub" style="margin-bottom:12px">Haftaning har kuni uchun alohida matn, video va ovoz. Video baza kanaldan olinadi: botni baza kanalga administrator qiling, videoni joylang va post havolasini (Копировать ссылку) kiriting. Matnda {kun} — hafta kuni, {sana} — bugungi sana, {hijriy} — hijriy sana. Qalin: &lt;b&gt;...&lt;/b&gt;.</p><div class="card"><div class="row"><b>⏰ Yuborish vaqti (Toshkent)</b><button class="chip'+(C.on?' on':'')+'" onclick="evaf(0)">'+(C.on?'✅ Yoqilgan':'⛔ O\'chirilgan')+'</button></div><input id="ev_tm" type="time" value="'+esc(C.time)+'"><div class="sub">'+C.n+' ta kanal/guruh · oxirgi: '+esc(C.last||'—')+'</div></div>'+C.days.map(function(x){return '<div class="card"><div class="row"><b>'+esc(x.name)+'</b><button class="chip'+(x.o?' on':'')+'" onclick="evaf('+x.d+')">'+(x.o?'✅ Yoqilgan':'⬜ O\'chirilgan')+'</button></div><input id="ev_v'+x.d+'" placeholder="Video: https://t.me/c/1234567890/45" value="'+esc(x.v)+'"><input id="ev_a'+x.d+'" placeholder="🔊 Ovoz (mp3): https://t.me/c/1234567890/46" value="'+esc(x.a||'')+'"><textarea id="ev_t'+x.d+'" rows="7" maxlength="1024" placeholder="Matn...">'+esc(x.t)+'</textarea><button class="btn s" onclick="evat('+x.d+')">🧪 Menga yuborish</button></div>'}).join('')+'<button class="btn" onclick="evs()">💾 Saqlash</button>'})}
function evv(){var o={time:$('ev_tm').value,days:{}};EVC.cfg.days.forEach(function(x){o.days[x.d]={v:$('ev_v'+x.d).value.trim(),a:$('ev_a'+x.d).value.trim(),t:$('ev_t'+x.d).value}});return o}
function evs(cb){api('adm_ev',evv()).then(function(j){if(!j.ok)return;EVC.cfg=j.cfg;if(cb)cb();else{toast('Saqlandi ✅');evla()}})}
function evaf(d){var C=EVC.cfg,on=d?!C.days[d-1].o:!C.on;api('adm_ev_flag',{d:d,on:on?1:0}).then(function(j){if(j.ok){EVC.cfg=j.cfg;evla()}})}
function evat(d){evs(function(){toast('Yuborilmoqda...');api('ev_test',{d:d}).then(function(j){if(j.ok)toast(j.vo?'Xabar ketdi, lekin ovoz yuborilmadi: '+j.vo:'Sizga yuborildi ✅')})})}
function evt(){toast('Yuborilmoqda...');api('ev_test').then(function(j){if(j.ok)toast(j.vo?'Tabrik ketdi, lekin ovoz yuborilmadi: '+j.vo:'Sizga yuborildi ✅')})}
function wal(){api('ev_info').then(function(j){var b=$('wab');if(!b||!j.ok)return;b.innerHTML='<div class="card" style="margin-top:10px"><div class="row"><div><b>⚠️ Ob-havo ogohlantirishi</b><div class="sub">Kuchli shamol, jazirama, qattiq sovuq, do\'l, kuchli qor yoki jala kutilsa — ob-havo yoqilgan kanal va guruhlarga ertalab alohida ogohlantirish keladi.'+(j.wa_last?' Oxirgi: '+esc(j.wa_last):'')+'</div></div>'+'</div></div>'})}
function wala(){api('ev_info').then(function(j){var b=$('waba');if(!b||!j.ok)return;b.innerHTML='<div class="card"><div class="row"><div><b>⚠️ Ob-havo ogohlantirishi</b><div class="sub">Kuchli shamol, jazirama, qattiq sovuq, do\'l, kuchli qor yoki jala kutilsa — ob-havo yoqilgan kanal va guruhlarga ertalab alohida ogohlantirish yuboriladi.'+(j.wa_last?' Oxirgi: '+esc(j.wa_last):'')+'</div></div><span style="cursor:pointer;flex:none" onclick="waf(this)">'+ck(j.wa)+'</span></div></div>'})}
function waf(el){var on=!el.firstChild.classList.contains('on');api('adm_wa',{on:on?1:0}).then(function(j){if(j.ok){el.firstChild.classList.toggle('on',j.wa);toast(j.wa?'Yoqildi ✅':'O\'chirildi')}})}
var VZ={cat:'',my:null,list:null};
function vzl(){var b=$('vzb');b.innerHTML='<div class="sk"></div><div class="sk"></div>';Promise.all([api('vz_my'),api('vz_list',{cat:VZ.cat})]).then(function(r){if(!r[0].ok||!r[1].ok)return;VZ.my=r[0];VZ.list=r[1].list;vzr()})}
function vzn(n){return n?nf(+n):'—'}
function vzr(){var M=VZ.my,C=M.cats,h='<p class="sub" style="margin:-6px 2px 12px">Kanal egalari bir-birini topib, o\'zaro reklama kelishadi. O\'z kanalingizni katalogga qo\'shing va boshqalarga taklif yuboring.</p>';
h+='<div class="row" style="margin:4px 2px 8px"><b>📢 Mening kanallarim katalogda</b></div>'+(M.chats.length?M.chats.map(function(c){return '<div class="card"><div class="row"><b>'+esc(c.username)+'</b><span class="sub">'+vzn(c.members)+' · '+esc(c.ctype)+'</span></div><label class="lr in"><span class="lt"><b>Katalogda ko\'rsatish</b><span>Boshqalar sizga taklif yubora oladi</span></span><input type="checkbox" id="vzo'+c.id+'"'+(c.vz_on==1?' checked':'')+'></label><select id="vzc'+c.id+'">'+C.map(function(x){return '<option'+(c.vz_cat===x?' selected':'')+'>'+esc(x)+'</option>'}).join('')+'</select><input id="vzd'+c.id+'" maxlength="200" placeholder="Qisqa tavsif: mavzu, auditoriya, shartlar" value="'+esc(c.vz_desc||'')+'"><button class="btn s" onclick="vzs('+c.id+')">💾 Saqlash</button></div>'}).join(''):'<div class="card sub">Avval «Kanal qo\'shish» orqali kanal yoki guruh qo\'shing.</div>');
h+='<div class="row" style="margin:16px 2px 8px"><b>🔎 Katalog</b><span class="sub">'+VZ.list.length+' ta</span></div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px">'+[''].concat(C).map(function(x){return '<button class="btn'+(VZ.cat===x?'':' s')+'" style="width:auto;flex:none;padding:6px 12px;font-size:13px" onclick="VZ.cat=\''+x.replace(/'/g,"\\'")+'\';vzl()">'+(x?esc(x):'Hammasi')+'</button>'}).join('')+'</div>';
h+=VZ.list.length?VZ.list.map(function(c){return '<div class="card"><div class="row"><div style="min-width:0"><b>'+esc(c.username)+'</b><div class="sub">'+esc(c.vz_cat||'Boshqa')+' · '+vzn(c.members)+' '+(c.ctype==='Kanal'?'obunachi':'a\'zo')+'</div></div><button class="btn s" style="flex:none" onclick="vzf('+c.id+')">🤝 Taklif</button></div>'+(c.vz_desc?'<div class="sub" style="margin-top:6px">'+esc(c.vz_desc)+'</div>':'')+'<div id="vzf'+c.id+'"></div></div>'}).join(''):'<div class="card sub">Bu bo\'limda hozircha kanal yo\'q.</div>';
$('vzb').innerHTML=h}
function vzs(id){api('vz_set',{id:id,on:$('vzo'+id).checked?1:0,cat:$('vzc'+id).value,desc:$('vzd'+id).value}).then(function(j){if(j.ok)toast('Saqlandi ✅')})}
function vzf(id){var M=VZ.my.chats,e=$('vzf'+id);if(!M.length){toast('Avval o\'z kanalingizni qo\'shing');return}e.innerHTML='<div style="margin-top:8px"><select id="vzm'+id+'">'+M.map(function(c){return '<option value="'+c.id+'">'+esc(c.username)+'</option>'}).join('')+'</select><textarea id="vzt'+id+'" rows="3" maxlength="300" placeholder="Taklifingiz: masalan, 1/24 formatda o\'zaro post"></textarea><button class="btn" onclick="vzsend('+id+')">📩 Yuborish</button></div>'}
function vzsend(id){api('vz_offer',{from:$('vzm'+id).value,to:id,text:$('vzt'+id).value}).then(function(j){if(j.ok){toast('Taklif yuborildi ✅');$('vzf'+id).innerHTML='<p class="sub" style="margin-top:6px;color:var(--g)">✅ Taklif yuborildi — kanal egasi siz bilan bog\'lanadi.</p>'}})}
function psv(id){var t=$('pst'+id).value.trim(),on=$('ps'+id).checked;if(on&&!t){toast('Imzo matnini yozing');return}api('chat_sig',{id:id,on:on?1:0,text:t}).then(function(j){if(j.ok)toast(j.on?'Imzo yoqildi ✅':'Imzo o\'chirildi')})}
function chats(){api('chats').then(function(j){$('chl').innerHTML=(j.chats||[]).filter(function(c){return c.ctype===CW}).map(function(c){var ok=c.status==='approved',nm=String(c.username||'');return '<div class="card"><div class="chd"><div class="cav">'+esc((nm.replace(/^@/,'').charAt(0)||'?').toUpperCase())+'</div><b>'+esc(nm)+'</b><div class="cs'+(ok&&c.blocked!='1'?'':' no')+'">● '+(CST[c.status]||esc(c.status))+(c.blocked=='1'?' · 🚫 bloklangan':'')+'</div></div>'+(ok?'<div class="sh2" style="margin-top:14px">Avtomatik xabarlar</div>'+CHI.map(function(x){return '<label class="lr in"><span class="li '+x[3]+'">'+sv2(x[2])+'</span><span class="lt"><b>'+x[4]+'</b><span>'+x[5]+'</span></span><input type="checkbox" id="'+x[0]+c.id+'"'+(c[x[1]]==1?' checked':'')+'></label>'}).join('')+'<div class="lr in tq-off" onclick="toast(\'🌙 Ramazon taqvimi tez kunda ishga tushadi\')"><span class="li c2"><svg viewBox="0 0 24 24"><path d="M15.5 3.5a8.5 8.5 0 1 0 5 13.6A7 7 0 0 1 15.5 3.5z"/><path d="M18 5.5l.7 1.4 1.5.2-1.1 1 .3 1.5-1.4-.7-1.4.7.3-1.5-1.1-1 1.5-.2z"/></svg></span><span class="lt"><b>Ramazon taqvimi</b><span>Saharlik va iftorlik vaqtlari</span></span><span class="tq-badge">Tez kunda</span></div><p class="sub" style="margin:10px 0 12px">Kurs xabarlari faqat narx o\'zgarganda yuboriladi.</p><button class="btn" onclick="sv('+c.id+')">Saqlash</button>'+(c.ctype==='Kanal'?'<div class="sh2" style="margin-top:16px">✍️ Kanal imzosi</div><label class="lr in"><span class="lt"><b>Har bir yangi postga imzo qo\'shish</b><span>Kanalga post joylasangiz — bot tagiga o\'zi qo\'shadi</span></span><input type="checkbox" id="ps'+c.id+'"'+(c.ps_on==1?' checked':'')+'></label><textarea id="pst'+c.id+'" rows="2" maxlength="300" placeholder="👉 '+esc(nm)+' — obuna bo\'ling!">'+esc(c.ps_text||'')+'</textarea>'+(c.ps_err?'<div class="sub" style="color:var(--r);margin:4px 0">⚠️ '+esc(c.ps_err)+'</div>':'')+'<div class="sub" style="margin:4px 0 8px">Bot kanalda «Xabarlarni tahrirlash» huquqiga ega bo\'lishi kerak. Formatlash va post tugmalari saqlanadi.</div><button class="btn s" onclick="psv('+c.id+')">💾 Imzoni saqlash</button><div class="sh2" style="margin-top:16px">🧷 Post tagidagi doimiy tugmalar</div><label class="lr in"><span class="lt"><b>📢 «Do\'stga ulashish» tugmasi</b><span>Har bir yangi postga avtomatik</span></span><input type="checkbox" id="pbs'+c.id+'"'+(c.pb_share==1?' checked':'')+'></label><label class="lr in"><span class="lt"><b>💝 «Qo\'llab-quvvatlash» tugmasi</b><span>Obunachilar balansidan sizga xayriya qiladi'+(+c.don_sum?' · jami: '+fmt(+c.don_sum):'')+'</span></span><input type="checkbox" id="pbd'+c.id+'"'+(c.pb_don==1?' checked':'')+'></label><div style="display:flex;gap:8px"><input id="pbt'+c.id+'" maxlength="40" placeholder="💬 Guruhimiz" value="'+esc(c.pb_text||'')+'" style="flex:1;min-width:0"><input id="pbu'+c.id+'" placeholder="https://t.me/guruh" value="'+esc(c.pb_url||'')+'" style="flex:1.3;min-width:0"></div><div class="sub" style="margin:4px 0 8px">Ikkinchi tugma ixtiyoriy (guruh yoki sayt havolasi). Albom va forward postlarga tugma qo\'shilmaydi.</div><button class="btn s" onclick="chpb('+c.id+')">💾 Tugmalarni saqlash</button>':'')+'<div class="sh2" style="margin-top:16px">⏸ Ta\'til rejimi</div><div class="sub" style="margin:4px 0 6px">'+(+c.paused>j.now?'<b style="color:var(--r)">⏸ '+dmy(c.paused)+' gacha barcha avtomatik xabarlar to\'xtatilgan</b>':'Motam, bayram yoki ta\'til kunlari barcha avtomatik xabarlarni (kurs, namoz, ob-havo, postlar, e\'lonlar) bir bosishda to\'xtating.')+'</div><div style="display:flex;gap:6px;flex-wrap:wrap">'+(+c.paused>j.now?'<button class="btn" style="width:auto" onclick="chp('+c.id+',0)">▶️ Davom ettirish</button>':[1,3,7,14,30].map(function(d){return '<button class="btn s" style="width:auto;flex:none" onclick="chp('+c.id+','+d+')">'+d+' kun</button>'}).join(''))+'</div><div class="sh2" style="margin-top:16px">📊 Pasport</div><div class="sub" style="margin:4px 0 6px">Obunachilar, o\'sish va 