function gdrm(i,all){var g=gdg(i,all),e=$('gx'+(all?'a':'')+i);e.innerHTML='<p class="sub">Yuklanmoqda...</p>';api('rem_list',{id:g.id}).then(function(j){if(j.ok)gdrmd(i,all,j.list)})}
function gdrmd(i,all,L){$('gx'+(all?'a':'')+i).innerHTML='<p style="margin:10px 0 4px"><b>⏰ Eslatmalar</b></p><p class="sub" style="margin:0 0 6px">Guruhda admin yozadi: <b>/eslat 18:00 matn</b> · <b>/eslat 2s matn</b> (m — daqiqa, s — soat, k — kun) · <b>/eslat har kuni 09:00 matn</b> · <b>/eslat har dushanba 09:00 matn</b>.</p>'+(L.length?L.map(function(r){return '<div class="row sub" style="padding:6px 0;border-bottom:1px solid var(--ln);align-items:flex-start"><span>#'+r.id+' · <b>'+esc(r.when)+'</b><br>'+esc(r.body)+'</span><button class="btn s" style="flex:none" onclick="gdrmx('+i+','+(all?1:0)+','+r.id+')">🗑</button></div>'}).join(''):'<p class="sub">Faol eslatma yo\'q.</p>')}
function gdrmx(i,all,rid){var g=gdg(i,all);api('rem_del',{id:g.id,rid:rid}).then(function(j){if(j.ok)gdrmd(i,all,j.list)})}
function gbl(){var e=$('gbl');if(!e)return;e.innerHTML='<p class="sub">Yuklanmoqda...</p>';api('gban_list').then(function(j){if(!j.ok)return;e.innerHTML='<p class="sub" style="margin:4px 0 8px">Jami: <b>'+j.n+'</b>. Guruhlarda /ban qilinganlar shu yerga tushadi va «Umumiy qora ro\'yxat» yoqilgan barcha guruhlarga kira olmaydi.</p>'+(j.list.length?j.list.map(function(x){return '<div class="row sub" style="padding:6px 0;border-bottom:1px solid var(--ln)"><span>'+esc(x.name||('ID '+x.user_id))+' · '+esc(x.chat||'')+' · '+esc(x.reason)+'</span><button class="btn s" style="flex:none" onclick="gbx('+x.user_id+')">Olib tashlash</button></div>'}).join(''):'<p class="sub">Bo\'sh.</p>')})}
function gbx(uid){cf('Qora ro\'yxatdan olib tashlansinmi?',function(y){if(y)api('gban_del',{uid:uid}).then(function(j){if(j.ok)gbl()})})}
function gdrs(id){cf('Xabar guruhga qayta yuborilsinmi?',function(y){if(y)api('guard_restore',{log:id}).then(function(j){if(j.ok)toast('Yuborildi ✅')})})}
/* ---- Postlar ---- */
var POD=null,REP={none:'Bir marta',daily:'Har kuni',weekly:'Har hafta'};
function pol(){api('post_list').then(function(j){if(!j.ok)return;POD=j;por();pcal()})}
var PCM=null;
function pcal(m){var e=$('poc');if(!e||!POD)return;var n=new Date();if(m!=null)PCM=m;if(PCM==null)PCM=n.getFullYear()*12+n.getMonth();var Y=Math.floor(PCM/12),M=PCM%12,first=new Date(Y,M,1),days=new Date(Y,M+1,0).getDate(),off=(first.getDay()+6)%7,by={};
var add=function(d,p){(by[d]=by[d]||[]).push(p)};POD.posts.filter(function(p){return p.active==1}).forEach(function(p){var t=new Date(p.run_at.replace(' ','T'));for(var d=1;d<=days;d++){var c=new Date(Y,M,d,23,59);if(c<t)continue;var dd=new Date(Y,M,d);if(p.rep==='daily'||(p.rep==='weekly'&&dd.getDay()===t.getDay())||(p.rep==='none'&&t.getFullYear()===Y&&t.getMonth()===M&&t.getDate()===d))add(d,p)}});
var MN=['Yanvar','Fevral','Mart','Aprel','May','Iyun','Iyul','Avgust','Sentabr','Oktabr','Noyabr','Dekabr'],h='<div class="card"><div class="row"><button class="btn s" style="flex:none;width:auto" onclick="pcal(PCM-1)">‹</button><b>🗓 '+MN[M]+' '+Y+'</b><button class="btn s" style="flex:none;width:auto" onclick="pcal(PCM+1)">›</button></div><div style="display:grid;grid-template-columns:repeat(7,1fr);gap:4px;margin-top:10px;text-align:center;font-size:12px">'+['Du','Se','Ch','Pa','Ju','Sh','Ya'].map(function(x){return '<div class="sub">'+x+'</div>'}).join('');
for(var i=0;i<off;i++)h+='<div></div>';for(var d=1;d<=days;d++){var L=by[d]||[],td=Y===n.getFullYear()&&M===n.getMonth()&&d===n.getDate();h+='<div onclick="pcd('+d+')" style="cursor:pointer;padding:6px 0;border-radius:10px;background:'+(L.length?'var(--soft)':'transparent')+';'+(td?'outline:2px solid var(--b)':'')+'"><b style="font-size:14px">'+d+'</b><div style="font-size:11px;color:var(--b);min-height:13px">'+(L.length?'● '+L.length:'')+'</div></div>'}
h+='</div><div id="pcd" class="sub" style="margin-top:8px">Kunni bosing — o\'sha kungi postlar ko\'rinadi.</div></div>';e.innerHTML=h;PCAL=by}
var PCAL={};
function pcd(d){var L=PCAL[d]||[];$('pcd').innerHTML=L.length?L.map(function(p){return '<div style="padding:6px 0;border-top:1px solid var(--ln)">🕐 <b>'+esc(p.run_at.slice(11,16))+'</b> · '+esc(p.username)+(p.rep!=='none'?' · 🔁':'')+'<div style="word-break:break-word">'+esc(String(p.body||'[media]').slice(0,80))+'</div></div>'}).join(''):d+'-kunga post rejalashtirilmagan.'}
function pxl(){var e=$('pox');if(!e)return;e.innerHTML='<div class="sk"></div>';Promise.all([api('rss_list'),api('cd_list'),api('sl_list')]).then(function(r){if(!r[0].ok)return;PX={rss:r[0],cd:r[1],sl:r[2]};pxr()})}
var PX=null;
function pxr(){var R=PX.rss,C=PX.cd,S=PX.sl,ch=chopt(R.chats),h='';
h+='<div class="card"><b>📰 Sayt yoki YouTube\'dan avtomatik post</b><div class="sub" style="margin:4px 0 8px">Sayt yoki blogda yangi maqola, YouTube kanalda yangi video chiqsa — kanalingizga sarlavha va havola bilan o\'zi joylanadi (15 daqiqada tekshiriladi). YouTube uchun kanal havolasini kiriting (https://youtube.com/@kanal).</div>'+(R.chats.length?'<select id="rs_c">'+ch+'</select><input id="rs_u" placeholder="https://sayt.uz/feed yoki https://youtube.com/@kanal"><button class="btn" onclick="rsa()">➕ Qo\'shish</button>':'<p class="sub">Avval kanal qo\'shing.</p>')+R.list.map(function(f){return '<div class="row" style="padding:8px 0;border-top:1px solid var(--ln);margin-top:8px"><div style="min-width:0"><b style="font-size:14px;word-break:break-all">'+esc(f.url)+'</b><div class="sub">→ '+esc(f.username)+' · '+f.n+' ta post'+(f.err?' · <span style="color:var(--r)">⚠️ '+esc(f.err)+'</span>':'')+'</div></div><button class="btn s" style="flex:none;width:auto" onclick="rsd('+f.id+')">🗑</button></div>'}).join('')+'</div>';
h+='<div class="card"><b>⏱ Sanoq posti (countdown)</b><div class="sub" style="margin:4px 0 8px">«Aksiyagacha 3 kun qoldi» — post kanalga chiqadi va har soatda o\'zi yangilanadi.</div>'+(C.chats.length?'<select id="cd_c">'+ch+'</select><input id="cd_t" maxlength="200" placeholder="Masalan: Katta aksiyagacha"><p class="sub" style="margin:0">Tugash vaqti</p><input id="cd_e" type="datetime-local" value="'+dtl(60*24*3)+'"><label class="lr in"><span class="lt"><b>Postni tepaga mahkamlash</b></span><input type="checkbox" id="cd_p"></label><button class="btn" onclick="cda()">⏱ Joylash</button>':'')+C.list.map(function(d){return '<div class="row" style="padding:8px 0;border-top:1px solid var(--ln);margin-top:8px"><div><b style="font-size:14px">'+esc(d.title)+'</b><div class="sub">'+esc(d.username)+' · '+new Date(d.end_at*1000).toLocaleString('uz-UZ',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})+(d.done==1?' · ✅ tugagan':'')+'</div></div>'+(d.done==1?'':'<button class="btn s" style="flex:none;width:auto" onclick="cdd('+d.id+')">⏹</button>')+'</div>'}).join('')+'</div>';
h+='<div class="card"><b>🔗 Qisqa havolalar</b><div class="sub" style="margin:4px 0 8px">Postga qisqa havola qo\'ying — necha marta bosilganini shu yerda ko\'rasiz.</div><input id="sl_u" placeholder="Uzun havola: https://..."><input id="sl_k" maxlength="20" placeholder="Qisqa nom (ixtiyoriy): aksiya"><button class="btn" onclick="sla()">🔗 Yaratish</button>'+S.list.map(function(l){var u=S.base+l.code;return '<div style="padding:8px 0;border-top:1px solid var(--ln);margin-top:8px"><div class="row"><b style="font-size:14px">👆 '+nf(+l.clicks)+' marta bosildi</b><button class="btn s" style="flex:none;width:auto" onclick="sld('+l.id+')">🗑</button></div><div class="sub" style="word-break:break-all">'+esc(u)+'</div><div class="sub" style="word-break:break-all">→ '+esc(l.url)+'</div><button class="btn s" style="margin-top:4px;width:auto" onclick="cpyt(\''+esc(u)+'\')">📋 Nusxalash</button></div>'}).join('')+'</div>';
$('pox').innerHTML=h}
function cpyt(t){try{navigator.clipboard.writeText(t);toast('Nusxalandi ✅')}catch(e){toast(t)}}
function rsa(){api('rss_add',{chat:$('rs_c').value,url:$('rs_u').value.trim()}).then(function(j){if(j.ok){toast('Qo\'shildi ✅ Yangi maqolalar kanalga chiqadi');PX.rss=j;pxr()}})}
function rsd(id){cf('RSS manba o\'chirilsinmi?',function(y){if(y)api('rss_del',{id:id}).then(function(j){if(j.ok){PX.rss=j;pxr()}})})}
function cda(){api('cd_add',{chat:$('cd_c').value,title:$('cd_t').value,end_at:$('cd_e').value,pin:$('cd_p').checked?1:0}).then(function(j){if(j.ok){toast('Joylandi ✅');PX.cd=j;pxr()}})}
function cdd(id){api('cd_del',{id:id}).then(function(j){if(j.ok){PX.cd=j;pxr()}})}
function sla(){api('sl_add',{url:$('sl_u').value.trim(),code:$('sl_k').value.trim()}).then(function(j){if(j.ok){toast('Yaratildi ✅');PX.sl=j;pxr()}})}
function sld(id){cf('Havola o\'chirilsinmi?',function(y){if(y)api('sl_del',{id:id}).then(function(j){if(j.ok){PX.sl=j;pxr()}})})}
function gcl(){var e=$('gcb');if(!e)return;api('gc_list').then(function(j){if(j.ok){GCD=j;gcr()}})}
var GCD=null;
function gcr(){var j=GCD,h='<div class="card"><b>🔑 Sovg\'a kodi</b><div class="sub" style="margin:4px 0 8px">Kanalga yashirin kod chiqadi. Kodni botga birinchi yuborgan obunachilar yutadi — tez va qiziqarli o\'yin.</div>'+(j.chats.length?'<select id="gc_c">'+chopt(j.chats)+'</select><input id="gc_p" maxlength="300" placeholder="Sovg\'a: masalan, 20 000 so\'mlik paynet"><div style="display:flex;gap:8px"><input id="gc_k" maxlength="40" placeholder="Kod: BAHOR25" style="flex:1"><input id="gc_n" type="number" inputmode="numeric" min="1" max="100" value="10" style="flex:none;width:90px"></div><button class="btn" onclick="gca()">🎁 Kanalga joylash</button>':'<p class="sub">Avval kanal qo\'shing.</p>')+'</div>';
h+=j.list.map(function(g){return '<div class="card"><div class="row"><b>🎁 '+esc(g.prize)+'</b><span class="sub">'+(g.status==='active'?'🟢 '+g.n+'/'+g.winners:'✅ tugagan')+'</span></div><div class="sub">'+esc(g.username)+' · kod: <b>'+esc(g.code)+'</b></div>'+(g.wins.length?'<div style="margin-top:6px;font-size:14px">'+g.wins.map(function(w,i){return (i+1)+'. '+esc(w.name)+(w.uname?' @'+esc(w.uname):'')}).join('<br>')+'</div>':'')+(g.status==='active'?'<button class="btn s" style="margin-top:8px;width:auto" onclick="gcs('+g.id+')">⏹ Yakunlash</button>':'')+'</div>'}).join('');$('gcb').innerHTML=h}
function gca(){api('gc_add',{chat:$('gc_c').value,prize:$('gc_p').value,code:$('gc_k').value.trim(),winners:$('gc_n').value}).then(function(j){if(j.ok){toast('Kanalga joylandi ✅');GCD=j;gcr()}})}
function gcs(id){cf('Sovg\'a o\'yini yakunlansinmi?',function(y){if(y)api('gc_stop',{id:id}).then(function(j){if(j.ok){GCD=j;gcr()}})})}
function prc(w,id,p){var v=$(id).value.trim();if(!v)return;api('promo_check',{code:v,what:w}).then(function(j){var e=$(id+'_r');if(e)e.innerHTML=j.ok?'<span style="color:var(--g)">✅ '+j.pct+'% chegirma — '+fmt(Math.round(p*(100-j.pct)/100))+'</span>':''})}
function dmy(t){var d=new Date(t*1000),p=function(n){return('0'+n).slice(-2)};return p(d.getDate())+'.'+p(d.getMonth()+1)+'.'+d.getFullYear()}
var PCD=null;
function pcl(){$('pcb').innerHTML='<div class="sk"></div>';api('pc_list').then(function(j){if(!j.ok)return;PCD=j;var h='<p class="sub" style="margin:-6px 2px 12px">Yopiq (pullik) kanal va guruhlar. Obuna balansdan to\'lanadi, kirish havolasi botga keladi. Muddat tugaganda kanaldan chiqarilasiz.</p>';
h+=j.list.length?j.list.map(function(c){var my=+c.my_until>j.now;return '<div class="card"><div class="row"><div style="min-width:0"><b>🔐 '+esc(c.username)+'</b><div class="sub">'+(c.members?nf(+c.members)+' '+(c.ctype==='Kanal'?'obunachi':'a\'zo')+' · ':'')+'oyiga</div></div><b style="flex:none">'+fmt(+c.price)+'</b></div>'+(c.descr?'<div class="sub" style="margin-top:6px">'+esc(c.descr)+'</div>':'')+(my?'<div class="sub" style="margin-top:6px;color:var(--g)">✅ Obunangiz '+dmy(c.my_until)+' gacha</div>':'')+(c.own==1?'<div class="sub" style="margin-top:8px">👤 Bu sizning kanalingiz — sozlamalari «Kanallarim» bo\'limida.</div>':'<div class="pcpk">'+[1,3,6,12].map(function(m){var d=m===3?+c.d3:m===6?+c.d6:m===12?+c.d12:0,t=Math.round(+c.price*m*(100-d)/100);return '<button class="btn s" onclick="pcbuy('+c.id+','+t+','+m+')"><b>'+m+' oy</b><span>'+fmt(t)+'</span>'+(d?'<em>-'+d+'%</em>':'')+'</button>'}).join('')+'</div>'+(!my&&+c.trial>0&&+c.tr_used===0?'<button class="btn" style="margin-top:8px" onclick="pctr('+c.id+','+c.trial+')">🎁 '+c.trial+' kun bepul sinab ko\'rish</button>':'')+(my?'<div class="sub" style="margin-top:6px">🔁 Paketni tanlasangiz, obuna muddati uzayadi.</div>':''))+'</div>'}).join(''):'<div class="card sub">Hozircha pullik kanal yo\'q. Kanal egasi bo\'lsangiz — «Kanallarim» → kanal kartasida «🔐 Pullik obuna»ni yoqing.</div>';$('pcb').innerHTML=h})}
function audsp(id){var t=prompt('Muammoni qisqacha yozing (masalan: reklama 2 soatda o\'chirildi):','');if(t==null)return;if(t.trim().length<5){toast('Muammoni yozing');return}api('auc_dispute',{id:id,note:t.trim()}).then(function(j){if(j.ok){toast('⚖️ Nizo ochildi — admin ko\'rib chiqadi');aul()}})}
function pctr(id,d){cf(d+' kunlik bepul sinov boshlansinmi? Kirish havolasi botga keladi.',function(y){if(y)api('pc_trial',{id:id}).then(function(j){if(j.ok){toast('🎁 Bepul sinov boshlandi — havola botga yuborildi');pcl()}})})}
function pcbuy(id,p,m){m=m||1;cf(m+' oylik obuna: '+fmt(p)+' balansingizdan yechiladi. Davom etilsinmi?',function(y){if(y)api('pc_buy',{id:id,m:m}).then(function(j){if(j.ok){toast('✅ Obuna faollashdi — kirish havolasi botga yuborildi');pcl()}else if(j.need_topup)go('bal')})})}
function pcOpen(id){var e=$('pcs'+id);e.innerHTML='<div class="sk"></div>';api('pc_get',{id:id}).then(function(j){if(j.ok)pcDraw(id,j);else e.innerHTML=''})}
function pcDraw(id,j){var p=j.pc;$('pcs'+id).innerHTML='<label class="lr in"><span class="lt"><b>Pullik obunani yoqish</b><span>Faol obunachilar: '+j.subs+' · jami tushum: '+fmt(+p.earned)+'</span></span><input type="checkbox" id="pco'+id+'"'+(p.on_==1?' checked':'')+'></label><input id="pcp'+id+'" type="number" inputmode="numeric" placeholder="Oylik narx (so\'m)" value="'+(+p.price||'')+'"><input id="pcd'+id+'" maxlength="300" placeholder="Tavsif: nima beriladi (masalan, VIP signal, darslar)" value="'+esc(p.descr||'')+'"><div class="sub" style="margin:2px 0 4px">📦 Paket chegirmalari (%, 0–50):</div><div style="display:flex;gap:8px">'+[['d3','3 oy'],['d6','6 oy'],['d12','12 oy']].map(function(x){return '<label style="flex:1;min-width:0"><span class="sub" style="font-size:12px">'+x[1]+'</span><input id="pc'+x[0]+id+'" type="number" min="0" max="50" inputmode="numeric" value="'+(+p[x[0]]||0)+'"></label>'}).join('')+'</div><label><span class="sub" style="font-size:12px">🎁 Bepul sinov (kun, 0–7; 0 — yo\'q)</span><input id="pctr'+id+'" type="number" min="0" max="7" inputmode="numeric" value="'+(+p.trial||0)+'"></label><div class="sub" style="margin:-4px 0 8px">Pul obunachi balansidan sizning balansingizga tushadi (xizmat haqi '+j.fee+'%). Bot kanalda «Taklif havolasi» va «Bloklash» huquqiga ega bo\'lishi kerak.</div>'+(j.warn?'<div class="sub" style="color:var(--r);margin-bottom:8px">⚠️ '+esc(j.warn)+'</div>':'')+'<button class="btn s" onclick="pcSave('+id+')">💾 Saqlash</button>'}
function pcSave(id){api('pc_set',{id:id,on:$('pco'+id).checked?1:0,price:$('pcp'+id).value,descr:$('pcd'+id).value,d3:$('pcd3'+id).value,d6:$('pcd6'+id).value,d12:$('pcd12'+id).value,trial:$('pctr'+id).value}).then(function(j){if(j.ok){toast(j.warn?'Saqlandi, lekin huquqni tekshiring':'Saqlandi ✅');pcDraw(id,j)}})}
var AUD=null,AUSEL=0,AUIMG='';
var FMT={'24':'1/24 (24 soatda o\'chadi)','48':'2/48 (48 soatda o\'chadi)','0':'doimiy'};
function aul(){$('aub').innerHTML='<div class="sk"></div>';api('auc_list').then(function(j){if(j.ok){AUD=j;aur()}})}
function aur(){var j=AUD,h='<p class="sub" style="margin:-6px 2px 12px">Kanallarga reklamani to\'g\'ridan-to\'g\'ri egasidan oling: narx ochiq, pul faqat reklama joylangach egasiga o\'tadi. 24 soatda javob bo\'lmasa — pul qaytadi.</p>';
h+=j.list.length?j.list.map(function(c){return '<div class="card"><div class="row"><div style="min-width:0"><b>📢 '+esc(c.username)+(c.verified==1?' <span title="TartibOn tasdiqlagan">✅</span>':'')+'</b><div class="sub">'+(c.members?nf(+c.members)+' obunachi · ':'')+esc(c.vz_cat||'Umumiy')+' · '+FMT[c.fmt]+'</div></div><b style="flex:none">'+fmt(+c.price)+'</b></div>'+(c.descr?'<div class="sub" style="margin-top:6px">'+esc(c.descr)+'</div>':'')+(AUSEL==c.id?'<div style="margin-top:8px"><textarea id="aut" rows="4" maxlength="1000" placeholder="Reklama matni"></textarea><label class="up">🖼 Rasm (ixtiyoriy)<input type="file" accept="image/*" style="display:none" onchange="auPick(this)"></label><div id="aupv" class="sub"></div><div style="display:flex;gap:8px"><input id="aup" maxlength="30" placeholder="🎟 Promo-kod" style="flex:1;min-width:0;text-transform:uppercase"><button class="btn s" style="flex:none;width:auto" onclick="prc(\'auc\',\'aup\','+c.price+')">Tekshirish</button></div><div id="aup_r" class="sub" style="margin:-4px 0 8px"></div><button class="btn" onclick="aubuy('+c.id+','+c.price+')">💳 To\'lash va yuborish</button></div>':'<button class="btn s" style="margin-top:8px" onclick="AUSEL='+c.id+';AUIMG=\'\';aur()">🛒 Reklama berish</button>')+'</div>'}).join(''):'<div class="card sub">Hozircha reklama joyi yo\'q. Kanal egasi bo\'lsangiz — kanal kartasida «📣 Reklama birjasi»ni yoqing.</div>';
var ST2={refunded:'↩️ Pul qaytarildi',pending:'⏳ Egasi ko\'rib chiqmoqda',posting:'⏳',posted:'✅ Joylandi',rejected:'❌ Rad etildi (pul qaytdi)',expired:'⌛ Javob bo\'lmadi (pul qaytdi)'};
if(j.mine.length)h+='<div class="card"><b>🛒 Buyurtmalarim</b>'+j.mine.map(function(o){var hold=o.status==='posted'&&+o.paid===0;return '<div style="margin-top:8px"><div class="row"><div><b>'+esc(o.username)+' · '+fmt(+o.price)+'</b><div class="sub">#'+o.id+(hold&&+o.dispute===0?' · 🛡 kafolat '+dtf(new Date(+o.release_at*1000).toISOString().slice(0,16).replace('T',' '))+' gacha':'')+(+o.dispute===1?' · ⚖️ nizo ko\'rib chiqilmoqda':'')+'</div></div><span class="tag">'+(ST2[o.status]||o.status)+'</span></div>'+(hold&&+o.dispute===0?'<button class="btn s" style="margin-top:6px" onclick="audsp('+o.id+')">⚠️ Nizo ochish</button>':'')+'</div>'}).join('')+'</div>';
if(j.sales.length)h+='<div class="card"><b>💰 Sotuvlarim</b>'+j.sales.map(function(o){return '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--ln)"><div class="row"><b>'+esc(o.username)+' · '+fmt(o.price-o.fee)+'</b><span class="tag">'+(ST2[o.status]||o.status)+'</span></div><div class="sub" style="word-break:break-word">'+esc(String(o.body).slice(0,160))+'</div>'+(o.status==='posted'&&+o.paid===0?'<div class="sub" style="margin-top:4px">'+(+o.dispute===1?'⚖️ Xaridor nizo ochdi — admin qarorini kuting':'🛡 Pul kafolatda — reklama turgach balansingizga tushadi')+'</div>':'')+(o.status==='pending'?'<div style="display:flex;gap:8px;margin-top:6px"><button class="btn" onclick="auact('+o.id+',1)">✅ Joylash</button><button class="btn s" onclick="auact('+o.id+',0)">❌ Rad etish</button></div>':'')+'</div>'}).join('')+'</div>';
$('aub').innerHTML=h}
function auPick(i){var f=i.files&&i.files[0];if(!f)return;imgfit(f,1280,1280,false,function(d){AUIMG=d;$('aupv').textContent='🖼 Rasm tanlandi'})}
function aubuy(id,p){var t=$('aut').value.trim();if(t.length<5){toast('Reklama matnini yozing');return}cf(fmt(p)+' balansingizdan yechiladi (rad etilsa qaytadi). Yuborilsinmi?',function(y){if(y)api('auc_buy',{id:id,text:t,image:AUIMG,promo:$('aup').value.trim()}).then(function(j){if(j.ok){toast('✅ Buyurtma kanal egasiga yuborildi');AUSEL=0;AUD=j;aur()}else if(j.need_topup)go('bal')})})}
function auact(id,ok){api('auc_act',{id:id,ok:ok}).then(function(j){if(j.ok){toast(ok?'✅ Joylandi':'Rad etildi');AUD=j;aur()}})}
function auOpen(id){var e=$('aus'+id);e.innerHTML='<div class="sk"></div>';api('auc_get',{id:id}).then(function(j){if(j.ok)auDraw(id,j);else e.innerHTML=''})}
function auDraw(id,j){var p=j.slot;$('aus'+id).innerHTML='<label class="lr in"><span class="lt"><b>Reklama joyini sotish</b><span>Sotilgan: '+j.sold+' ta</span></span><input type="checkbox" id="auo'+id+'"'+(p.on_==1?' checked':'')+'></label><div style="display:flex;gap:8px"><input id="aupr'+id+'" type="number" inputmode="numeric" placeholder="Narx (so\'m)" value="'+(+p.price||'')+'" style="flex:1;min-width:0"><select id="auf'+id+'" style="flex:1;min-width:0">'+['24','48','0'].map(function(k){return '<option value="'+k+'"'+(p.fmt==k?' selected':'')+'>'+FMT[k]+'</option>'}).join('')+'</select></div><input id="aud'+id+'" maxlength="300" placeholder="Shartlar: mavzu cheklovi, joylash vaqti" value="'+esc(p.descr||'')+'"><div class="sub" style="margin:-4px 0 8px">Buyurtma kelganda bot sizga yozadi — «Joylash» bosilsa reklama kanalga chiqadi va pul (xizmat haqi '+j.fee+'% ayirib) balansingizga tushadi.</div><button class="btn s" onclick="auSave('+id+')">💾 Saqlash</button>'}
function auSave(id){api('auc_set',{id:id,on:$('auo'+id).checked?1:0,price:$('aupr'+id).value,fmt:$('auf'+id).value,descr:$('aud'+id).value}).then(function(j){if(j.ok){toast('Saqlandi ✅');auDraw(id,j)}})}
function rtl(){$('rtb').innerHTML='<div class="sk"></div>';api('rt_list').then(function(j){if(j.ok)rtr(j)})}
function rtr(j){var row=function(c,i,b){return '<div class="row" style="padding:10px 0;border-top:1px solid var(--ln)"><div style="min-width:0"><b>'+(b?'⭐ ':(i<3?['🥇','🥈','🥉'][i]:(i+1)+'.')+' ')+esc(c.username)+'</b><div class="sub">'+nf(c.members)+' obunachi'+(c.cat?' · '+esc(c.cat):'')+'</div></div>'+(c.grow!=null?'<b style="flex:none;color:var(--g)">+'+nf(c.grow)+(c.pct!=null?' <span class="sub">('+c.pct+'%)</span>':'')+'</b>':'')+'</div>'},h='<p class="sub" style="margin:-6px 2px 12px">Oxirgi 7 kunda eng tez o\'sgan kanallar. Har kuni yangilanadi.</p>';
if(j.boost.length)h+='<div class="card"><b>⭐ Tavsiya etiladi</b>'+j.boost.map(function(c){return row(c,0,1)}).join('')+'</div>';
h+='<div class="card"><b>🏆 Haftaning TOP-10</b>'+(j.top.length?j.top.map(function(c,i){return row(c,i,0)}).join(''):'<div class="sub" style="margin-top:6px">Reyting statistikadan hisoblanadi — bir necha kundan keyin paydo bo\'ladi.</div>')+'</div>';
if(j.my.length)h+='<div class="card"><b>🚀 Kanalimni ko\'tarish</b><div class="sub" style="margin:4px 0 8px">Kanalingiz 7 kun «⭐ Tavsiya etiladi» qatorida, eng tepada turadi'+(j.price?' — narxi '+fmt(j.price):' (tez orada)')+'.</div>'+j.my.map(function(c){return '<div class="row" style="padding:8px 0;border-top:1px solid var(--ln)"><b>'+esc(c.username)+'</b>'+(c.boost?'<span class="tag">⭐ '+dmy(c.boost)+' gacha</span>':'')+(j.price?'<button class="btn s" style="flex:none;width:auto" onclick="rtb('+c.id+','+j.price+')">🚀 '+(c.boost?'Uzaytirish':'Ko\'tarish')+'</button>':'')+'</div>'}).join('')+'</div>';$('rtb').innerHTML=h}
function rtb(id,p){cf(fmt(p)+' balansingizdan yechiladi. Kanal 7 kun tavsiya qatorida turadi.',function(y){if(y)api('rt_boost',{id:id}).then(function(j){if(j.ok){toast('🚀 Kanalingiz ko\'tarildi');rtr(j)}else if(j.need_topup)go('bal')})})}
var XT=null;
function xtr(){var j=XT,ST=j.mon.st,AL2={topup_approve:'✅ To\'lov tasdiqlandi',topup_reject:'❌ To\'lov rad etildi',ad_send:'📤 E\'lon yuborildi',ad_reject:'❌ E\'lon rad etildi',paycfg:'💳 Karta/narx o\'zgardi',promo_add:'🎟 Promo-kod',promo_del:'🗑 Promo-kod o\'chirildi',tfa:'🔐 2FA',tfa_ok:'🔐 Kod bilan kirdi',xt_set:'⚙️ Sozlamalar',boost:'🚀 Ko\'tarish',kechki_xabar:'🌙 Tungi xabar',tungi_xabar:'🌙 Tungi xabar',tungi_flag:'🌙 Tungi xabar yoqish/o\'chirish'},h='<h1>🧩 Qo\'shimcha</h1>';
h+='<div class="card"><div class="row"><b>🔐 Ikki bosqichli tasdiqlash</b><span style="cursor:pointer;flex:none" onclick="xtfa()">'+ck(j.tfa)+'</span></div><div class="sub">Yoqilsa, to\'lovni tasdiqlash, e\'lon yuborish, karta/narxni o\'zgartirish va ommaviy xabar uchun botga keladigan 6 xonali kod so\'raladi (30 daqiqada bir marta). Telefoningiz qo\'lga tushsa ham, ilova orqali pul amallarini qilib bo\'lmaydi.</div></div>';
h+='<div class="card"><div class="row"><b>🔕 Kechasi ovozsiz</b><span style="cursor:pointer;flex:none" onclick="XT.quiet.on=!XT.quiet.on;xtr()">'+ck(j.quiet.on)+'</span></div><div class="sub" style="margin-bottom:6px">Shu vaqtda kanal va guruhlarga bot xabarlari bildirishnomasiz (ovozsiz) ketadi — obunachilar uyg\'onmaydi.</div><div style="display:flex;gap:8px"><input id="xq_f" type="time" value="'+esc(j.quiet.from)+'" style="flex:1;min-width:0"><input id="xq_t" type="time" value="'+esc(j.quiet.to)+'" style="flex:1;min-width:0"></div><button class="btn s" onclick="xts({quiet_on:XT.quiet.on?1:0,quiet_from:$(\'xq_f\').value,quiet_to:$(\'xq_t\').value})">💾 Saqlash</button></div>';
h+='<div class="card"><div class="row"><b>🩺 Sayt monitoringi</b><span style="cursor:pointer;flex:none" onclick="XT.mon.on=!XT.mon.on;xtr()">'+ck(j.mon.on)+'</span></div><div class="sub" style="margin-bottom:6px">Har 5 daqiqada tekshiriladi. Sayt ishlamay qolsa yoki qayta ishlasa — sizga darhol xabar keladi.</div>'+Object.keys(ST).map(function(u){var x=ST[u];return '<div class="row sub" style="padding:4px 0"><span style="word-break:break-all">'+(x.ok?'🟢':'🔴')+' '+esc(u.replace(/^https?:\/\//,'').slice(0,40))+'</span><span style="flex:none">'+(x.ok?x.ms+' ms':'HTTP '+(x.code||'—'))+'</span></div>'}).join('')+'<textarea id="xm_u" rows="4" placeholder="Har qatorda bitta manzil">'+esc(j.mon.urls)+'</textarea><button class="btn s" onclick="xts({mon_on:XT.mon.on?1:0,mon_urls:$(\'xm_u\').value})">💾 Saqlash</button></div>';
h+='<div class="card"><b>💰 Komissiya va narxlar</b><p class="sub" style="margin:8px 0 2px">🔐 Pullik kanal — xizmat haqi (%)</p><input id="xf_pc" type="number" min="0" max="50" value="'+j.fees.pc_fee+'"><p class="sub" style="margin:0 0 2px">📣 Reklama birjasi — xizmat haqi (%)</p><input id="xf_au" type="number" min="0" max="50" value="'+j.fees.auc_fee+'"><p class="sub" style="margin:0 0 2px">🚀 Reytingda ko\'tarish — 7 kun narxi (0 — o\'chiq)</p><input id="xf_bp" type="number" min="0" value="'+j.fees.boost_price+'"><p class="sub" style="margin:0 0 2px">🏷 Kanal Savdo — vositachilik haqi (%)</p><input id="xf_sf" type="number" min="0" max="50" value="'+j.fees.sale_fee+'"><p class="sub" style="margin:0 0 2px">💝 Qo\'llab-quvvatlash — xizmat haqi (%)</p><input id="xf_dn" type="number" min="0" max="50" value="'+j.fees.don_fee+'"><button class="btn s" onclick="xts({pc_fee:$(\'xf_pc\').value,auc_fee:$(\'xf_au\').value,boost_price:$(\'xf_bp\').value,sale_fee:$(\'xf_sf\').value,don_fee:$(\'xf_dn\').value})">💾 Saqlash</button></div>';
h+='<div class="card"><div class="row"><b>📣 Kun kanali</b><span style="cursor:pointer;flex:none" onclick="XT.kk.on=!XT.kk.on;xtr2()">'+ck(j.kk.on)+'</span></div><div class="sub" style="margin-bottom:6px">Har kuni tasodifiy qatnashuvchi kanal boshqa qatnashuvchilarda tavsiya etiladi (24 soatda o\'chadi). Qatnashuvchilar: '+j.kk.n+' ta.</div><input id="xk_t" type="time" value="'+esc(j.kk.time)+'"><button class="btn s" onclick="xts({kk_gon:XT.kk.on?1:0,kk_time:$(\'xk_t\').value})">💾 Saqlash</button></div>';
h+='<div class="card"><b>🧑‍🤝‍🧑 Kanal egalari klubi</b><div class="sub" style="margin:4px 0 6px">Yopiq guruh ID si yoki @username. Bot u yerda «Taklif havolasi» huquqi bilan admin bo\'lsin — har bir kanal egasiga shaxsiy bir martalik havola beriladi. Bo\'sh qoldirilsa — klub ko\'rinmaydi.</div><input id="xc_c" placeholder="-1001234567890" value="'+esc(j.club)+'"><button class="btn s" onclick="xts({club_chat:$(\'xc_c\').value})">💾 Saqlash</button></div>';
h+='<div class="card"><b>🎓 Video qo\'llanmalar</b><div class="sub" style="margin:4px 0 6px">Videoni baza kanalga joylang va havolasini kiriting — o\'sha bo\'limda «❓ Qanday ishlaydi» tugmasi paydo bo\'ladi.</div><select id="xh_p">'+Object.keys(HLN).map(function(k){return '<option value="'+k+'">'+HLN[k]+(j.help[k]?' ✅':'')+'</option>'}).join('')+'</select><input id="xh_l" placeholder="https://t.me/c/1234567890/45 (bo\'sh — o\'chirish)"><button class="btn s" onclick="xts({help_page:$(\'xh_p\').value,help_link:$(\'xh_l\').value.trim()});HLV=null">💾 Saqlash</button>'+Object.keys(j.help).map(function(k){return '<div class="sub" style="padding:4px 0">✅ '+esc(HLN[k]||k)+' — '+esc(j.help[k])+'</div>'}).join('')+'</div>';
var SC={ads:'E\'lonlar',auc:'Reklama birjasi',boost:'Ko\'tarish',all:'Hammasi'};
h+='<div class="card"><b>🎟 Promo-kodlar</b><div style="display:flex;gap:8px;margin-top:8px"><input id="xp_c" maxlength="30" placeholder="KOD" style="flex:1.4;min-width:0;text-transform:uppercase"><input id="xp_p" type="number" min="1" max="90" placeholder="%" style="flex:.6;min-width:0"></div><div style="display:flex;gap:8px"><input id="xp_u" type="number" min="0" placeholder="Limit (0 — cheksiz)" style="flex:1;min-width:0"><input id="xp_d" type="number" min="0" placeholder="Kun (0 — muddatsiz)" style="flex:1;min-width:0"></div><select id="xp_s">'+Object.keys(SC).map(function(k){return '<option value="'+k+'">'+SC[k]+'</option>'}).join('')+'</select><button class="btn s" onclick="xpa()">➕ Yaratish</button>'+j.promo.map(function(p){return '<div class="row" style="padding:6px 0;border-top:1px solid var(--ln)"><div><b>'+esc(p.code)+'</b> · -'+p.pct+'%<div class="sub">'+SC[p.scope]+' · '+p.used+(+p.max_uses?'/'+p.max_uses:'')+' marta'+(+p.until?' · '+dmy(p.until)+' gacha':'')+'</div></div><button class="btn s" style="flex:none;width:auto" onclick="xpd(\''+esc(p.code)+'\')">🗑</button></div>'}).join('')+'</div>';
h+='<div class="card"><b>🔑 Admin harakatlari tarixi</b>'+(j.audit.length?j.audit.map(function(a){return '<div style="padding:6px 0;border-top:1px solid var(--ln)"><div class="row sub"><span>'+esc(a.name||'Admin')+(a.username?' @'+esc(a.username):'')+'</span><span>'+esc(dtf(a.at))+'</span></div><div style="font-size:14px">'+esc(AL2[a.action]||a.action)+(a.detail?' <span class="sub">'+esc(String(a.detail).slice(0,80))+'</span>':'')+'</div></div>'}).join(''):'<div class="sub">Hali yozuv yo\'q.</div>')+'</div>';return h}
function xtr2(){av('xt')}
function xts(o){api('adm_xt_set',o).then(function(j){if(j.ok){XT=j;toast('Saqlandi ✅');av('xt')}})}
function xtfa(){api('adm_tfa',{on:XT.tfa?0:1}).then(function(j){if(j.ok){XT=j;toast(j.tfa?'🔐 2FA yoqildi':'2FA o\'chirildi');av('xt')}})}
function xpa(){api('adm_pk_add',{code:$('xp_c').value.trim(),pct:$('xp_p').value,uses:$('xp_u').value,days:$('xp_d').value,scope:$('xp_s').value}).then(function(j){if(j.ok){XT=j;toast('Yaratildi ✅');av('xt')}})}
function xpd(c){cf('Promo-kod o\'chirilsinmi?',function(y){if(y)api('adm_pk_del',{code:c}).then(function(j){if(j.ok){XT=j;av('xt')}})})}
function stcsv(id){toast('Tayyorlanmoqda...');api('stat_csv',{id:id}).then(function(j){if(j.ok)toast('📤 Fayl botga yuborildi ✅')})}
function pobt(){var c=$('po_c').value;api('best_time',{chat:c==='all'?0:c}).then(function(j){if(j.ok){$('po_t').value=j.run_at;toast('🧠 '+('0'+j.hour).slice(-2)+':00 — '+j.src)}})}
function clubl(){var e=$('clubb');if(!e)return;api('club').then(function(j){e.innerHTML=j.ok&&j.on&&j.can?'<div class="card"><div class="row"><div><b>🧑‍🤝‍🧑 Kanal egalari klubi</b><div class="sub">Yopiq guruh: tajriba almashish, birgalikda reklama aksiyalari</div></div><button class="btn s" style="flex:none;width:auto" onclick="api(\'club_join\').then(function(k){if(k.ok)toast(\'👉 Taklif havolasi botga yuborildi\')})">Qo\'shilish</button></div></div>':''})}
var SAD=null;
/* ---------- NAKRUTKA ---------- */
var NK={j:null,plat:'',cat:'',sid:0,price:0,busy:0,tm:0,rq:0,link:'',qty:'',A:null,fp:'tg',fr:null,cart:[],rep:1,times:4,open:0,disc:0};
var NKP={tg:'✈️ Telegram',ig:'📸 Instagram',yt:'▶️ YouTube',tt:'🎵 TikTok',fb:'👍 Facebook',x:'𝕏 Twitter',th:'🧵 Threads',vk:'🔷 VK',sp:'🎧 Spotify',tw:'🎮 Twitch'};
var NKS={'new':['⏳','Yuborilmoqda','#8e8e93'],wait:['🔄','Bajarilmoqda','#1d84f2'],done:['✅','Bajarildi','#1a9e4f'],part:['⚠️','Qisman bajarildi','#c77a00'],cancel:['↩️','Bekor qilindi · pul qaytdi','#d92d20'],fail:['↩️','Rad etildi · pul qaytdi','#d92d20'],unk:['🔍','Tekshirilmoqda','#8e8e93']};
function nkn(n){return String(Math.round(+n||0)).replace(/\B(?=(\d{3})+(?!\d))/g,' ')}
function nkch(t,cur,clr){var h='<div class="cps">';[70,80,90,100].forEach(function(v){h+='<button class="chip'+(cur!==''&&cur!==null&&+cur===v?' on':'')+'" data-t="'+t+'" data-v="'+v+'" onclick="nkmv(\''+t+'\','+v+')">'+v+'%</button>'});if(clr)h+='<button class="chip'+(cur===''||cur===null?' on':'')+'" data-t="'+t+'" data-v="" onclick="nkmv(\''+t+'\',\'\')">Umumiy</button>';return h+'</div>'}
function nkmv(t,v){var e=$(t);if(!e)return;e.value=v;document.querySelectorAll('[data-t="'+t+'"]').forEach(function(b){b.classList.toggle('on',String(b.getAttribute('data-v'))===String(v))})}
function nkcf(m,f){try{tg.showConfirm(m,function(ok){if(ok)f()})}catch(e){if(confirm(m))f()}}
function nksv(){var j=NK.j;if(!j)return null;for(var i=0;i<j.svcs.length;i++)if(j.svcs[i].id===NK.sid)return j.svcs[i];return null}
function nkl(){$('nkb').innerHTML='<div class="sk"></div>';api('nk_list').then(function(j){if(!j.ok){$('nkb').innerHTML='';return}NK.j=j;if(!NK.plat||j.plats.indexOf(NK.plat)<0)NK.plat=j.plats[0]||'';if(!nksv())NK.sid=0;nkr();if($('nka'))nka()})}
function nkr(){var j=NK.j;if(!j)return;var h=(j.notice?'<div class="card" style="background:#fff4e5;border:1px solid #f5c98b"><b>⚠️ '+esc(j.notice)+'</b></div>':'')+'<div class="card"><div class="row" style="margin:0"><div><div class="sub">Balans</div><b style="font-size:22px">'+fmt(j.balance)+'</b>'+lvl(j)+'</div><button class="btn s" onclick="go(\'bal\')">➕ To\'ldirish</button></div></div>';
if(!j.on||!j.svcs.length)h+='<div class="card"><b>Xizmat hozircha mavjud emas</b><div class="sub" style="margin-top:4px">'+'Birozdan keyin qayta urinib ko\'ring.'+'</div></div>';
else h+='<div class="card"><b>Platforma</b><div class="cps">'+j.plats.map(function(p){return '<button class="chip'+(NK.plat===p?' on':'')+'" onclick="nkp(\''+p+'\')">'+NKP[p]+'</button>'}).join('')+'</div></div>'+nkcb()+'<div id="nkls"></div><div id="nkf"></div>';
h+='<div id="nkc"></div><div id="nko"></div>';$('nkb').innerHTML=h;nkv();nkf();nkc();nkh()}
var NKC={sub:'👥 Obuna',like:'❤️ Layk',cmt:'💬 Izoh',view:'👁 Ko\'rish',oth:'✨ Boshqa'};
function nkcat(t){t=String(t||'').toLowerCase().replace(/[\u02bb\u02bc\u2019\u2018`\u00b4]/g,"'");if(/comment|izoh|коммент|отзыв/.test(t))return 'cmt';if(/subscr|follower|member|obuna|a'?zo|подпис|друз|fans|join/.test(t))return 'sub';if(/like|layk|laik|reaction|reaksiya|heart|лайк|реакц|vote/.test(t))return 'like';if(/view|ko'?rish|watch|story|stories|reel|impression|просмотр|stream|play|listen/.test(t))return 'view';return 'oth'}
function nkcs(){var m={};NK.j.svcs.forEach(function(s){if(s.plat===NK.plat){var c=nkcat(s.title);m[c]=(m[c]||0)+1}});return m}
function nkpc(c){NK.cat=c;NK.sid=0;NK.price=0;nkr()}
function nkp(p){NK.plat=p;NK.cat='';NK.sid=0;NK.price=0;nkr()}
function nkcb(){if(!NK.plat)return '';var m=nkcs(),ks=Object.keys(NKC).filter(function(k){return m[k]});if(ks.length<2){NK.cat='';return ''}if(!NK.cat||!m[NK.cat])NK.cat=ks[0];return '<div class="card"><b>Xizmat turi</b><div class="cps">'+ks.map(function(k){return '<button class="chip'+(NK.cat===k?' on':'')+'" onclick="nkpc(\''+k+'\')">'+NKC[k]+' · '+m[k]+'</button>'}).join('')+'</div></div>'}
function nkv(){var el=$('nkls');if(!el)return;var h='';NK.j.svcs.forEach(function(s){if(s.plat!==NK.plat)return;if(NK.cat&&nkcat(s.title)!==NK.cat)return;var on=s.id===NK.sid;h+='<div class="card" onclick="nks('+s.id+')" style="cursor:pointer;'+(on?'border:2px solid #1d84f2;background:var(--soft)':'')+'"><div class="row" style="margin:0"><div><b>'+esc(s.title)+'</b>'+(s.hot?'<span style="margin-left:6px;font-size:11px;font-weight:700;color:#d92d20;background:#fee4e2;border-radius:8px;padding:2px 7px">🔥 Eng ko\'p olinadi</span>':'')+'<div class="sub">'+nkn(s.min)+' – '+nkn(s.max)+' ta'+(s.rt?' · ⭐ '+s.rt.avg+' ('+s.rt.n+')':'')+(s.sold?' · '+nkn(s.sold)+' ta buyurtma':'')+'</div></div><div style="text-align:right"><b style="color:#1d84f2">'+fmt(s.p1000)+'</b><div class="sub">1000 ta uchun</div></div></div></div>'});el.innerHTML=h}
function nks(id){NK.sid=id;NK.price=0;nkv();nkf();var e=$('nkf');if(e&&e.scrollIntoView)e.scrollIntoView({behavior:'smooth',block:'center'})}
function nkrn(d){return d===1?'har kuni':d===7?'har hafta':d===30?'har oy':'har '+d+' kunda'}
function nkrp(n){NK.rep=n;nkf()}
function nkf(){var el=$('nkf');if(!el)return;var s=nksv();if(!s){el.innerHTML='';return}
var ph={tg:'https://t.me/kanalim yoki @kanalim',ig:'https://instagram.com/akkaunt yoki @akkaunt',yt:'YouTube video yoki kanal havolasi'}[s.plat]||(NKP[s.plat]||'')+' havolasi';
var vol=(NK.j.vol||[]).length?'<div class="sub" style="margin:0 0 8px;color:#1a9e4f">🎁 Hajm chegirmasi: '+NK.j.vol.map(function(t){return nkn(t[0])+' ta va undan ko\'p −'+t[1]+'%'}).join(' · ')+'</div>':'';
el.innerHTML='<div class="card"><b>'+esc(s.title)+'</b><div class="sub" style="margin:2px 0 8px">Miqdor: '+nkn(s.min)+' – '+nkn(s.max)+'</div>'+vol+fbbtn('nk',s)+'<input id="nklk" placeholder="'+esc(ph)+'" autocomplete="off" autocapitalize="off" value="'+esc(NK.link)+'" oninput="NK.link=this.value"><input id="nkq" type="number" inputmode="numeric" placeholder="Miqdor" value="'+esc(NK.qty)+'" oninput="nkqi(this.value)"><div id="nkpr" class="sub" style="margin:2px 0 10px"></div>'
+'<div class="sub" style="margin:0 0 4px">Takrorlash</div><div class="cps">'+[[1,'Bir marta'],[3,'Har 3 kun'],[7,'Har hafta'],[30,'Har oy']].map(function(r){return '<button class="chip'+(NK.rep===r[0]?' on':'')+'" onclick="nkrp('+r[0]+')">'+r[1]+'</button>'}).join('')+'</div>'
+(NK.rep>1?'<input id="nkt" type="number" inputmode="numeric" value="'+esc(NK.times)+'" placeholder="Necha marta (2–12)" oninput="NK.times=this.value">':'')
+'<button id="nkbtn" class="btn" onclick="nko()">'+(NK.rep>1?'🔁 Takroriy buyurtmani boshlash':'🚀 Buyurtma berish')+'</button>'+(NK.rep===1?'<button class="btn s" style="margin-top:8px" onclick="nkca()">🛒 Savatga qo\'shish</button>':'')
+'<p class="sub" style="font-size:12px;margin:8px 0 0">Havola ochiq bo\'lishi kerak (yopiq kanal/akkaunt qabul qilinmaydi). Natija kafolatlanmaydi: platforma qoidalariga ko\'ra obunachilar vaqt o\'tishi bilan kamayishi mumkin. Buyurtma boshlangach bekor qilib bo\'lmaydi; bajarilmagan qismi uchun pul avtomatik qaytariladi.</p></div>';nkpr();if(NK.qty)nkqi(NK.qty)}
function nkpr(){var el=$('nkpr'),s=nksv();if(!el||!s)return;var q=parseInt(NK.qty,10)||0;if(!q){el.textContent='Kerakli miqdorni kiriting';return}if(q<s.min||q>s.max){el.textContent='Miqdor '+nkn(s.min)+' dan '+nkn(s.max)+' gacha bo\'lsin';return}el.innerHTML=NK.price?'Narxi: <b>'+fmt(NK.price)+'</b>'+(NK.disc>0?' <span style="color:#1a9e4f">(−'+NK.disc+'% hajm chegirmasi)</span>':''):'Narx hisoblanmoqda...'}
function nkqi(v){NK.qty=v;NK.price=0;NK.disc=0;nkpr();clearTimeout(NK.tm);var s=nksv(),q=parseInt(v,10)||0;if(!s||q<s.min||q>s.max)return;var rq=++NK.rq;NK.tm=setTimeout(function(){api('nk_quote',{sid:s.id,qty:q}).then(function(j){if(rq!==NK.rq)return;if(j.ok){NK.price=j.price;NK.disc=j.disc||0;nkpr()}})},350)}
function nko(){if(NK.busy)return;var s=nksv();if(!s)return;var q=parseInt(NK.qty,10)||0,lk=(NK.link||'').trim();
if(!lk){toast('Havolani kiriting');return}if(q<s.min||q>s.max){toast('Miqdor '+nkn(s.min)+' dan '+nkn(s.max)+' gacha bo\'lsin');return}if(!NK.price){toast('Narx hisoblanmoqda, bir soniya kuting');return}
var rep=NK.rep>1,tm=parseInt(NK.times,10)||0;if(rep&&(tm<2||tm>12)){toast('Takrorlash soni 2 dan 12 gacha bo\'lsin');return}
var pr=NK.price;nkcf(s.title+'\n'+nkn(q)+' ta · '+fmt(pr)+(rep?'\n🔁 '+nkrn(NK.rep)+', jami '+tm+' marta (har safar '+fmt(pr)+')':'')+'\n\nBuyurtma berilsinmi?',function(){if(NK.busy)return;NK.busy=1;var b=$('nkbtn');if(b){b.disabled=true;b.textContent='Yuborilmoqda...'}
api(rep?'nk_sub_new':'nk_order',rep?{sid:s.id,link:lk,qty:q,every:NK.rep,times:tm}:{sid:s.id,link:lk,qty:q}).then(function(j){NK.busy=0;if(j.ok){toast(rep?'🔁 Takroriy buyurtma boshlandi':(j.check?'Buyurtma qabul qilindi, holati tekshirilmoqda':'✅ Buyurtma qabul qilindi'));NK.link='';NK.qty='';NK.sid=0;NK.price=0;NK.rep=1;nkl()}else{var b2=$('nkbtn');if(b2){b2.disabled=false;b2.textContent=rep?'🔁 Takroriy buyurtmani boshlash':'🚀 Buyurtma berish'}if(j.need_topup)setTimeout(function(){go('bal')},900)}})})}
function nkca(){var s=nksv();if(!s)return;var q=parseInt(NK.qty,10)||0,lk=(NK.link||'').trim();if(!lk){toast('Havolani kiriting');return}if(q<s.min||q>s.max){toast('Miqdor '+nkn(s.min)+' dan '+nkn(s.max)+' gacha bo\'lsin');return}if(!NK.price){toast('Narx hisoblanmoqda, bir soniya kuting');return}
if(NK.cart.length>=5){toast('Savatda 5 tadan ko\'p bo\'lmasin');return}if(NK.cart.some(function(c){return c.sid===s.id&&c.link===lk})){toast('Bu allaqachon savatda');return}
NK.cart.push({sid:s.id,title:s.title,qty:q,link:lk,price:NK.price});toast('🛒 Savatga qo\'shildi ('+NK.cart.length+')');NK.link='';NK.qty='';NK.price=0;nkf();nkc()}
function nkc(){var el=$('nkc');if(!el)return;if(!NK.cart.length){el.innerHTML='';return}var t=0;NK.cart.forEach(function(c){t+=c.price});
el.innerHTML='<div class="card" style="border:2px solid #1d84f2"><b>🛒 Savat ('+NK.cart.length+')</b>'+NK.cart.map(function(c,i){return '<div class="row" style="border-top:1px solid var(--ln);padding:8px 0;margin:0"><div><b style="font-size:14px">'+esc(c.title)+'</b><div class="sub" style="font-size:12px;word-break:break-all">'+nkn(c.qty)+' ta · '+esc(c.link)+'</div></div><div style="text-align:right"><b>'+fmt(c.price)+'</b><br><button class="btn s" style="width:auto;padding:2px 10px;margin-top:4px" onclick="nkcx('+i+')">✖</button></div></div>'}).join('')+'<div class="row" style="margin:8px 0 0"><b>Jami</b><b>'+fmt(t)+'</b></div><button id="nkcb" class="btn" style="margin-top:8px" onclick="nkcbuy()">🛒 Hammasini buyurtma qilish</button></div>'}
function nkcx(i){NK.cart.splice(i,1);nkc()}
function nkcbuy(){if(NK.busy)return;var t=0;NK.cart.forEach(function(c){t+=c.price});nkcf('Savatdagi '+NK.cart.length+' ta buyurtma ('+fmt(t)+') berilsinmi?',function(){if(NK.busy)return;NK.busy=1;var b=$('nkcb');if(b){b.disabled=true;b.textContent='Yuborilmoqda...'}
api('nk_cart',{items:NK.cart.map(function(c){return {sid:c.sid,qty:c.qty,link:c.link}})}).then(function(j){NK.busy=0;if(j.placed>0){var bad=(j.failed||[]).map(function(f){return f.i});NK.cart=NK.cart.filter(function(c,i){return bad.indexOf(i)>=0});toast(bad.length?'Berildi: '+j.placed+', berilmadi: '+bad.length:'✅ Hammasi qabul qilindi');nkl()}else{var b2=$('nkcb');if(b2){b2.disabled=false;b2.textContent='🛒 Hammasini buyurtma qilish'}if(j.need_topup)setTimeout(function(){go('bal')},900)}})})}
function nkto(id){NK.open=NK.open===id?0:id;nkh()}
function nksub(a,id){api(a,{id:id}).then(function(j){if(j.ok){toast('Saqlandi');nkl()}})}
function nkre(id){var o=NK.j.orders.filter(function(x){return x.id===id})[0];if(!o)return;var s=NK.j.svcs.filter(function(x){return x.id===o.sid})[0];if(!s){toast('Bu xizmat hozir mavjud emas');return}
NK.plat=s.plat;NK.sid=s.id;NK.link=o.link;NK.qty=String(o.qty);NK.price=0;NK.rep=1;nkr();nkqi(NK.qty);var e=$('nkf');if(e&&e.scrollIntoView)e.scrollIntoView({behavior:'smooth',block:'center'})}
function nktl(r){var f=r.st,fin=f==='done'||f==='part'||f==='cancel'||f==='fail',g='#1a9e4f',b='#1d84f2',x='#c4c9d4',rd='#d92d20',am='#c77a00',dot=function(c,t,s){return '<div style="display:flex;gap:10px;margin:6px 0"><span style="width:10px;height:10px;border-radius:50%;background:'+c+';margin-top:5px;flex:none"></span><div style="font-size:13px"><b>'+t+'</b>'+(s?'<div class="sub" style="font-size:12px">'+s+'</div>':'')+'</div></div>'};
var h=dot(g,'Qabul qilindi',esc(r.created));h+=r.sent?dot(g,'Provayderga yuborildi',''):(f==='new'||f==='unk'?dot(b,'Yuborilmoqda / tekshirilmoqda',''):dot(x,'Provayderga yuborilmadi',''));
if(f==='wait'){var p=r.remains!=null&&r.qty>0?Math.round((r.qty-r.remains)*100/r.qty):null;h+=dot(b,'Bajarilmoqda',p!==null?p+'% bajarildi':'Boshlanishi kutilmoqda')+dot(x,'Natija',r.eta?'Taxminan '+r.eta+' daqiqada':'')}
else if(fin){h+=dot(g,'Jarayon tugadi','')+(f==='done'?dot(g,'Bajarildi',esc(r.upd)):f==='part'?dot(am,'Qisman bajarildi',esc(r.upd)+(r.refunded>0?' · '+fmt(r.refunded)+' qaytdi':'')):dot(rd,'Bekor qilindi',esc(r.upd)+(r.refunded>0?' · '+fmt(r.refunded)+' qaytdi':'')))}
return '<div style="margin-top:10px;border-top:1px solid var(--ln);padding-top:6px">'+h+'<button class="btn s" style="margin-top:6px" onclick="event.stopPropagation();nkre('+r.id+')">🔁 Qayta buyurtma</button></div>'}
function nkh(){var el=$('nko');if(!el)return;var j=NK.j,o=j.orders,h='';
if((j.subs||[]).length)h+='<h3 style="margin:14px 2px 8px">🔁 Takroriy buyurtmalarim</h3>'+j.subs.map(function(s){var m={on:['🟢','Faol'],pause:['⏸','To\'xtatilgan'],done:['✅','Tugadi']}[s.st]||['',''];return '<div class="card"><div class="row" style="margin:0"><b>'+esc(s.title||'Xizmat')+'</b><span style="font-size:13px;font-weight:700;white-space:nowrap">'+m[0]+' '+m[1]+'</span></div><div class="sub" style="word-break:break-all">'+esc(s.link)+'</div><div class="sub">'+nkn(s.qty)+' ta · '+nkrn(s.every)+(s.left>0?' · yana '+s.left+' marta':'')+(s.st==='on'?' · keyingisi: '+esc(s.next):'')+'</div>'+((s.st==='on'||s.st==='pause')?'<div style="display:flex;gap:8px;margin-top:8px">'+(s.st==='pause'?'<button class="btn s" style="flex:1" onclick="nksub(\'nk_sub_on\','+s.id+')">▶️ Davom ettirish</button>':'')+'<button class="btn s" style="flex:1" onclick="nksub(\'nk_sub_stop\','+s.id+')">⛔ To\'xtatish</button></div>':'')+'</div>'}).join('');
if(o.length){var ur=o.filter(function(r){return (r.st==='done'||r.st==='part')&&!r.rated})[0];if(ur)h+='<div class="card" onclick="nkto('+ur.id+')" style="cursor:pointer;border:2px solid #f5c542"><b>⭐ Buyurtma #'+ur.id+' qanday bo\'ldi?</b><div class="sub">Bosing va baholang — fikringiz boshqalarga yordam beradi.</div></div>';h+='<h3 style="margin:14px 2px 8px">Buyurtmalarim</h3>';o.forEach(function(r){var st=NKS[r.st]||NKS.wait,pr='';if(r.st==='wait'&&r.remains!=null&&r.qty>0){var d=Math.max(0,Math.min(100,Math.round((r.qty-r.remains)*100/r.qty)));pr='<div style="height:6px;border-radius:3px;background:#e5e8ef;margin-top:8px;overflow:hidden"><i style="display:block;height:100%;width:'+d+'%;background:#1d84f2"></i></div>'}
var q=(r.st==='wait'&&r.ahead!=null)?'<div class="sub" style="margin-top:6px">👥 Sizdan oldin '+r.ahead+' ta buyurtma jarayonda'+(r.eta?' · taxminan '+r.eta+' daqiqa':'')+'</div>':'';
h+='<div class="card" onclick="nkto('+r.id+')" style="cursor:pointer"><div class="row" style="margin:0"><b>#'+r.id+' · '+esc(r.title)+'</b><span style="color:'+st[2]+';font-weight:700;font-size:13px;white-space:nowrap">'+st[0]+' '+st[1]+'</span></div><div class="sub" style="margin-top:3px;word-break:break-all">'+esc(r.link)+'</div><div class="sub">'+nkn(r.qty)+' ta · '+fmt(r.price)+' · '+esc(r.created)+(r.refunded>0?' · qaytdi: '+fmt(r.refunded):'')+'</div>'+pr+q+(NK.open===r.id?nktl(r)+((r.st==='done'||r.st==='part')?fbui('nk',r.id,r.rated):''):'')+'</div>'});}
el.innerHTML=h}
/* --- admin --- */
function nkauto(){nkcf('Provayder katalogidan xizmatlar avtomatik qo\'shilsinmi? Narx avto hisoblanadi.',function(){api('nk_adm_auto',{per:3}).then(function(j){if(j.ok){toast('Qo\'shildi: '+j.added+' ta ('+j.groups+' guruh)');nka();nkl()}})})}
function nka(){api('nk_adm_get',{}).then(function(j){if(!j.ok)return;NK.A=j;nkar()})}
function nkar(){var j=NK.A,el=$('nka');if(!el||!j)return;var h='<div class="card" style="border:1px dashed #1d84f2"><b>⚙️ Admin: Nakrutka sozlamalari</b><div class="sub" style="margin:4px 0 8px">Provayder: prm4u.com (API v2). Narx = provayder narxi × dollar kursi × (1 + ustama).</div>'
+'<input id="nku" value="'+esc(j.url)+'" placeholder="API manzil"'+(j.url_const?' disabled':'')+'><input id="nkk" type="password" autocomplete="off" placeholder="'+(j.key_set?'API kalit saqlangan (••••'+esc(j.key_tail)+') — o\'zgartirish uchun yangisini kiriting':'API kalit (prm4u.com → Account → API)')+'"'+(j.key_const?' disabled':'')+'>'
+'<input id="nkus" type="number" inputmode="decimal" value="'+(j.usd||'')+'" placeholder="Dollar kursi (bo\'sh = avtomatik: '+(j.usd_eff?fmt(j.usd_eff):'topilmadi')+')"><input id="nkm" type="number" inputmode="decimal" value="'+j.mk+'" placeholder="Ustama, % (masalan 40)">'+nkch('nkm',j.mk,0)+'<input id="nkd" type="number" inputmode="numeric" value="'+j.day+'" placeholder="Bir foydalanuvchiga kunlik buyurtma chegarasi">'
+'<div class="cps"><button class="chip'+(j.on?' on':'')+'" id="nkon" onclick="nkton()">'+(j.on?'✅ Xizmat yoqilgan':'⛔ Xizmat o\'chirilgan')+'</button></div>'
+'<div style="display:flex;gap:8px"><button class="btn" onclick="nkas()">💾 Saqlash</button><button class="btn s" style="width:auto;flex:none" onclick="nkat()">🔌 Tekshirish</button></div><div id="nkar" class="sub" style="margin-top:8px"></div></div>';
h+='<div class="card" style="border:1px dashed #1d84f2"><b>🧩 Xizmatlar ('+j.svcs.length+')</b><div class="sub" style="margin:4px 0 6px">Provayder katalogidan avtomatik: har platforma va tur (Obuna, Layk, Izoh, Ko\'rish) uchun eng arzon 3 tadan xizmat qo\'shiladi. Mavjudlari o\'zgarmaydi.</div><button class="btn" onclick="nkauto()">⚡ Avtomatik qo\'shish</button>';
if(!j.svcs.length)h+='<div class="sub" style="margin:6px 0">Hali xizmat qo\'shilmagan. Pastdan qidirib qo\'shing.</div>';
j.svcs.forEach(function(s){h+='<div style="border-top:1px solid var(--ln);margin-top:10px;padding-top:8px"><div class="sub">'+NKP[s.plat]+' · ID '+s.pid+' · $'+s.rate+'/1000 · '+nkn(s.min_q)+'–'+nkn(s.max_q)+' · narx '+fmt(s.p1000)+'</div><input id="nkst'+s.id+'" value="'+esc(s.title)+'" maxlength="100"><input id="nksm'+s.id+'" type="number" inputmode="decimal" value="'+(s.mk===null?'':s.mk)+'" placeholder="Ustama % (bo\'sh = umumiy)">'+nkch('nksm'+s.id,s.mk,1)+'<div style="display:flex;gap:8px"><button class="btn s" style="flex:1" onclick="nksave('+s.id+',0)">💾</button><button class="btn s" style="flex:1" onclick="nksave('+s.id+',1)">'+(s.act==1?'⛔ O\'chirish':'✅ Yoqish')+'</button><button class="btn s" style="flex:1" onclick="nkdel('+s.id+')">🗑</button></div></div>'});
h+='<div style="border-top:1px solid var(--ln);margin-top:12px;padding-top:10px"><b>➕ Provayderdan xizmat qo\'shish</b><div class="cps">'+Object.keys(NKP).map(function(p){return '<button class="chip'+(NK.fp===p?' on':'')+'" onclick="NK.fp=\''+p+'\';nkar()">'+NKP[p]+'</button>'}).join('')+'</div><input id="nkfq" placeholder="Qidiruv: masalan «telegram members»" onkeydown="if(event.key===\'Enter\')nkaf()"><button class="btn s" onclick="nkaf()">🔎 Qidirish</button><div id="nkfr" style="margin-top:8px"></div></div></div>';
var bad=j.orders.filter(function(r){return r.st==='unk'||r.st==='new'});
h+='<div class="card" style="border:1px dashed #1d84f2"><b>📋 Buyurtmalar (oxirgi '+j.orders.length+')</b>'+(bad.length?'<div class="sub" style="color:#d92d20;margin:4px 0">⚠️ '+bad.length+' ta buyurtma holati noma\'lum — pul ushlab turilgan. Provayder panelida tekshirib, «Qaytarish» yoki «Yuborilgan» ni bosing.</div>':'');
j.orders.forEach(function(r){var st=NKS[r.st]||NKS.wait;h+='<div style="border-top:1px solid var(--ln);margin-top:8px;padding-top:8px"><div class="row" style="margin:0"><b>#'+r.id+' · '+esc(r.title)+'</b><span style="color:'+st[2]+';font-weight:700;font-size:12.5px">'+st[0]+' '+st[1]+'</span></div><div class="sub" style="word-break:break-all">'+esc(r.link)+'</div><div class="sub">'+esc(r.name||'')+(r.username?' @'+esc(r.username):'')+' · ID '+r.uid+' · '+nkn(r.qty)+' ta · '+fmt(r.price)+(r.cost?' · provayder $'+r.cost:'')+(r.porder?' · P#'+r.porder:'')+'</div>'+(r.err?'<div class="sub" style="color:#d92d20">'+esc(r.err)+'</div>':'');
if(r.st==='unk'||r.st==='new')h+='<div style="display:flex;gap:8px;margin-top:6px"><button class="btn s" style="flex:1" onclick="nkfx('+r.id+',\'refund\')">↩️ Qaytarish</button><input id="nkpo'+r.id+'" type="number" inputmode="numeric" placeholder="Provayder #" style="flex:1;margin:0"><button class="btn s" style="flex:1" onclick="nkfx('+r.id+',\'sent\')">✔ Yuborilgan</button></div>';h+='</div>'});
h+='</div>';el.innerHTML=h}
function nkton(){NK.A.on=!NK.A.on;var b=$('nkon');b.className='chip'+(NK.A.on?' on':'');b.textContent=NK.A.on?'✅ Xizmat yoqilgan':'⛔ Xizmat o\'chirilgan'}
function nkas(){var k=$('nkk').value.trim();api('nk_adm_set',{url:$('nku').value.trim(),key:k,usd:$('nkus').value,mk:$('nkm').value,day:$('nkd').value,on:NK.A.on?1:0}).then(function(j){if(j.ok){toast('Saqlandi');nkl()}})}
function nkat(){var r=$('nkar');r.textContent='Tekshirilmoqda...';api('nk_adm_test',{}).then(function(j){r.innerHTML=j.ok?'✅ Ulandi. Provayderdagi balans: <b>'+esc(j.balance)+' '+esc(j.currency)+'</b>':'❌ '+esc(j.error||'Ulanib bo\'lmadi')})}
function nkaf(){var q=$('nkfq').value.trim(),r=$('nkfr');if(q.length<2){toast('Kamida 2 ta harf kiriting');return}r.innerHTML='<div class="sk"></div>';api('nk_adm_find',{q:q}).then(function(j){if(!j.ok){r.innerHTML='';return}NK.fr=j.list;if(!j.list.length){r.innerHTML='<div class="sub">Hech narsa topilmadi</div>';return}r.innerHTML=j.list.map(function(s,i){return '<div style="border-top:1px solid var(--ln);padding:8px 0"><b style="font-size:14px">'+esc(s.name)+'</b><div class="sub">ID '+s.pid+' · '+esc(s.cat)+' · $'+s.rate+'/1000 · '+nkn(s.min)+'–'+nkn(s.max)+'</div><button class="btn s" onclick="nkaa('+i+')"'+(s.have?' disabled':'')+'>'+(s.have?'✓ Qo\'shilgan':'➕ '+NKP[NK.fp]+' ga qo\'shish')+'</button></div>'}).join('')})}
function nkaa(i){var s=NK.fr&&NK.fr[i];if(!s)return;api('nk_adm_add',{pid:s.pid,plat:NK.fp,title:s.name}).then(function(j){if(j.ok){toast('Qo\'shildi — nom va ustamani yuqorida tahrirlang');nkl()}})}
function nksave(id,tg2){var s=null;NK.A.svcs.forEach(function(x){if(x.id===id)s=x});if(!s)return;var act=tg2?(s.act==1?0:1):s.act;api('nk_adm_svc',{id:id,title:$('nkst'+id).value,mk:$('nksm'+id).value,act:act,sort:s.sort}).then(function(j){if(j.ok){toast('Saqlandi');nkl()}})}
function nkdel(id){nkcf('Xizmat ro\'yxatdan o\'chirilsinmi? (Eski buyurtmalar saqlanadi)',function(){api('nk_adm_svc',{id:id,del:1}).then(function(j){if(j.ok){toast('O\'chirildi');nkl()}})})}
function nkfx(id,d){var po=d==='sent'?($('nkpo'+id).value||''):'';nkcf(d==='refund'?'Buyurtma #'+id+' uchun pul foydalanuvchiga qaytarilsinmi?':'Buyurtma #'+id+' provayderga yuborilgan deb belgilansinmi?',function(){api('nk_adm_fix',{id:id,do:d,porder:po}).then(function(j){if(j.ok){toast('Bajarildi');nkl()}})})}

/* --- provayder balanslari (faqat admin panelda) --- */
var PV={d:null,sm:null};
var PVI={'5sim':['c1','<svg viewBox="0 0 24 24"><path d="M5 4h14a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H9l-4 4v-4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2z"/><path d="M8 10h.01M12 10h.01M16 10h.01"/></svg>'],prm4u:['c9','<svg viewBox="0 0 24 24"><path d="M4.5 16.5c-1.5 1.3-2 5-2 5s3.7-.5 5-2c.7-.8.7-2.1-.1-2.9-.8-.8-2.1-.8-2.9-.1z"/><path d="M12 15l-3-3a22 22 0 0 1 2-3.9A12.9 12.9 0 0 1 22 2c0 2.7-.8 7.5-6 11a22.4 22.4 0 0 1-4 2z"/><path d="M9 12H4s.6-3 2-4c1.6-1.1 5 0 5 0"/><path d="M12 15v5s3-.6 4-2c1.1-1.6 0-5 0-5"/></svg>']};
(function(){var st=document.createElement('style');st.textContent='.pvh{font-size:13px;color:var(--sub);font-weight:600;text-transform:uppercase;margin:6px 4px 8px}.pvs{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:0 0 12px}.pvs button{display:flex;align-items:center;gap:10px;background:var(--cd);border:0;border-radius:16px;padding:8px 12px 8px 8px;text-align:left;box-shadow:var(--sh);position:relative;font:inherit;cursor:pointer}.pvs .tq-i{width:38px;height:38px;flex:none;margin:0;border-radius:12px}.pvs .tq-i svg{width:20px;height:20px}.pvs small{display:block;font-size:11.5px;color:var(--sub);line-height:1.1}.pvs b{display:block;font-size:17px;font-weight:800;letter-spacing:-.3px;color:var(--tx);line-height:1.25}.pvs i{position:absolute;top:10px;right:11px;width:8px;height:8px;border-radius:4px}.pvs .g{background:#22b35e;box-shadow:0 0 0 3px #e3f8ea}.pvs .r{background:#ef4444;box-shadow:0 0 0 3px #fee4e2}.pvc{font-size:12px;font-weight:700;border-radius:9px;padding:3px 9px;white-space:nowrap}';document.head.appendChild(st)})();
function pvtiles(){var h='';(PV.d||[{id:'prm4u',name:'prm4u',ok:null},{id:'5sim',name:'5sim',ok:null}]).forEach(function(p){var ic=PVI[p.id]||PVI.prm4u,dot=p.ok===null?'':(p.ok&&!p.low?'g':'r');h+='<button onclick="av(\'pv\')"><span class="tq-i '+ic[0]+'">'+ic[1]+'</span><span><small>'+esc(p.name)+'</small><b>'+(p.ok===null?'…':(p.ok?(p.cur==='RUB'?(+p.bal).toFixed(2)+'₽':'$'+(+p.bal).toFixed(2)):'—'))+'</b></span>'+(dot?'<i class="'+dot+'"></i>':'')+'</button>'});return h}
function pvl(force){api('nk_adm_bal',{force:force?1:0}).then(function(j){if(!j.ok)return;PV.d=j.providers;PV.sm=j.sm;var e=$('pvs');if(e)e.innerHTML=pvtiles();pvr()})}
function pvchip(p){if(!p.conf)return '<span class="pvc" style="color:#7d8799;background:#eef1f6">Sozlanmagan</span>';if(!p.ok)return '<span class="pvc" style="color:#d92d20;background:#fee4e2">❌ Ulanmadi</span>';return p.low?'<span class="pvc" style="color:#d92d20;background:#fee4e2">⚠️ Kam</span>':'<span class="pvc" style="color:#1a9e4f;background:#e3f8ea">✓ Ulangan</span>'}
function pvr(){var el=$('pvb');if(!el||!PV.d)return;var h='';
PV.d.forEach(function(p){if(p.low)h+='<div class="card" style="background:#fee4e2;border:1px solid #fecdca"><b style="color:#b42318">⚠️ '+esc(p.name)+' balansi kam</b><div class="sub" style="color:#b42318">$'+(+p.bal).toFixed(2)+' — chegara $'+p.limit+' '+p.cur+' dan past. Buyurtmalar to\'xtab qolishi mumkin. Provayderdagi hisobni to\'ldiring.</div></div>';if(p.conf&&!p.ok)h+='<div class="card" style="background:#fee4e2;border:1px solid #fecdca"><b style="color:#b42318">❌ '+esc(p.name)+': ulanib bo\'lmadi</b><div class="sub" style="color:#b42318">'+esc(p.err||'')+'</div></div>'});
PV.d.forEach(function(p){var ic=PVI[p.id]||PVI.prm4u;h+='<div class="card"><div class="row" style="margin:0 0 10px"><div style="display:flex;align-items:center;gap:12px"><span class="tq-i '+ic[0]+'" style="width:44px;height:44px;margin:0">'+ic[1]+'</span><div><b style="font-size:17px">'+esc(p.name)+'</b><div class="sub">'+esc(p.desc)+'</div></div></div>'+pvchip(p)+'</div>'
+'<div style="font-size:32px;font-weight:800;letter-spacing:-1px">'+(p.ok?(p.cur==='RUB'?'':'$')+(+p.bal).toFixed(2)+' '+esc(p.cur):'—')+'</div><div class="sub" style="margin-bottom:12px">'+(p.uzs!=null?'≈ '+fmt(p.uzs)+' · ':'')+'yangilandi '+esc(p.at)+'</div>'
+(p.ok&&p.days!=null?'<div class="sub" style="margin:-4px 0 12px">📊 So\'nggi 7 kunda sarf: $'+p.spent7+' · taxminan <b>'+p.days+' kunga</b> yetadi</div>':'')
+(p.id==='5sim'?pvsm(p):'')+'<div class="sub" style="margin-bottom:4px">Ogohlantirish chegarasi ('+esc(p.cur)+') — balans shundan pasaysa, Telegramga xabar keladi</div><input id="pvlm_'+p.id+'" type="number" inputmode="decimal" value="'+p.limit+'"><div style="display:flex;gap:8px"><button class="btn s" style="flex:1" onclick="pvl(1);toast(\'Yangilanmoqda...\')">🔄 Yangilash</button><button class="btn s" style="flex:1" onclick="pvsave(\''+p.id+'\')">💾 Saqlash</button><button class="btn s" style="flex:1" onclick="pvsite(\''+p.site+'\')">🌐 Sayt</button></div></div>'});
el.innerHTML=h}
function pvsave(id){api('nk_adm_limit',{id:id,limit:$('pvlm_'+id).value}).then(function(j){if(j.ok){toast('Saqlandi');pvl(0)}})}
function pvsite(u){try{tg.openLink(u)}catch(e){window.open(u,'_blank')}}
var _avN=av;av=function(v){_avN(v);if(v==='home'||v==='pv')pvl(0);if(v==='sec')secl();if(v==='bct')bctl();if(v==='bnx')bnl();if(v==='ads')adsl();if(v==='nkx')nka();if(v==='vsx')vsa();if(v==='evx')evla();if(v==='wax')wala();if(v==='wsx')wsl();if(v==='rep')repl();if(v==='tod')todl()};

function pvsm(p){var s=PV.sm||{};return '<div class="sub" style="margin-bottom:4px">API kalit ('+(s.key_set?'saqlangan ••••'+esc(s.key_tail):'kiritilmagan')+') — 5sim → Settings → «API key for 5SIM protocol»</div><input id="smk" type="password" autocomplete="off" placeholder="'+(s.key_set?'Yangi kalit (o\'zgartirish uchun)':'API kalitni shu yerga qo\'ying')+'"'+(s.key_const?' disabled':'')+'><div class="sub" style="margin-bottom:4px">Balans valyutasi (5sim API qaysi valyutada qaytarsa shuni tanlang — saytdagi bilan solishtiring)</div><div class="cps"><button class="chip'+(s.cur==='RUB'?' on':'')+'" id="smc_RUB" onclick="smcur(\'RUB\')">₽ RUB</button><button class="chip'+(s.cur==='USD'?' on':'')+'" id="smc_USD" onclick="smcur(\'USD\')">$ USD</button></div><input id="smr" type="number" inputmode="decimal" value="'+(s.rub||'')+'" placeholder="1 rubl necha so\'m (faqat RUB uchun, ixtiyoriy)"><button class="btn" onclick="smsave()">💾 Kalit va valyutani saqlash</button>'}
function smcur(c){PV.sm.cur=c;['RUB','USD'].forEach(function(x){var b=$('smc_'+x);if(b)b.classList.toggle('on',x===c)})}
function smsave(){var s=PV.sm||{};api('nk_adm_sm',{key:($('smk')||{}).value||'',cur:s.cur||'RUB',rub:($('smr')||{}).value||0}).then(function(j){if(j.ok){toast('Saqlandi');pvl(1)}})}

/* ---------- VIRTUAL RAQAM ---------- */
var VS={j:null,pr:'',cc:'',A:null,tm:0,tk:0,fr:null,busy:0};
var VSP={telegram:'✈️ Telegram',whatsapp:'🟢 WhatsApp',instagram:'📸 Instagram',facebook:'🔵 Facebook',google:'🔴 Google',tiktok:'🎵 TikTok',twitter:'🐦 X (Twitter)',viber:'🟣 Viber'};
var VSS={wait:['⏳','SMS kutilmoqda','#1d84f2'],got:['✅','Kod keldi','#1a9e4f'],cancel:['↩️','Bekor · pul qaytdi','#d92d20'],fail:['↩️','Rad etildi · pul qaytdi','#d92d20'],unk:['🔍','Tekshirilmoqda','#8e8e93'],'new':['⏳','Yuborilmoqda','#8e8e93']};
function vsn(p){return VSP[p]||('📱 '+String(p).charAt(0).toUpperCase()+String(p).slice(1))}
function vscp(t){try{navigator.clipboard.writeText(t).then(function(){toast('Nusxalandi')},function(){vscp2(t)})}catch(e){vscp2(t)}}
function vscp2(t){var a=document.createElement('textarea');a.value=t;a.style.position='fixed';a.style.opacity='0';document.body.appendChild(a);a.select();try{document.execCommand('copy');toast('Nusxalandi')}catch(e){toast(t)}document.body.removeChild(a)}
function vsl(quiet){if(!quiet)$('vsb').innerHTML='<div class="sk"></div>';api('vs_list').then(function(j){if(!j.ok){if(!quiet)$('vsb').innerHTML='';return}VS.j=j;var ps=[];j.offers.forEach(function(o){if(ps.indexOf(o.product)<0)ps.push(o.product)});if(!VS.pr||ps.indexOf(VS.pr)<0)VS.pr=ps[0]||'';if($('p-vs').classList.contains('on'))vsr();if($('vsa'))vsa();vspoll()})}
function vspoll(){clearTimeout(VS.tm);var w=VS.j&&VS.j.orders.some(function(o){return o.st==='wait'});if(!w){clearInterval(VS.tk);return}VS.tm=setTimeout(function(){if($('p-vs').classList.contains('on'))vsl(1)},5000);clearInterval(VS.tk);VS.tk=setInterval(function(){if(!$('p-vs').classList.contains('on')){clearInterval(VS.tk);return}document.querySelectorAll('[data-vsl]').forEach(function(e){var l=Math.max(0,+e.getAttribute('data-vsl')-1);e.setAttribute('data-vsl',l);e.textContent=vsmm(l)})},1000)}
function vsmm(s){s=Math.max(0,s|0);return (s/60|0)+':'+('0'+s%60).slice(-2)}
function vscn(o){return String(o.title||'').replace(/^[\u{1F1E6}-\u{1F1FF}]{2}\s*/u,'').split(/\s+[·\-—(]/)[0].trim()||o.country}
function vsfl(o){var t=String(o.title||'');return /^[\u{1F1E6}-\u{1F1FF}]/u.test(t)?t:(o.flag||'🌍')+' '+t}
function vsr(){var j=VS.j;if(!j)return;var h=(j.notice?'<div class="card" style="background:#fff4e5;border:1px solid #f5c98b"><b>⚠️ '+esc(j.notice)+'</b></div>':'')+'<div class="card"><div class="row" style="margin:0"><div><div class="sub">Balans</div><b style="font-size:22px">'+fmt(j.balance)+'</b>'+lvl(j)+'</div><button class="btn s" onclick="go(\'bal\')">➕ To\'ldirish</button></div></div>';
if(!j.on)h+='<div class="card"><b>Xizmat hozircha mavjud emas</b><div class="sub" style="margin-top:4px">'+'Birozdan keyin qayta urinib ko\'ring.'+'</div></div>';
else if(!j.offers.length)h+='<div class="card"><b>Hozircha raqamlar yo\'q</b><div class="sub" style="margin-top:4px">Tez orada qo\'shiladi.</div></div>';
else{var cs=vscs(),pop=j.pop||{};
if(!cs.some(function(c){return c.c===VS.cc}))VS.cc=cs[0].c;
var ps=[];j.offers.forEach(function(o){if(o.country===VS.cc&&ps.indexOf(o.product)<0)ps.push(o.product)});ps.sort(function(a,b){return (pop[b]||0)-(pop[a]||0)});if(ps.indexOf(VS.pr)<0)VS.pr=ps[0];
h+='<div class="card"><b>Davlat</b>'+(cs.length>12?'<input id="vsq" placeholder="🔎 Davlat qidirish" autocomplete="off" value="'+esc(VS.q||'')+'" oninput="VS.q=this.value;vscl()" style="margin-top:8px">':'')+'<div class="cps" id="vscc" style="max-height:230px;overflow:auto">'+vsch(cs)+'</div></div><div class="card"><b>Ijtimoiy tarmoq</b><div class="cps">'+ps.map(function(p,i){return '<button class="chip'+(VS.pr===p?' on':'')+'" onclick="VS.pr=\''+p+'\';vsr()">'+(i<3&&(pop[p]||0)>0?'🔥 ':'')+esc(vsn(p))+'</button>'}).join('')+'</div></div><div id="vsl"></div>';
h+='<p class="sub" style="font-size:12px;margin:2px 4px 10px">Raqam olingach, uni tarmoqqa kiriting — kod shu yerda avtomatik chiqadi. Kod kelmasa (taxminan 15 daqiqa) pul balansga avtomatik qaytadi. Kod kelgach pul qaytmaydi. Platforma raqamni qabul qilishi kafolatlanmaydi. ⭐ — oxirgi 30 kunda kod kelish foizi va o\'rtacha vaqt.</p>'}
h+='<div id="vso"></div>';$('vsb').innerHTML=h;vsrl();vso()}
function vscs(){var cm={},cs=[];VS.j.offers.forEach(function(o){if(!cm[o.country]){cm[o.country]={c:o.country,n:vscn(o),f:o.flag||'🌍'};cs.push(cm[o.country])}});cs.sort(function(a,b){return a.n.localeCompare(b.n)});return cs}
function vsch(cs){var q=String(VS.q||'').trim().toLowerCase();var L=cs.filter(function(c){return !q||c.n.toLowerCase().indexOf(q)>=0||c.c===VS.cc});return L.map(function(c){return '<button class="chip'+(VS.cc===c.c?' on':'')+'" onclick="VS.cc=\''+c.c+'\';VS.pr=\'\';VS.q=\'\';vsr()">'+esc(c.f+' '+c.n)+'</button>'}).join('')}
function vscl(){var e=$('vscc');if(e)e.innerHTML=vsch(vscs())}
function vsrl(){var el=$('vsl');if(!el)return;var L=VS.j.offers.filter(function(o){return o.country===VS.cc&&o.product===VS.pr});
L.sort(function(a,b){var an=a.stock===0?1:0,bn=b.stock===0?1:0;if(an!==bn)return an-bn;var aq=a.q?a.q.pct:-1,bq=b.q?b.q.pct:-1;if(aq!==bq)return bq-aq;return a.price-b.price});
el.innerHTML=L.length?L.map(function(o){var no=o.stock===0,rr=o.rt?'<span>⭐ '+o.rt.avg+' ('+o.rt.n+')</span>':'',qq=o.q?'<span style="color:'+(o.q.pct>=80?'#1a9e4f':o.q.pct>=50?'#c77a00':'#d92d20')+'">⭐ '+o.q.pct+'%'+(o.q.sec?' · ~'+(o.q.sec<90?o.q.sec+' s':Math.round(o.q.sec/60)+' daq'):'')+'</span>':'';return '<div class="card"><div class="row" style="margin:0"><div><b>'+esc(vsfl(o))+'</b>'+(o.hot?'<span style="margin-left:6px;font-size:11px;font-weight:700;color:#d92d20;background:#fee4e2;border-radius:8px;padding:2px 7px">🔥 Eng ko\'p olinadi</span>':'')+'<div class="sub">'+(no?'<span style="color:#d92d20">Hozircha tugagan</span>':'SMS-kod uchun bir martalik raqam')+(qq?' · '+qq:'')+(rr?' · '+rr:'')+' · <a onclick="fbl(\'vs\','+o.id+')" style="color:#1d84f2;cursor:pointer">💬</a></div><div id="fbr_vs'+o.id+'"></div></div><div style="text-align:right"><b style="color:#1d84f2">'+fmt(o.price)+'</b><br><button class="btn s" style="width:auto;margin-top:6px;padding:6px 16px"'+(no?' disabled':'')+' onclick="vsb('+o.id+')">Olish</button></div></div></div>'}).join(''):'<div class="card"><div class="sub">Hech narsa topilmadi.</div></div>'}
function vso(){var el=$('vso');if(!el)return;var o=VS.j.orders;if(!o.length){el.innerHTML='';return}var h='<h3 style="margin:14px 2px 8px">Buyurtmalarim</h3>';
o.forEach(function(r){var st=VSS[r.st]||VSS.wait,body='';
if(r.st==='wait')body='<div class="sub" style="margin-top:8px">Raqam (bosib nusxalang):</div><div style="display:flex;align-items:center;gap:10px;margin:2px 0 6px"><b style="font-size:34px;letter-spacing:1px;cursor:pointer;word-break:break-all" onclick="vscp(\''+esc(r.phone)+'\')">'+esc(r.phone)+'</b></div><button class="btn" style="margin:0 0 6px" onclick="vscp(\''+esc(r.phone)+'\')">📋 Raqamni nusxalash</button><div class="sub">⏳ Kod kutilmoqda... qolgan vaqt <b data-vsl="'+r.left+'">'+vsmm(r.left)+'</b></div><div style="display:flex;gap:8px;margin-top:10px"><button class="btn s" style="flex:1" onclick="vsx('+r.id+')">✖ Bekor qilish</button><button class="btn s" style="flex:1"'+(r.age>=90?'':' disabled')+' onclick="vssw('+r.id+')">🔄 Boshqa raqam</button></div>'+(r.age>=90?'':'<div class="sub" style="font-size:12px;margin-top:4px">«Boshqa raqam» 1.5 daqiqadan keyin ochiladi</div>');
else if(r.st==='got')body='<div class="sub" style="margin-top:6px">Raqam:</div><b style="font-size:26px;letter-spacing:1px;cursor:pointer" onclick="vscp(\''+esc(r.phone)+'\')">'+esc(r.phone)+' 📋</b><div class="sub" style="margin-top:8px">Kod (bosib nusxalang):</div><div style="display:flex;align-items:center;gap:10px;margin:2px 0 6px"><b style="font-size:44px;letter-spacing:4px;color:#1a9e4f;cursor:pointer" onclick="vscp(\''+esc(r.code)+'\')">'+esc(r.code)+'</b></div><button class="btn" style="margin:0 0 6px" onclick="vscp(\''+esc(r.code)+'\')">📋 Kodni nusxalash</button>'+(r.reuse?'<button class="btn s" style="margin-top:6px" onclick="vsru('+r.id+','+r.price+')">🔁 Shu raqamga yana kod olish · '+fmt(r.price)+'</button>':'')+fbui('vs',r.id,r.rated);
else if(r.st==='unk'||r.st==='new')body='<div class="sub" style="margin-top:6px">Holati tekshirilmoqda. Muammo bo\'lsa pul avtomatik qaytariladi yoki admin hal qiladi.</div>';
h+='<div class="card"><div class="row" style="margin:0"><b>#'+r.id+' · '+esc(r.title)+'</b><span style="color:'+st[2]+';font-weight:700;font-size:13px;white-space:nowrap">'+st[0]+' '+st[1]+'</span></div>'+body+'<div class="sub" style="margin-top:6px">'+fmt(r.price)+' · '+esc(r.created)+(r.refunded>0?' · qaytdi: '+fmt(r.refunded):'')+'</div></div>'});el.innerHTML=h}
function vssw(id){nkcf('Raqam almashtirilsinmi? Eski raqam bekor qilinadi (pul qaytadi), shu taklifdan yangisi olinadi.',function(){api('vs_swap',{id:id}).then(function(j){if(j.ok){toast(j.check?'Qabul qilindi, holati tekshirilmoqda':'🔄 Yangi raqam olindi')}vsl(1)})})}
function vsru(id,p){nkcf('Shu raqamga yana bir SMS-kod olinadi: '+fmt(p)+' yechiladi, kod kelmasa qaytadi. Davom etasizmi?',function(){api('vs_reuse',{id:id}).then(function(j){if(j.ok){toast('✅ Kodni kuting')}else if(j.need_topup)setTimeout(function(){go('bal')},900);vsl(1)})})}
function vsb(id){if(VS.busy)return;var o=null;VS.j.offers.forEach(function(x){if(x.id===id)o=x});if(!o)return;nkcf(o.title+'\n'+fmt(o.price)+'\n\nRaqam olinsinmi? Pul balansdan yechiladi, kod kelmasa qaytadi.',function(){if(VS.busy)return;VS.busy=1;api('vs_buy',{oid:id}).then(function(j){VS.busy=0;if(j.ok){toast(j.check?'Qabul qilindi, holati tekshirilmoqda':'✅ Raqam olindi — kodni kuting');vsl(1);setTimeout(function(){var e=$('vso');if(e&&e.scrollIntoView)e.scrollIntoView({behavior:'smooth',block:'start'})},400)}else if(j.need_topup)setTimeout(function(){go('bal')},900)})})}
function vsx(id){nkcf('Raqam bekor qilinsinmi? SMS kelmagan bo\'lsa pul qaytadi.',function(){api('vs_cancel',{id:id}).then(function(j){if(j.ok){toast('↩️ Bekor qilindi, '+fmt(j.refund)+' qaytdi')}vsl(1)})})}
/* --- admin --- */
function vsa(){api('vs_adm_get',{}).then(function(j){if(!j.ok)return;VS.A=j;vsar()})}
function vsar(){var j=VS.A,el=$('vsa');if(!el||!j)return;var h='<div class="card" style="border:1px dashed #1d84f2"><b>⚙️ Admin: eSIM</b><div class="sub" style="margin:4px 0 8px">5sim kaliti va valyuta: Profil → 💰 Provayder balanslari. Narxni siz so\'mda belgilaysiz; tannarx 5sim dan olinadi.'+(j.rate>0?'':' <b style="color:#d92d20">Foyda hisobi uchun 1 '+j.cur+' kursini kiriting (Provayder balanslari → 5sim).</b>')+'</div>'
+'<div class="sub"><b>Umumiy ustama, %</b> — narxi bo\'sh (avto) takliflarga: narx = tannarx × (1 + ustama)</div><input id="vsk" type="number" inputmode="decimal" value="'+j.mk+'">'+nkch('vsk',j.mk,0)+'<div class="sub">Eng kam foyda, % (tannarxdan; pastga tushsa raqam yashiriladi)</div><input id="vsm" type="number" value="'+j.minm+'"><div class="sub">SMS kutish vaqti, daqiqa (5–20)</div><input id="vst" type="number" value="'+j.ttl+'"><div class="sub">Bir foydalanuvchida bir vaqtda kutilayotgan raqamlar</div><input id="vsc" type="number" value="'+j.act+'"><div class="sub">Bir foydalanuvchiga kunlik buyurtma chegarasi</div><input id="vsd" type="number" value="'+j.day+'">'
+'<div class="cps"><button class="chip'+(j.on?' on':'')+'" id="vson" onclick="VS.A.on=!VS.A.on;this.className=\'chip\'+(VS.A.on?\' on\':\'\');this.textContent=VS.A.on?\'✅ Xizmat yoqilgan\':\'⛔ Xizmat o\\\'chirilgan\'">'+(j.on?'✅ Xizmat yoqilgan':'⛔ Xizmat o\'chirilgan')+'</button></div><button class="btn" onclick="vsas()">💾 Saqlash</button>'
+'<div class="sub" style="margin-top:8px">So\'nggi 30 kun: sotildi <b>'+j.sold.n+'</b> ta · tushum <b>'+fmt(j.sold.sum)+'</b>'+(j.sold.cost!=null?' · tannarx '+fmt(j.sold.cost)+' · foyda <b>'+fmt(j.sold.sum-j.sold.cost)+'</b>':'')+'</div></div>';
var vpn=j.offers.filter(function(o){return o.pcost!==null}).length;
h+='<div class="card" style="border:1px dashed #1d84f2"><b>⚡ Avtomatik rejim</b><div class="sub" style="margin:4px 0 8px">Takliflar va narxlar 5sim dan o\'zi yuklanadi. Siz faqat yuqoridagi <b>ustama %</b> ni belgilaysiz. Hozir: takliflar <b>'+j.offers.length+'</b>, narxi bor <b>'+vpn+'</b>.'+(j.offers.length&&!vpn?' <b style="color:#d92d20">Narx kelmadi'+(j.key_set?'':' — 5sim kaliti kiritilmagan (Profil → Provayder balanslari)')+'.</b>'+(j.perr?'<div class="sub" style="color:#d92d20;margin-top:4px">'+esc(j.perr)+'</div>':''):'')+'</div><button class="btn" onclick="vsauto()">🔄 Hozir yangilash</button><button class="btn s" style="margin-top:8px" onclick="VS.adv=!VS.adv;vsar()">'+(VS.adv?'▲ Qo\'lda boshqarishni yashirish':'🛠 Qo\'lda boshqarish (ixtiyoriy)')+'</button></div>';
if(!VS.adv){el.innerHTML=h+vsord(j);return}
h+='<div class="card" style="border:1px dashed #1d84f2"><b>🔎 5sim narxini ko\'rish</b><div class="sub" style="margin:4px 0 6px">Davlat va tarmoq nomi inglizcha, kichik harfda (usa, canada, indonesia, russia · telegram, whatsapp, instagram)</div><input id="vfc" placeholder="Davlat: indonesia" autocapitalize="off"><input id="vfp" placeholder="Tarmoq: telegram" autocapitalize="off"><button class="btn s" onclick="vsaf()">🔎 Narxlarni ko\'rish</button><div id="vfr" style="margin-top:8px"></div></div>';
h+='<div class="card" style="border:1px dashed #1d84f2"><b>🧩 Takliflar ('+j.offers.length+')</b>'+(j.offers.length?'':'<div class="sub" style="margin:6px 0">Hali qo\'shilmagan. Yuqorida narxni ko\'ring, so\'ng qo\'shing.</div>')+(j.offers.length>20?'<input id="vsf" placeholder="🔎 Davlat yoki tarmoq (Enter)" autocapitalize="off" value="'+esc(VS.of||'')+'" onchange="VS.of=this.value;VS.on=20;vsar()">':'');
var vfq=String(VS.of||'').trim().toLowerCase(),vfl=j.offers.filter(function(o){return !vfq||(o.product+' '+o.country+' '+o.title).toLowerCase().indexOf(vfq)>=0}),vfn=VS.on||20;
if(vfl.length>vfn)h+='<div class="sub" style="margin:6px 0">Ko\'rsatilgan: '+vfn+' / '+vfl.length+'</div>';
vfl.slice(0,vfn).forEach(function(o){h+='<div style="border-top:1px solid var(--ln);margin-top:10px;padding-top:8px"><div class="sub">'+esc(o.product)+' · '+esc(o.country)+' · operator: '+esc(o.operator)+' · qoldiq: '+nkn(o.pcount)+(o.pcost!==null?' · tannarx '+o.pcost+' '+j.cur+(o.cost_uzs!=null?' (≈ '+fmt(o.cost_uzs)+')':''):'')+'</div>'+(o.auto?'<div class="sub" style="color:#1d84f2">⚙️ AVTO narx: '+(o.eff!=null?fmt(o.eff)+' (ustama '+j.mk+'%)':'hisoblanmadi — qoldiq yoki kurs yo\'q')+'</div>':'')+(o.profit!=null?'<div class="sub" style="color:'+(o.hidden?'#d92d20':'#1a9e4f')+'">Foyda: '+fmt(o.profit)+(o.hidden?' — foyda chegarasidan past, YASHIRILGAN':'')+'</div>':'')+'<input id="vot'+o.id+'" value="'+esc(o.title)+'" maxlength="100"><input id="vop'+o.id+'" type="number" inputmode="numeric" value="'+(o.auto?'':o.price)+'" placeholder="Narx, so\'m (bo\'sh = avto)"><div style="display:flex;gap:8px"><button class="btn s" style="flex:1" onclick="vsos('+o.id+',0)">💾</button><button class="btn s" style="flex:1" onclick="vsos('+o.id+',1)">'+(o.act?'⛔ O\'chirish':'✅ Yoqish')+'</button><button class="btn s" style="flex:1" onclick="vsod('+o.id+')">🗑</button></div></div>'});
if(vfl.length>vfn)h+='<button class="btn s" style="margin-top:10px" onclick="VS.on='+(vfn+30)+';vsar()">Yana ko\'rsatish</button>';
h+=vsbulk();
h+='<div style="border-top:1px solid var(--ln);margin-top:12px;padding-top:10px"><b>➕ Taklif qo\'shish</b><input id="vac" placeholder="Davlat: indonesia" autocapitalize="off"><input id="vap" placeholder="Tarmoq: telegram" autocapitalize="off"><input id="vao" placeholder="Operator (bo\'sh = any, eng arzon)" autocapitalize="off"><input id="vat" placeholder="Nomi: 🇮🇩 Indoneziya" maxlength="100"><input id="vaq" type="number" inputmode="numeric" placeholder="Narx, so\'m (BO\'SH = avto-ustama)"><button class="btn" onclick="vsaa()">➕ Qo\'shish</button></div></div>';
el.innerHTML=h+vsord(j)}
function vsord(j){var h='',bad=j.orders.filter(function(r){return r.st==='unk'||r.st==='new'});
h+='<div class="card" style="border:1px dashed #1d84f2"><b>📋 Buyurtmalar (oxirgi '+j.orders.length+')</b>'+(bad.length?'<div class="sub" style="color:#d92d20;margin:4px 0">⚠️ '+bad.length+' ta buyurtma holati noma\'lum — pul ushlab turilgan. 5sim panelida (Purchases) tekshiring.</div>':'');
j.orders.forEach(function(r){var st=VSS[r.st]||VSS.wait;h+='<div style="border-top:1px solid var(--ln);margin-top:8px;padding-top:8px"><div class="row" style="margin:0"><b>#'+r.id+' · '+esc(r.title)+'</b><span style="color:'+st[2]+';font-weight:700;font-size:12.5px">'+st[0]+' '+st[1]+'</span></div><div class="sub">'+esc(r.name||'')+(r.username?' @'+esc(r.username):'')+' · ID '+r.uid+' · '+fmt(r.price)+(r.phone?' · '+esc(r.phone):'')+(r.porder?' · P#'+r.porder:'')+(r.code?' · kod '+esc(r.code):'')+'</div>'+(r.err?'<div class="sub" style="color:#d92d20">'+esc(r.err)+'</div>':'');
if(r.st==='unk'||r.st==='new')h+='<div style="display:flex;gap:8px;margin-top:6px;flex-wrap:wrap"><button class="btn s" style="flex:1 1 100%" onclick="vsfx('+r.id+',\'refund\')">↩️ Qaytarish</button><input id="vpo'+r.id+'" type="number" inputmode="numeric" placeholder="5sim ID" style="flex:1;margin:0"><input id="vph'+r.id+'" placeholder="+62..." style="flex:1;margin:0"><button class="btn s" style="flex:1 1 100%" onclick="vsfx('+r.id+',\'sent\')">✔ Yuborilgan (5sim da bor)</button></div>';h+='</div>'});
return h+'</div>'}
function vsas(){api('vs_adm_set',{mk:$('vsk').value,minm:$('vsm').value,ttl:$('vst').value,act:$('vsc').value,day:$('vsd').value,on:VS.A.on?1:0}).then(function(j){if(j.ok){toast('Saqlandi');vsl(1)}})}
function vsaf(){var r=$('vfr');r.innerHTML='<div class="sk"></div>';api('vs_adm_find',{country:$('vfc').value,product:$('vfp').value}).then(function(j){if(!j.ok){r.innerHTML='';return}VS.fr=j;r.innerHTML=j.list.map(function(s){return '<div style="border-top:1px solid var(--ln);padding:6px 0"><b>'+esc(s.op)+'</b> · '+s.cost+' '+VS.A.cur+(s.uzs!=null?' (≈ '+fmt(s.uzs)+')':'')+' · qoldiq '+nkn(s.count)+'</div>'}).join('')+'<button class="btn s" style="margin-top:8px" onclick="vsaprefill()">➕ Shu davlat/tarmoq bilan taklif qo\'shish</button>'})}
function vsaprefill(){var f=VS.fr;if(!f)return;$('vac').value=f.country;$('vap').value=f.product;var e=$('vat');if(e.scrollIntoView)e.scrollIntoView({behavior:'smooth',block:'center'});e.focus()}
function vsaa(){api('vs_adm_add',{country:$('vac').value,product:$('vap').value,operator:$('vao').value,title:$('vat').value,price:$('vaq').value}).then(function(j){if(j.ok){toast('Qo\'shildi');vsl(1)}})}
function vsos(id,tg2){var o=null;VS.A.offers.forEach(function(x){if(x.id===id)o=x});if(!o)return;api('vs_adm_off',{id:id,title:$('vot'+id).value,price:$('vop'+id).value,act:tg2?(o.act?0:1):o.act,sort:o.sort}).then(function(j){if(j.ok){toast('Saqlandi');vsl(1)}})}
function vsod(id){nkcf('Taklif o\'chirilsinmi? (Eski buyurtmalar saqlanadi)',function(){api('vs_adm_off',{id:id,del:1}).then(function(j){if(j.ok){toast('O\'chirildi');vsl(1)}})})}
function vsfx(id,d){nkcf(d==='refund'?'Buyurtma #'+id+' uchun pul foydalanuvchiga qaytarilsinmi?':'Buyurtma 5sim ga yuborilgan deb belgilansinmi?',function(){api('vs_adm_fix',{id:id,do:d,porder:($('vpo'+id)||{}).value||'',phone:($('vph'+id)||{}).value||''}).then(function(j){if(j.ok){toast('Bajarildi');vsl(1)}})})}

/* ---------- XAVFSIZLIK VA HOLAT (admin) ---------- */
var SEC={j:null};
function secl(){api('sec_adm_get',{}).then(function(j){if(!j.ok)return;SEC.j=j;secr()})}
function secr(){var j=SEC.j,el=$('secb');if(!el||!j)return;var h='';
['nk','vs'].forEach(function(k){var s=j.sv[k],st=s.off?'<span style="color:#d92d20;font-weight:700">⛔ Qo\'lda o\'chirilgan</span>':(s.down>0?'<span style="color:#c77a00;font-weight:700">⚠️ Avto-to\'xtatilgan ('+s.down+' daq.)</span>':'<span style="color:#1a9e4f;font-weight:700">✅ Ishlayapti</span>');
h+='<div class="card"><div class="row" style="margin:0 0 6px"><b>'+esc(s.name)+'</b>'+st+'</div><div class="sub" style="margin-bottom:4px">Mijozga ko\'rinadigan xabar (xizmat yopilganda):</div><input id="svm_'+k+'" maxlength="200" value="'+esc(s.msg)+'" placeholder="Masalan: Texnik ishlar, 1 soatda tiklanadi"><div style="display:flex;gap:8px"><button class="btn s" style="flex:1" onclick="secsv(\''+k+'\','+(s.off?0:1)+')">'+(s.off?'✅ Yoqish':'⛔ O\'chirish')+'</button>'+(s.down>0||s.fails>0?'<button class="btn s" style="flex:1" onclick="secsv(\''+k+'\','+(s.off?1:0)+',1)">🔄 Avto-holatni tiklash</button>':'')+'</div><div class="sub" style="margin-top:6px;font-size:12px">Provayder ketma-ket 3 marta xato bersa, xizmat 10 daqiqaga o\'zi to\'xtaydi (pul yechilmaydi) va sizga xabar keladi.</div></div>'});
var b=j.bk;
h+='<div class="card"><b>🗄 Zaxira nusxa</b><div class="sub" style="margin:4px 0 8px">'+(b.at?'Oxirgi: '+esc(b.at)+' · '+esc(b.info):'Hali nusxa olinmagan')+'</div>'
+'<div class="cps"><button class="chip'+(b.on?' on':'')+'" onclick="SEC.j.bk.on=!SEC.j.bk.on;this.classList.toggle(\'on\',SEC.j.bk.on)">🕒 Har kuni</button><button class="chip'+(b.tg?' on':'')+'" onclick="SEC.j.bk.tg=!SEC.j.bk.tg;this.classList.toggle(\'on\',SEC.j.bk.tg)">✈️ Telegram</button></div>'
+'<button class="btn" onclick="secbk()">💾 Hozir nusxa olish</button>'
+(b.files.length?'<div style="margin-top:10px">'+b.files.map(function(f){return '<div class="sub" style="border-top:1px solid var(--ln);padding:6px 0">'+esc(f.name)+' · '+(f.size/1048576).toFixed(2)+' MB · '+esc(f.at)+'</div>'}).join('')+'</div>':'')
+'<p class="sub" style="font-size:12px;margin:8px 0 0">Har kuni 03:00 dan keyin avtomatik olinadi. Serverda oxirgi 7 ta saqlanadi (<code>backups/</code>, tashqaridan ochilmaydi). Telegramga yuboriladigan nusxada API kalit va maxfiy manzillar bo\'lmaydi. Tiklash: <code>gunzip &lt; fayl.sql.gz | mysql -u... -p BAZA</code></p></div>';
h+='<div class="card"><b>🛡 Himoya sozlamalari</b><div class="sub" style="margin:6px 0 2px">Bir foydalanuvchi daqiqasiga eng ko\'pi bilan nechta so\'rov (30–5000)</div><input id="secrl" type="number" inputmode="numeric" value="'+j.rl+'"><div class="sub" style="margin:6px 0 2px">24 soatda nechta raqam bekor qilinsa, raqam olish cheklanadi (2–50)</div><input id="secab" type="number" inputmode="numeric" value="'+j.abuse+'"><div class="sub" style="margin:6px 0 2px">Oq ro\'yxat (ishonchli foydalanuvchi ID lari, vergul bilan) — chegaralar unga tegmaydi</div><input id="secwl" value="'+esc(j.wl)+'" placeholder="123456789, 987654321"><button class="btn" onclick="secconf()">💾 Saqlash</button></div>';
h+='<div class="card"><b>🚫 Qora ro\'yxat</b><div class="sub" style="margin:4px 0 6px">Bloklangan foydalanuvchi ilovadan foydalana olmaydi.</div><input id="secbq" placeholder="ID yoki @username" autocapitalize="off"><button class="btn s" onclick="secblk(1)">🚫 Bloklash</button>'
+(j.blocked.length?'<div style="margin-top:10px">'+j.blocked.map(function(u){return '<div class="row" style="border-top:1px solid var(--ln);padding:8px 0;margin:0"><div><b>'+esc(u.name||'—')+'</b><div class="sub">'+u.id+(u.username?' · @'+esc(u.username):'')+'</div></div><button class="btn s" style="width:auto;padding:6px 12px" onclick="secblk(0,\''+u.id+'\')">✅ Ochish</button></div>'}).join('')+'</div>':'<div class="sub" style="margin-top:8px">Bloklanganlar yo\'q.</div>')+'</div>';
