el.innerHTML=h}
function rpl2(){var v=($('rpsrc').value||'').replace(/[^A-Za-z0-9_-]/g,'');$('rpsrc').value=v;$('rplk').textContent=v?'https://t.me/'+RP.j.bot+'?startapp='+v:''}
