var P5={j:null},FB={};
function lvl(j){var l=j&&j.lv;if(!l||!l.on||(l.reduce<=0&&!l.next))return '';return '<div class="sub" style="margin-top:2px">'+l.icon+' '+l.name+(l.reduce>0?' · ustamada −'+l.reduce+'%':'')+'</div>'}
