else{var td=j.today,tm=j.tomorrow;h+=j.tasks.length?j.tasks.map(function(t){var b='';if(t.due&&!t.done){b=t.due<td?'<span style="color:#d92d20;font-weight:700">⚠️ Muddati o\'tgan</span>':t.due===td?'<span style="color:#d92d20;font-weight:700">Bugun</span>':t.due===tm?'<span style="color:#c77a00;font-weight:700">Ertaga</span>':'<span class="sub">'+esc(t.due.split('-').reverse().join('.'))+'</span>'}
return '<div class="card" style="'+(t.done?'opacity:.55':'')+'"><div class="row" style="margin:0"><div style="flex:1;padding-right:8px"><b'+(t.done?' style="text-decoration:line-through"':'')+'>'+esc(t.subj)+'</b><div class="sub" style="color:var(--tx)">'+esc(t.txt)+'</div>'+(b?'<div style="margin-top:2px;font-size:13px">'+b+'</div>':'')+'</div><div style="display:flex;gap:6px"><button class="chip'+(t.done?' on':'')+'" onclick="hwtd('+t.id+','+(t.done?0:1)+')">'+(t.done?'✅':'⬜')+'</button><button class="chip" onclick="hwtx('+t.id+')">🗑</button></div></div></div>'}).join(''):'<div class="card"><div class="sub">Hozircha vazifa yo\'q.</div></div>';
h+='<div class="card"><b>➕ Vazifa qo\'shish</b><input id="hwv" maxlength="40" placeholder="Fan"><input id="hwx" maxlength="200" placeholder="Vazifa (masalan: 45-bet, 3-mashq)"><div class="sub" style="margin:4px 0 2px">Topshirish sanasi (ixtiyoriy). Kechqurun ertangi vazifalar haqida eslatma keladi.</div><input id="hwd" type="date"><button class="btn" onclick="hwta()">➕ Qo\'shish</button></div>'}
