function adspick(inp){var f=inp.files&&inp.files[0];if(!f)return;var gif=/gif$/i.test(f.type);if(gif&&f.size>2000000){toast('GIF 2 MB dan katta — kichraytiring');return}
var r=new FileReader();r.onload=function(){if(gif){ADS.m=r.result;ADS.mdel=0;adspv();return}var im=new Image();im.onload=function(){var w=Math.min(1200,im.width),h=Math.round(im.height*w/im.width),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h);ADS.m=c.toDataURL('image/jpeg',.86);ADS.mdel=0;adspv()};im.onerror=function(){toast('Rasm o\'qilmadi')};im.src=r.result};r.readAsDataURL(f)}
