function adsr(){var j=ADS.j,el=$('adsa');if(!el||!j)return;var h='<div class="card"><div class="row" style="margin:0"><div><b>Reklama bloki</b><div class="sub">Bosh sahifada ilovalar tagida ko\'rinadi</div></div><button class="chip'+(j.on?' on':'')+'" onclick="adson()">'+(j.on?'✅ Yoqilgan':'⛔ O\'chirilgan')+'</button></div></div><button class="btn s" style="margin-bottom:10px" onclick="ADS.edit=-1;ADS.m=\'\';ADS.mdel=0;adsr()">➕ Yangi reklama</button>';
