function mkr(){var j=MK.d,yt=MK.p==='yt',P=yt?'YouTube':'Instagram',h='<p class="sub" style="margin:-6px 2px 12px">'+P+' '+(yt?'kanallari':'sahifalari')+' savdosi. Ma\'lumotlarni sotuvchi kiritadi — xarid qilishdan oldin akkauntni o\'zingiz tekshiring. Xavfsiz savdo uchun «🛡 Vositachi» (haqi '+j.fee+'%): pul admin orqali o\'tadi.</p>';
h+='<div class="tq-tabs" style="display:flex;gap:8px;margin-bottom:12px">'+[['list','🔎 Sotuvda ('+j.list.length+')'],['mine','➕ Mening e\'lonlarim ('+j.mine.length+')']].map(function(x){return '<button class="btn'+(MK.tab===x[0]?'':' s')+'" style="flex:1" onclick="MK.tab=\''+x[0]+'\';MK.ed=null;mkr()">'+x[1]+'</button>'}).join('')+'</div>';
if(MK.tab==='list')h+=j.list.length?j.list.map(function(c){return '<div class="card"><div class="row"><div style="min-width:0"><b>'+(yt?'▶️ ':'📸 ')+esc(c.title||((yt?'@':'')+c.handle))+(c.ver==1?' <span title="Admin tekshirgan">✅</span>':'')+'</b><div class="sub"><a href="'+esc(c.url)+'" target="_blank" style="color:var(--ac)">'+esc((yt?'@':'@')+c.handle)+'</a> · '+mkf(c.followers)+' '+(yt?'obunachi':'kuzatuvchi')+(c.cat?' · '+esc(c.cat):'')+(yt&&c.monet==1?' · 💵 monetizatsiya':'')+'</div></div><b style="flex:none">'+fmt(+c.price)+'</b></div>'+(c.descr?'<div class="sub" style="margin-top:6px;white-space:pre-wrap">'+esc(c.descr)+'</div>':'')+'<div class="sub" style="margin-top:4px">'+(c.ver==1?'✅ Admin tomonidan tekshirilgan':'⚠️ Ma\'lumotlar sotuvchi tomonidan kiritilgan')+'</div>'+(c.own==1?'<div class="sub" style="margin-top:8px">👤 Bu sizning e\'loningiz</div>':'<div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap"><button class="btn s" onclick="mkm('+c.id+',\'mk_msg\')">📩 Sotuvchiga yozish</button><button class="btn s" onclick="mkm('+c.id+',\'mk_safe\')">🛡 Vositachi</button></div>')+(j.adm&&ADMV?'<div style="display:flex;gap:8px;margin-top:8px"><button class="btn s" onclick="mkv('+c.id+','+(c.ver==1?0:1)+')">'+(c.ver==1?'✖️ Belgini olish':'✅ Tekshirildi deb belgilash')+'</button><button class="btn s" onclick="mkd('+c.id+')">🗑 O\'chirish</button></div>':'')+'</div>'}).join(''):'<div class="card sub">Hozircha sotuvda '+P+' '+(yt?'kanali':'sahifasi')+' yo\'q. Birinchi bo\'lib qo\'shing — «➕ Mening e\'lonlarim».</div>';
else{var E=MK.ed;if(E){h+='<div class="card"><b>'+(E.id?'✏️ E\'lonni tahrirlash':'➕ Yangi e\'lon')+'</b><input id="mk_h" maxlength="80" placeholder="'+(yt?'YouTube kanal: @nomi yoki havola':'Instagram: username yoki havola')+'" value="'+esc(E.handle||'')+'"><input id="mk_t" maxlength="120" placeholder="Nomi (ixtiyoriy)" value="'+esc(E.title||'')+'"><input id="mk_f" type="number" inputmode="numeric" placeholder="'+(yt?'Obunachilar soni':'Kuzatuvchilar soni')+'" value="'+(+E.followers||'')+'"><input id="mk_c" maxlength="40" placeholder="Mavzu (masalan: yangiliklar, sport, ta\'lim)" value="'+esc(E.cat||'')+'"><input id="mk_p" type="number" inputmode="numeric" placeholder="Narx (so\'m)" value="'+(+E.price||'')+'"><textarea id="mk_d" rows="3" maxlength="500" placeholder="Tavsif: auditoriya, daromad, faollik">'+esc(E.descr||'')+'</textarea>'+(yt?'<label class="lr in"><span class="lt"><b>Monetizatsiya yoqilgan</b><span>YouTube dan daromad olinadi</span></span><input type="checkbox" id="mk_m"'+(E.monet==1?' checked':'')+'></label>':'')+'<label class="lr in"><span class="lt"><b>Sotuvda ko\'rsatish</b></span><input type="checkbox" id="mk_o"'+(E.on_==null||E.on_==1?' checked':'')+'></label><div style="display:flex;gap:8px"><button class="btn" onclick="mkSave()">💾 Saqlash</button><button class="btn s" onclick="MK.ed=null;mkr()">Bekor</button></div></div>'}
else h+='<button class="btn" style="margin-bottom:12px" onclick="MK.ed={};mkr()">➕ Yangi e\'lon qo\'shish</button>';
h+=j.mine.length?j.mine.map(function(c){return '<div class="card"><div class="row"><div style="min-width:0"><b>'+esc(c.title||((yt?'@':'')+c.handle))+'</b><div class="sub">'+mkf(c.followers)+' · '+fmt(+c.price)+(c.on_==1?' · ✅ sotuvda':' · ⏸ yashirilgan')+(c.ver==1?' · ✅ tekshirilgan':'')+'</div></div></div><div style="display:flex;gap:8px;margin-top:8px"><button class="btn s" onclick="MK.ed=MK.d.mine.filter(function(x){return +x.id==='+c.id+'})[0];mkr()">✏️ Tahrirlash</button><button class="btn s" onclick="mkd('+c.id+')">🗑 O\'chirish</button></div></div>'}).join(''):(E?'':'<div class="card sub">Sizda hali e\'lon yo\'q.</div>')}
$('mkb').innerHTML=h}
function mkSave(){var E=MK.ed||{};api('mk_save',{plat:MK.p,id:E.id||0,handle:$('mk_h').value,title:$('mk_t').value,followers:$('mk_f').value,cat:$('mk_c').value,price:$('mk_p').value,descr:$('mk_d').value,monet:$('mk_m')&&$('mk_m').checked?1:0,on:$('mk_o').checked?1:0}).then(function(j){if(j.ok){toast('Saqlandi ✅');MK.ed=null;MK.d=j;mkr()}})}
function mkd(id){cf('E\'lon o\'chirilsinmi?',function(y){if(y)api('mk_del',{plat:MK.p,id:id}).then(function(j){if(j.ok){MK.d=j;mkr()}})})}
function mkv(id,v){api('mk_ver',{plat:MK.p,id:id,v:v}).then(function(j){if(j.ok){MK.d=j;mkr()}})}
function mkm(id,a){cf(a==='mk_msg'?'Sotuvchiga sizning ismingiz va profilingiz yuboriladi. Davom etilsinmi?':'TartibOn admini vositachi bo\'ladi: pul admin orqali o\'tadi, akkaunt topshirilgach sotuvchiga beriladi. So\'rov yuborilsinmi?',function(y){if(y)api(a,{plat:MK.p,id:id}).then(function(j){if(j.ok)toast(a==='mk_msg'?'📩 Sotuvchiga yuborildi':'🛡 So\'rov yuborildi — admin bog\'lanadi')})})}
function salm(id){cf('Sotuvchiga sizning ismingiz va profilingiz yuboriladi. Davom etilsinmi?',function(y){if(y)api('sale_msg',{id:id,text:''}).then(function(j){if(j.ok)toast('📩 Sotuvchiga yuborildi — u siz bilan bog\'lanadi')})})}
function sals(id){cf('TartibOn admini vositachi bo\'ladi: pul admin orqali o\'tadi, kanal topshirilgach sotuvchiga beriladi. So\'rov yuborilsinmi?',function(y){if(y)api('sale_safe',{id:id}).then(function(j){if(j.ok)toast('🛡 So\'rov yuborildi — admin bog\'lanadi')})})}
function slOpen(id,pf){pf=pf||'sls';var e=$(pf+id);e.innerHTML='<div class="sk"></div>';api('sale_get',{id:id}).then(function(j){if(j.ok)slDraw(id,j,pf);else e.innerHTML=''})}
function slDraw(id,j,pf){pf=pf||'sls';var p=j.sale,x=pf+id;$(x).innerHTML='<label class="lr in"><span class="lt"><b>Sotuvga qo\'yish</b><span>«Kanal Savdo · Telegram» bo\'limida ko\'rinadi</span></span><input type="checkbox" id="'+x+'o"'+(p.on_==1?' checked':'')+'></label><input id="'+x+'p" type="number" inputmode="numeric" placeholder="Narx (so\'m)" value="'+(+p.price||'')+'"><input id="'+x+'d" maxlength="300" placeholder="Tavsif: mavzu, auditoriya, daromad" value="'+esc(p.descr||'')+'"><button class="btn s" onclick="slSave('+id+',\''+pf+'\')">💾 Saqlash</button>'}
function slSave(id,pf){pf=pf||'sls';var x=pf+id;api('sale_set',{id:id,on:$(x+'o').checked?1:0,price:$(x+'p').value,descr:$(x+'d').value}).then(function(j){if(j.ok){toast('Saqlandi ✅');slDraw(id,j,pf);if(pf==='slm')sall()}})}
var HLV=null,HLN={home:'Bosh sahifa',pcb:'Dollar kursi',pnm:'Namoz vaqtlari',pwx:'Ob-havo',pdp:'Tongi xabar',pev:'Tungi xabar',bt:'Bayram tabriklari',po:'Rejalashtirilgan postlar',gd:'Guruh himoyasi',gw:'Konkurslar',qz:'Testlar',st:'Statistika',rf:'Taklif havolalari',vz:'O\'zaro reklama',auc:'Reklama birjasi',pc:'Pullik kanallar',rt:'Kanallar reytingi',sale:'Kanal Savdo',mk:'Kanal Savdo',my:'Kanallarim',bal:'Balans',ads:'E\'lon berish'};
function hlp(p){var put=function(){var pg=$('p-'+p);if(!pg||!HLV||HLV.indexOf(p)<0)return;var h=pg.querySelector('h1');if(h&&!h.querySelector('.hlpb'))h.insertAdjacentHTML('beforeend',' <button class="hlpb" onclick="hlpS(\''+p+'\')" style="border:0;background:var(--soft);color:var(--ac);border-radius:14px;padding:4px 10px;font-size:14px;font-weight:600;vertical-align:middle;cursor:pointer">❓ Qanday ishlaydi</button>')};if(HLV)put();else api('help_list').then(function(j){HLV=j.ok?j.v:[];put()})}
function hlpS(p){toast('Yuborilmoqda...');api('help_send',{page:p}).then(function(j){if(j.ok)toast('🎓 Video botga yuborildi')})}
function chp(id,d){api('chat_pause',{id:id,days:d}).then(function(j){if(j.ok){toast(d?'⏸ Ta\'til rejimi yoqildi':'▶️ Avtomatik xabarlar qayta yoqildi');chats()}})}
function chpb(id){api('chat_pb',{id:id,share:$('pbs'+id).checked?1:0,don:$('pbd'+id).checked?1:0,text:$('pbt'+id).value,url:$('pbu'+id).value.trim()}).then(function(j){if(j.ok){toast('Saqlandi ✅');$('pbu'+id).value=j.url}})}
function chps(id){toast('Tayyorlanmoqda...');api('chat_passport',{id:id}).then(function(j){if(j.ok)toast('Pasport sizga yuborildi ✅')})}
function por(){var j=POD,h='<div class="card"><b>➕ Yangi post</b>'+(j.chats.length?'<select id="po_c">'+(j.chats.length>1?'<option value="all">🌐 Barcha kanal va guruhlarimga</option>':'')+chopt(j.chats)+'</select><div class="pet">'+[['b','<b>B</b>','Qalin'],['i','<i>I</i>','Kursiv'],['u','<u>U</u>','Tagi chizilgan'],['s','<s>S</s>','O\'chirilgan'],['tg-spoiler','▒','Yashirin'],['code','&lt;/&gt;','Kod'],['blockquote','❝','Iqtibos'],['a','🔗','Havola']].map(function(x){return '<button title="'+x[2]+'" onclick="pfx(\''+x[0]+'\')">'+x[1]+'</button>'}).join('')+'<button title="Emoji" onclick="var e=$(\'pem\');e.style.display=e.style.display===\'flex\'?\'none\':\'flex\'">😊</button></div><div class="pem" id="pem">'+'😀 😂 😍 🥳 😎 🤝 👍 👏 🙏 🔥 ❤️ 💯 ✅ ❌ ⚡️ 📢 📌 🎁 💰 📈 🕌 ☀️ 🌙 🚗 ⏰ 👉 ⬇️ 🆕 ‼️ ❓'.split(' ').map(function(m){return '<button onclick="pins(\''+m+'\')">'+m+'</button>'}).join('')+'</div><textarea id="po_b" rows="6" maxlength="4096" placeholder="Post matni… Matnni belgilab, yuqoridagi tugmalar bilan formatlang" oninput="pprev()"></textarea><div class="sub" id="po_n" style="text-align:right;font-size:11.5px;margin:-4px 0 6px">0 / 4096</div><input id="po_s" placeholder="Rasm/video (ixtiyoriy): t.me/... post havolasi" oninput="pprev()"><div id="po_lib"></div><div style="display:flex;gap:8px"><input id="po_bt" placeholder="Tugma nomi" style="flex:1" oninput="pprev()"><input id="po_bu" placeholder="Tugma havolasi https://" style="flex:1.4" oninput="pprev()"></div><div class="sub" style="margin:4px 0 4px">👁 Telegram\'da shunday ko\'rinadi:</div><div class="ppv" id="po_pv"></div><p class="sub" style="margin:0">Yuborish vaqti (Toshkent) · <a href="#" onclick="pobt();return false" style="color:var(--ac)">🧠 aqlli vaqt</a></p><input id="po_t" type="datetime-local" value="'+dtl(10)+'"><select id="po_r"><option value="none">Bir marta</option><option value="daily">Har kuni</option><option value="weekly">Har hafta</option></select><select id="po_d"><option value="0">🗑 Avto-o\'chirish: yo\'q</option><option value="1">1 soatdan keyin o\'chsin</option><option value="3">3 soatdan keyin</option><option value="6">6 soatdan keyin</option><option value="12">12 soatdan keyin</option><option value="24">⏳ 24 soatdan keyin (1/24 reklama)</option><option value="48">48 soatdan keyin</option><option value="72">72 soatdan keyin</option></select><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" style="flex:1" onclick="pos()">🗓 Rejalashtirish</button><button class="btn s" onclick="pot()">🧪 Menga yuborish</button></div><button class="btn s" style="margin-top:6px" onclick="pobt()">🧠 Eng yaxshi vaqtni qo\'yish</button><p class="sub" style="margin:8px 0 0">Rasm yoki video uchun uni istalgan kanalga (masalan, video baza) joylang va post havolasini kiriting — matn uning tagiga yoziladi. Bot o\'sha kanalda admin bo\'lishi kerak.</p>':'<p class="sub">Avval kanal yoki guruh qo\'shing.</p>')+'</div>';
h+=j.posts.length?'<h1 style="font-size:18px">🗓 Postlar</h1>'+j.posts.map(function(p){return '<div class="card"><div class="row"><b>'+(p.ctype==='Kanal'?'📢 ':'👥 ')+esc(p.username)+'</b><span class="tag">'+(p.active==1?'⏳ '+REP[p.rep]:(+p.sent_n?'✅ Yuborildi':'⏸ To\'xtatilgan'))+'</span></div><div class="sub">'+(p.active==1?'Navbatdagi: '+esc(dtf(p.run_at)):(p.last_at?'Oxirgi: '+esc(dtf(p.last_at)):''))+(+p.sent_n?' · '+p.sent_n+' marta yuborildi':'')+(p.src?' · 🖼 media':'')+(p.btn_text?' · 🔘 '+esc(p.btn_text):'')+(+p.del_h?' · ⏳ '+p.del_h+' soatdan keyin o\'chadi':'')+'</div>'+(p.last_err?'<div class="sub" style="color:var(--r)">⚠️ '+esc(p.last_err)+'</div>':'')+'<div style="white-space:pre-wrap;word-break:break-word;margin:8px 0;font-size:14px;max-height:120px;overflow:hidden">'+esc(p.body)+'</div><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn s" onclick="pocp('+p.id+')">📋 Nusxa</button>'+((p.active==1||p.rep!=='none')?'<button class="btn s" onclick="poa(\'post_toggle\','+p.id+')">'+(p.active==1?'⏸ To\'xtatish':'▶️ Davom ettirish')+'</button>':'')+'<button class="btn s" onclick="poa(\'post_del\','+p.id+')">🗑 O\'chirish</button></div></div>'}).join(''):'';
$('pob').innerHTML=h;podr();plib();pprev()}
function pov(){return {chat:$('po_c').value,body:$('po_b').value,src:$('po_s').value,btn_text:$('po_bt').value,btn_url:$('po_bu').value,run_at:$('po_t').value,rep:$('po_r').value,del_h:$('po_d').value}}
function pos(){api('post_save',pov()).then(function(j){if(j.ok){try{localStorage.removeItem('po_draft')}catch(e){}toast(j.n>1?j.n+' ta kanal/guruhga rejalashtirildi ✅':'Rejalashtirildi ✅');pol()}})}
function pfx(t){var a=$('po_b');if(!a)return;var s=a.selectionStart,e=a.selectionEnd,v=a.value,sel=v.slice(s,e);var o='<'+t+'>',c='</'+t+'>';if(t==='a'){var u=prompt('Havola (https://...)','https://');if(!u)return;o='<a href="'+u.replace(/"/g,'')+'">';c='</a>';if(!sel)sel='havola'}a.value=v.slice(0,s)+o+sel+c+v.slice(e);a.focus();a.selectionStart=s+o.length;a.selectionEnd=s+o.length+sel.length;pprev()}
function pins(m){var a=$('po_b');if(!a)return;var s=a.selectionStart;a.value=a.value.slice(0,s)+m+a.value.slice(a.selectionEnd);a.focus();a.selectionStart=a.selectionEnd=s+m.length;pprev()}
function phtml(t){var h=esc(t);h=h.replace(/&lt;(\/?)(b|strong|i|em|u|ins|s|strike|del|code|pre|blockquote)&gt;/g,'<$1$2>').replace(/&lt;tg-spoiler&gt;/g,'<span class="spl">').replace(/&lt;\/tg-spoiler&gt;/g,'</span>').replace(/&lt;a href=(?:&quot;|&#39;)(https?:\/\/[^&"']+)(?:&quot;|&#39;)&gt;/g,'<a href="$1" target="_blank" rel="noopener">').replace(/&lt;\/a&gt;/g,'</a>');return h.replace(/\n/g,'<br>')}
function pprev(){var a=$('po_b'),pv=$('po_pv');if(!a||!pv)return;var m=$('po_s').value.trim(),lim=m?1024:4096,n=a.value.length;$('po_n').textContent=n+' / '+lim+(m?' (rasm/video bilan)':'');$('po_n').style.color=n>lim?'var(--r)':'';var bt=$('po_bt').value.trim();pv.innerHTML=(m?'<div class="ppm">🖼 Media: '+esc(m.replace(/^https?:\/\//,''))+'</div>':'')+'<div class="ppt">'+(a.value.trim()?phtml(a.value):'<span class="sub">Post matni shu yerda ko\'rinadi</span>')+'</div>'+(bt?'<div class="ppb">'+esc(bt)+'</div>':'');try{localStorage.setItem('po_draft',JSON.stringify({b:a.value,s:m,bt:bt,bu:$('po_bu').value}))}catch(e){}}
function podr(){var d=null;try{d=JSON.parse(localStorage.getItem('po_draft')||'null')}catch(e){}if(!d||!$('po_b')||$('po_b').value)return;$('po_b').value=d.b||'';$('po_s').value=d.s||'';$('po_bt').value=d.bt||'';$('po_bu').value=d.bu||'';if(d.b)toast('📝 Qoralama tiklandi')}
var PLIB=[];function plib(){var e=$('po_lib');if(!e||!POD)return;PLIB=[];POD.posts.forEach(function(p){if(p.src&&PLIB.indexOf(p.src)<0)PLIB.push(p.src)});PLIB=PLIB.slice(0,8);e.innerHTML=PLIB.length?'<div class="sub" style="font-size:12px;margin:-4px 0 4px">🗂 Avval ishlatilgan media:</div><div class="plb">'+PLIB.map(function(s,i){return '<button onclick="$(\'po_s\').value=PLIB['+i+'];pprev()">🖼 '+esc(s.replace(/^https?:\/\/(t\.me\/)?/,'').slice(0,22))+'</button>'}).join('')+'</div>':''}
function pocp(id){var p=POD.posts.filter(function(x){return +x.id===id})[0];if(!p)return;$('po_b').value=p.body||'';$('po_s').value=p.src||'';$('po_bt').value=p.btn_text||'';$('po_bu').value=p.btn_url||'';pprev();window.scrollTo(0,0);toast('📋 Post muharrirga nusxalandi')}
function pot(){api('post_test',pov()).then(function(j){if(j.ok)toast('Sizga yuborildi ✅')})}
function poa(a,id){var go2=function(){api(a,{id:id}).then(function(j){if(j.ok)pol()})};if(a==='post_del')cf('Post o\'chirilsinmi?',function(y){if(y)go2()});else go2()}
/* ---- Statistika ---- */
function stl(){$('stb').innerHTML='<div class="sk"></div>';api('stat_my').then(function(j){if(!j.ok)return;var h='';
var dl=function(v,t){return v==null?'':'<div style="flex:1;text-align:center"><b class="'+(v>0?'g':v<0?'r':'')+'">'+(v>0?'+':'')+f(v)+'</b><div class="sub">'+t+'</div></div>'};
var bars=function(D,k,col){var mx=1,mn=null;D.forEach(function(d){var v=+d[k];if(d[k]!=null&&v>=0){mx=Math.max(mx,v);mn=mn==null?v:Math.min(mn,v)}});if(mn==null)return '';var base=k==='members'?Math.max(0,mn-(mx-mn)*0.3-1):0;
return '<div style="display:flex;align-items:flex-end;gap:3px;height:56px;margin-top:8px">'+D.map(function(d){var v=+d[k];var hh=d[k]==null||v<0?0:Math.max(3,Math.round((v-base)/(mx-base)*56));return '<div title="'+esc(d.day)+': '+f(v)+'" style="flex:1;height:'+hh+'px;background:'+col+';border-radius:3px 3px 0 0"></div>'}).join('')+'</div>'};
h+=j.chats.length?j.chats.map(function(c){var D=c.days||[],ms=0,jn=0,lf=0;D.forEach(function(d){ms+=+d.msgs;jn+=+d.joins;lf+=+d.lefts});
return '<div class="card"><div class="row"><b>'+(c.ctype==='Kanal'?'📢 ':'👥 ')+esc(c.username)+'</b><span class="sub">'+(c.ctype==='Kanal'?'obunachi':'a\'zo')+'</span></div><div style="font-size:30px;font-weight:700;margin:6px 0">'+(c.now==null?'—':f(c.now))+'</div><div style="display:flex;gap:6px">'+dl(c.d1,'kecha')+dl(c.d7,'7 kun')+dl(c.d30,'30 kun')+'</div>'+bars(D,'members','var(--ac)')+'<div class="sub" style="margin-top:4px">So\'nggi 14 kun · '+(c.ctype==='Guruh'?'💬 '+f(ms)+' xabar · ':'')+(jn||lf?'➕ '+f(jn)+' kirdi · ➖ '+f(lf)+' chiqdi':'kirdi-chiqdi bot admin bo\'lgach hisoblanadi')+'</div>'+(c.ctype==='Guruh'&&ms?bars(D,'msgs','#34c759'):'')+'<button class="btn s" style="margin-top:8px" onclick="stcsv('+c.id+')">📤 Excel (CSV) yuklab olish</button></div>'}).join(''):'<div class="card sub">Kanal yoki guruh qo\'shing — statistika shu yerda chiqadi.</div>';
h+='<div class="card row" style="cursor:pointer" onclick="api(\'stat_wr\',{on:'+(j.wr?0:1)+'}).then(stl)"><div style="display:flex;align-items:center;gap:10px">'+ck(j.wr)+'<div><b>📨 Haftalik hisobot</b><div class="sub">har dushanba soat 9:00 da sizga shaxsan</div></div></div></div><p class="sub" style="margin:0 4px 12px">Postlarning ko\'rishlar sonini Telegram botlarga bermaydi, shuning uchun ular hisobotda yo\'q.</p>';
$('stb').innerHTML=h})}
/* ---- Konkurslar ---- */
var GWD=null,GWS={active:'⏳ Davom etmoqda',done:'✅ Yakunlandi',cancel:'❌ Bekor qilingan'};
function gwl(){api('gw_list').then(function(j){if(!j.ok)return;GWD=j;gwr()})}
function gwr(){var j=GWD,h='<div class="card"><b>🎁 Yangi konkurs</b>'+(j.chats.length?'<p class="sub" style="margin:8px 0 0">Qayerda e\'lon qilinadi</p><select id="gw_c">'+chopt(j.chats)+'</select><textarea id="gw_t" rows="5" maxlength="1500" placeholder="Konkurs haqida: sovrin, qoidalar..."></textarea><p class="sub" style="margin:0 0 4px">Shart — obuna bo\'lish kerak:</p><p class="sub" style="margin:0 0 6px;padding:8px 10px;border-radius:12px;background:var(--soft);color:var(--tx)">ℹ️ Ro\'yxatda faqat bot administrator bo\'lgan kanal va guruhlar chiqadi. Boshqa kanal yoki guruhni shart qilish uchun avval botni o\'sha kanal/guruhga <b>administrator</b> qiling va «Kanal qo\'shish» yoki «Guruh qo\'shish» orqali ulang.</p>'+j.chats.map(function(c,n){return '<label style="display:block;margin:6px 0"><input type="checkbox" class="gw_rq" value="'+c.id+'" style="width:auto;margin:0 8px 0 0"'+(n===0?' checked':'')+'> '+(c.ctype==='Kanal'?'📢 ':'👥 ')+esc(c.username)+'</label>'}).join('')+'<div style="display:flex;gap:8px"><div style="flex:1"><p class="sub" style="margin:0">G\'oliblar soni</p><input id="gw_w" type="number" inputmode="numeric" min="1" max="20" value="1"></div><div style="flex:1.6"><p class="sub" style="margin:0">Yakunlanish (Toshkent)</p><input id="gw_e" type="datetime-local" value="'+dtl(1440)+'"></div></div><button class="btn" onclick="gwc()">🚀 Konkursni boshlash</button><p class="sub" style="margin:8px 0 0">Post tugma bilan joylanadi. Bosganlarning obunasi tekshiriladi. Vaqt tugaganda g\'oliblar tasodifiy tanlanib (obunadan chiqqanlar hisobga olinmaydi) e\'lon qilinadi.</p>':'<p class="sub">Avval kanal yoki guruh qo\'shing.</p>')+'</div>';
h+=j.list.map(function(g){var w=g.result?JSON.parse(g.result):[];return '<div class="card"><div class="row"><b>'+esc(g.username)+'</b><span class="tag">'+GWS[g.status]+'</span></div><div class="sub">👥 '+g.n+' ishtirokchi · 🏆 '+g.winners+' g\'olib · ⏰ '+esc(dtf(g.ends_at))+'</div><div style="white-space:pre-wrap;word-break:break-word;margin:8px 0;font-size:14px;max-height:90px;overflow:hidden">'+esc(g.title)+'</div>'+(w.length?'<div class="sub">G\'oliblar: '+w.map(function(x){return esc(x.name)+(x.username?' @'+esc(x.username):'')}).join(', ')+'</div>':'')+(g.status==='active'?'<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px"><button class="btn s" onclick="gwa(\'gw_finish\','+g.id+')">🏁 Hozir yakunlash</button><button class="btn s" onclick="gwa(\'gw_cancel\','+g.id+')">❌ Bekor qilish</button></div>':'')+'</div>'}).join('');
$('gwb').innerHTML=h}
function gwc(){var rq=[];document.querySelectorAll('.gw_rq').forEach(function(x){if(x.checked)rq.push(x.value)});api('gw_create',{chat:$('gw_c').value,title:$('gw_t').value,req:rq,winners:$('gw_w').value,ends:$('gw_e').value}).then(function(j){if(j.ok){toast('Konkurs boshlandi 🎉');gwl()}})}
function gwa(a,id){cf(a==='gw_finish'?'Konkurs hozir yakunlanib, g\'oliblar e\'lon qilinsinmi?':'Konkurs bekor qilinsinmi?',function(y){if(y)api(a,{id:id}).then(function(j){if(j.ok)gwl()})})}
/* ---- Taklif havolalari ---- */
var RFD=null;
function rfl(){api('ref_list').then(function(j){if(!j.ok)return;RFD=j;rfr()})}
function rfr(){var j=RFD,md=['🥇','🥈','🥉'],h='<div class="card"><b>🔗 Do\'stlarni taklif qiling</b><div class="sub" style="margin-top:6px">Shaxsiy havolangizni oling va tarqating. Havola orqali kirgan har bir odam sizga hisoblanadi. Eng ko\'p taklif qilganlar reytingda.</div></div>';
h+=j.open.length?j.open.map(function(c,i){return '<div class="card"><div class="row"><b>'+(c.ctype==='Kanal'?'📢 ':'👥 ')+esc(c.username)+'</b>'+(c.rank?'<span class="tag">'+(md[c.rank-1]||c.rank+'-o\'rin')+'</span>':'')+'</div>'+(c.link?'<input readonly value="'+esc(c.link)+'" onclick="this.select()"><div class="sub">Siz taklif qilganlar: <b>'+c.joins+'</b></div><div style="display:flex;gap:6px;margin-top:8px"><button class="btn s" onclick="rfcp('+i+')">📋 Nusxalash</button><button class="btn s" onclick="rfsh('+i+')">📤 Ulashish</button></div>':'<button class="btn" style="margin-top:8px" onclick="rfg('+c.id+')">🔗 Havolamni olish</button>')+(c.top.length?'<p style="margin:12px 0 4px"><b>🏆 Reyting</b></p>'+c.top.map(function(t,n){return '<div class="row sub" style="padding:3px 0"><span>'+(md[n]||(n+1)+'.')+' '+esc(t.name)+'</span><b>'+t.joins+'</b></div>'}).join(''):'')+'</div>'}).join(''):'<div class="card sub">Hozircha taklif tanlovi yo\'q.</div>';
if(j.mine.length)h+='<h1 style="font-size:18px">⚙️ Mening kanal/guruhlarim</h1><div class="card"><div class="sub" style="margin-bottom:4px">Yoqilsa, a\'zolar shaxsiy taklif havolasini oladi. Botga «Havola orqali taklif qilish» huquqi kerak.</div>'+j.mine.map(function(c){return '<div class="row" style="padding:10px 0;border-top:1px solid var(--ln);cursor:pointer" onclick="rft('+c.id+')"><div style="display:flex;align-items:center;gap:10px">'+ck(c.ref_on==1)+'<b>'+(c.ctype==='Kanal'?'📢 ':'👥 ')+esc(c.username)+'</b></div></div>'+(c.ref_on==1?'<div style="display:flex;gap:6px;margin:0 0 8px"><button class="btn s" onclick="rftop('+c.id+',this)">🏆 Reyting</button><button class="btn s" onclick="rfp('+c.id+')">📣 Reytingni yuborish</button></div><div id="rft'+c.id+'"></div>':'')}).join('')+'</div>';
$('rfb').innerHTML=h}
function rfg(id){api('ref_get',{id:id}).then(function(j){if(j.ok)rfl()})}
function rfcp(i){var t=RFD.open[i].link;var ok=function(){toast('Nusxalandi ✅')};try{navigator.clipboard.writeText(t).then(ok,function(){prompt('Nusxalang:',t)})}catch(e){prompt('Nusxalang:',t)}}
function rfsh(i){var u='https://t.me/share/url?url='+encodeURIComponent(RFD.open[i].link);try{tg.openTelegramLink(u)}catch(e){location.href=u}}
function rft(id){api('ref_toggle',{id:id}).then(function(j){if(j.ok){if(j.warn)toast('⚠️ '+j.warn);rfl()}})}
function rftop(id){api('ref_top',{id:id}).then(function(j){if(!j.ok)return;$('rft'+id).innerHTML='<div class="sub" style="margin-bottom:8px">Jami taklif orqali kirganlar: <b>'+j.total+'</b></div>'+(j.top.length?j.top.map(function(t,n){return '<div class="row sub" style="padding:3px 0"><span>'+(n+1)+'. '+esc(t.name)+(t.username?' @'+esc(t.username):'')+'</span><b>'+t.joins+'</b></div>'}).join(''):'<div class="sub">Hali hech kim yo\'q.</div>')})}
function rfp(id){cf('Reyting kanal/guruhga yuborilsinmi?',function(y){if(y)api('ref_post',{id:id}).then(function(j){if(j.ok)toast('Yuborildi ✅')})})}
function gda(){api('adm_guard').then(function(j){if(j.ok){GDA=j;av('gd')}})}
function ail(){api('adm_ai_cfg',{limit:$('ai_l').value}).then(function(j){if(j.ok){GDA.ai.limit=+$('ai_l').value;toast('Saqlandi ✅')}})}
function ait(){$('ai_r').textContent='Tekshirilmoqda...';api('adm_ai_test',{text:$('ai_t').value}).then(function(j){$('ai_r').textContent=j.ok?'Natija: '+({ok:'✅ oddiy xabar',spam:'📣 spam/reklama',porn:'🔞 behayo',refusal:'⚠️ model javob bermadi'}[j.verdict]||j.verdict)+' · bugun '+j.used+' so\'rov':'Xato: '+(j.error||'')})}
function gdw(){api('adm_guard_words',{words:$('gd_w').value}).then(function(j){if(j.ok){GDA.words=$('gd_w').value;toast('Saqlandi ✅')}})}
var DPC=null;
var BTC=null;
function btl(){$('btb').innerHTML='<div class="sk"></div><div class="sk"></div>';api('bt_my').then(function(j){if(j.ok){BTC=j;btr()}})}
function btdf(d){if(!d)return '';var p=d.split('-');return p[2]+'.'+p[1]+'.'+p[0]}
function btr(){var j=BTC,C=j.cfg,A=j.adm&&ADMV,h='<p class="sub" style="margin:-6px 2px 12px">Har Juma va bayram kunlari soat <b>'+esc(C.time)+'</b> da kanal va guruhlaringizga video tabrik (tagida matn bilan) yuboriladi.'+(C.on?'':' <b style="color:var(--r)">Hozir o\'chirilgan.</b>')+'</p>';
if(A)h+='<div class="card row" style="cursor:pointer" onclick="btf(\'\')"><div style="display:flex;align-items:center;gap:10px">'+ck(C.on)+'<div><b>Bayram tabriklari</b><div class="sub">'+C.n+' ta kanal/guruh · oxirgi: '+esc(C.last||'—')+'</div></div></div></div>';
h+='<div class="row" style="margin:4px 2px 8px"><b>Bayramlar</b></div>'+C.items.map(function(x){var nx=x.next?btdf(x.next):(x.fix===''?'sana kiritilmagan':'');return '<div class="card"><div class="row"><div style="display:flex;align-items:center;gap:10px;min-width:0">'+(A?'<span style="cursor:pointer;flex:none" onclick="btf(\''+x.k+'\')">'+ck(x.o)+'</span>':'')+'<div style="min-width:0"><b>'+(x.k==='juma'?'🕌 ':'🎉 ')+esc(x.name)+'</b><div class="sub">'+(x.fix==='fri'?'Har Juma · keyingisi: ':'')+esc(nx)+' · '+(x.v?'🎬 video':'📝 matn')+(x.a?' + 🔊 ovoz':'')+(x.o?'':' · ⛔ o\'chirilgan')+'</div></div></div><button class="btn s" style="flex:none" onclick="btt(\''+x.k+'\')">📩 Namuna</button></div>'
+(A?'<details style="margin-top:8px"><summary class="sub">✏️ Video va matnni o\'zgartirish</summary>'+(x.fix===''?'<p class="sub" style="margin:8px 0 4px">Bayram sanasi (har yili o\'zgaradi):</p><input id="btd_'+x.k+'" type="date" value="'+esc(x.d)+'">':'')+'<p class="sub" style="margin:8px 0 4px">Video havolasi (baza kanaldagi post):</p><input id="btv_'+x.k+'" placeholder="https://t.me/c/1234567890/45" value="'+esc(x.v)+'"><p class="sub" style="margin:8px 0 4px">Video tagidagi matn — {sana}, {yil}, {yosh}, {bayram}; qalin: &lt;b&gt;..&lt;/b&gt;</p><textarea id="btt_'+x.k+'" rows="7" maxlength="1024">'+esc(x.t)+'</textarea><p class="sub" style="margin:8px 0 4px">🔊 Ovoz (mp3) havolasi — baza kanaldagi post; video va matn tagida alohida xabar bo\'lib ketadi (ixtiyoriy):</p><input id="bta_'+x.k+'" placeholder="https://t.me/c/1234567890/46" value="'+esc(x.a||'')+'"><button class="btn" onclick="bts()">💾 Saqlash</button></details>':'')+'</div>'}).join('');
if(A)h+='<div class="card"><b>⏰ Yuborish vaqti (Toshkent)</b><input id="bt_time" type="time" value="'+esc(C.time)+'"><button class="btn s" onclick="bts()">Saqlash</button><p class="sub" style="margin-top:6px">Video baza kanaldan olinadi: botni baza kanalga administrator qiling, videoni joylang va post havolasini (Копировать ссылку) kiriting. Bir kunga bayram va Juma to\'g\'ri kelsa — bayram tabrigi yuboriladi.</p></div>';
h+='<div class="row" style="margin:12px 2px 8px"><b>Kanallarim</b>'+(j.chats.length?'<button class="btn s" onclick="btall()">✅ Hammasi</button>':'')+'</div>'+(j.chats.length?j.chats.map(function(c,i){return '<div class="card row" style="cursor:pointer" onclick="btc('+i+')"><div style="display:flex;align-items:center;gap:10px">'+ck(c.bt_on==1)+'<b>'+esc(c.username)+'</b></div><span class="sub">'+esc(c.ctype)+'</span></div>'}).join(''):'<div class="card sub">Tasdiqlangan kanal yoki guruh yo\'q. Avval «Kanal qo\'shish» orqali qo\'shing.</div>');
$('btb').innerHTML=h}
function btf(k){var C=BTC.cfg,on=k?!C.items.filter(function(x){return x.k===k})[0].o:!C.on;api('adm_bt_flag',{k:k,on:on?1:0}).then(function(j){if(j.ok){BTC.cfg=j.bt;btr()}})}
function bts(){var o={time:($('bt_time')||{}).value||BTC.cfg.time,items:{}};BTC.cfg.items.forEach(function(x){var v=$('btv_'+x.k),t=$('btt_'+x.k),d=$('btd_'+x.k),a=$('bta_'+x.k);o.items[x.k]={v:v?v.value.trim():x.v,a:a?a.value.trim():(x.a||''),t:t?t.value:x.t,d:d?d.value:x.d}});api('adm_bt',o).then(function(j){if(j.ok){BTC.cfg=j.bt;btr();toast('Saqlandi ✅')}})}
function btt(k){toast('Yuborilmoqda...');api('bt_test',{k:k}).then(function(j){if(j.ok)toast(j.vo?'Tabrik ketdi, lekin ovoz yuborilmadi: '+j.vo:'Sizga yuborildi ✅')})}
function btc(i){var c=BTC.chats[i],on=c.bt_on==1?0:1;api('bt_my_set',{id:c.id,on:on}).then(function(j){if(j.ok){c.bt_on=on;btr();toast(on?'Yoqildi ✅':'O\'chirildi')}})}
function btall(){api('bt_my_set',{id:0,on:1}).then(function(j){if(j.ok){BTC.chats.forEach(function(c){c.bt_on=1});btr();toast('Hamma kanal va guruhlarga yoqildi ✅')}})}
function dpl(){$('dpb').innerHTML='<div class="sk"></div>';api('dp_my').then(function(j){if(j.ok){DPC=j;dpr()}})}
function ck(on){return '<span class="sw'+(on?' on':'')+'"></span>'}
function dpr(){var j=DPC,D=j.cfg,h='';
if(D){h+='<div class="card row" style="cursor:pointer" onclick="dpf(0)"><div style="display:flex;align-items:center;gap:10px">'+ck(D.on)+'<div><b>Tongi xabar</b><div class="sub">har kuni '+esc(D.time)+' · '+D.n+' ta kanal</div></div></div><span class="sub">'+(D.on?'Yoqilgan':'O\'chirilgan')+'</span></div>'
+'<div class="row" style="margin:4px 2px 8px"><b>Hafta kunlari</b><button class="btn s" onclick="dpa()">✅ Hammasi</button></div>'
+D.days.map(function(x){return '<div class="card row" style="cursor:pointer" onclick="dpf('+x.d+')"><div style="display:flex;align-items:center;gap:10px">'+ck(x.o)+'<b>'+esc(x.name)+'</b></div><span class="sub">'+(x.v?'🎬 video':'📝 matn')+'</span></div>'}).join('')}
else if(!j.on)h+='<div class="card sub">Tongi xabar hozircha o\'chirilgan.</div>';
h+='<div class="row" style="margin:4px 2px 8px"><b>Kanallarim</b>'+(D?'':'<span class="sub">har kuni '+esc(j.time)+'</span>')+'</div>'+(j.chats.length?j.chats.map(function(c,i){return '<div class="card row" style="cursor:pointer" onclick="dpc('+i+')"><div style="display:flex;align-items:center;gap:10px">'+ck(c.dp_on==1)+'<b>'+esc(c.username)+'</b></div><span class="sub">'+esc(c.ctype)+'</span></div>'}).join(''):'<div class="card sub">Tasdiqlangan kanal yoki guruh yo\'q. Avval «Kanal qo\'shish» orqali qo\'shing.</div>');
$('dpb').innerHTML=h}
function dpf(d,on){var D=DPC.cfg;if(on==null)on=d?!D.days[d-1].o:!D.on;return api('adm_dp_flag',{d:d,on:on}).then(function(j){if(j.ok){DPC.cfg=j.dp;DPC.on=j.dp.on;if(AD)AD.dp=j.dp;dpr()}return j})}
function dpa(){var p=Promise.resolve();DPC.cfg.days.forEach(function(x){if(!x.o)p=p.then(function(){return dpf(x.d,true)})});p.then(function(){toast('7 kun yoqildi ✅')})}
function hm2(m){return m<60?m+' daqiqa':Math.floor(m/60)+' soat'+(m%60?' '+m%60+' daq':'')}
function prh(){api('pr_home').then(function(j){var e=$('prh');if(!e)return;if(!j.ok){e.innerHTML='';return}var my='';try{my=localStorage.getItem('pr_reg')||''}catch(x){}
e.innerHTML='<div class="sc" style="cursor:pointer" onclick="go(\'pr\')"><div class="sh2">Namoz vaqtlari <span class="sub">· '+j.icon+' '+(j.tomorrow?'Ertaga ':'')+esc(j.name)+' · '+(j.started?'vaqti kirdi':hm2(j.mins)+' qoldi')+'</span><span class="chv2">›</span></div><div class="pgr">'+j.rows.map(function(x){return '<div'+(x.r===my?' class="me"':'')+'><span>'+esc(x.n)+'</span><b>'+esc(x.t)+'</b></div>'}).join('')+'</div></div>'})}
setInterval(function(){var p=$('p-pnm');if(p&&p.classList.contains('on'))prh()},120000);
function dpc(i){var c=DPC.chats[i],on=c.dp_on==1?0:1;api('dp_my_set',{id:c.id,on:on}).then(function(j){if(j.ok){c.dp_on=on;dpr();toast(on?'Yoqildi ✅':'O\'chirildi')}})}
function dpv(){var o={time:$('dp_time').value,days:{}};AD.dp.days.forEach(function(x){o.days[x.d]={v:$('dp_v'+x.d).value.trim(),a:$('dp_a'+x.d).value.trim(),t:$('dp_t'+x.d).value}});return o}
function dps(cb){api('adm_dp',dpv()).then(function(j){if(!j.ok)return;AD.dp=j.dp;if(cb)cb();else{toast('Saqlandi ✅');av('dp')}})}
function dpt(d){dps(function(){api('adm_dp_test',{d:d}).then(function(j){if(j.ok)toast(j.vo?'Tabrik ketdi, lekin ovoz yuborilmadi: '+j.vo:'Sizga yuborildi ✅')})})}
/* ---- 🚗 PRAVA: nazariy imtihonga tayyorgarlik ---- */
var DV={v:'home',d:null,run:null,al:null,af:{t:-1,tp:0,s:'',p:0},ed:null,ai:null};
function dvl(){if(!DV.d)$('dvb').innerHTML='<div class="sk"></div><div class="sk"></div>';api('pv_home').then(function(j){if(!j.ok)return;DV.d=j;if(DV.want){DV.v=j.admin?DV.want:'home';DV.want=null;if(DV.v==='adm')dvaq(0)}if(DV.v!=='run')dvr()})}
function dvgo(v){DV.v=v;dvr();window.scrollTo(0,0)}
function dvr(){var j=DV.d,v=DV.v,h='';if(!j)return;
if(v==='home'){var tk=j.tickets.length,pct=j.total?Math.round(j.me.ok*100/j.total):0;
h+='<div class="card" style="text-align:center"><div style="font-size:44px;line-height:1">🚗</div><b style="font-size:20px;display:block;margin-top:6px">Barcha testlar bir joyda</b><div class="sub" style="margin-top:4px">Haydovchilik guvohnomasi nazariy imtihoniga bepul tayyorgarlik</div><div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:14px">'+[[j.total,'savol'],[tk,'bilet'],[j.topics.filter(function(t){return +t.n}).length,'mavzu']].map(function(x){return '<div style="padding:10px 4px;border-radius:14px;border:1.5px solid var(--ln)"><b style="font-size:22px;color:var(--ac2,var(--ac))">'+nf(+x[0])+'</b><div class="sub" style="font-size:12px">'+x[1]+'</div></div>'}).join('')+'</div>'
+'<div style="margin-top:14px;text-align:left"><div class="row sub"><span>Tayyorgarligingiz</span><b>'+pct+'%</b></div><div style="height:8px;border-radius:4px;background:var(--in);margin-top:6px"><div style="height:8px;border-radius:4px;background:var(--g);width:'+pct+'%"></div></div></div></div>';
if(j.demo&&j.demo===j.total)h+='<div class="card sub">ℹ️ Savollar bazasi hozircha to\'ldirilmoqda. Hozircha '+j.demo+' ta namuna savol bor — sinab ko\'ring.</div>';
h+='<button class="btn" style="padding:16px;font-size:17px" onclick="dvstart(\'exam\',0)">🎯 Imtihon — '+j.cfg.n+' savol · '+j.cfg.min+' daqiqa</button><p class="sub" style="text-align:center;margin:6px 0 12px">Haqiqiy imtihondek: '+j.cfg.err+' tagacha xato mumkin</p>';
h+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">'+[['📋','Biletlar',tk?tk+' ta bilet':'tez orada',"dvgo('tickets')"],['📚','Mavzular',j.topics.length+' ta mavzu',"dvgo('topics')"],['🔁','Xatolarim',j.me.bad+' ta savol',"dvstart('mist',0)"],['⭐','Saqlanganlar',j.me.fav+' ta savol',"dvstart('fav',0)"]].map(function(x){return '<div class="card" style="margin:0;cursor:pointer;text-align:center;padding:14px 8px" onclick="'+x[3]+'"><div style="font-size:28px">'+x[0]+'</div><b>'+x[1]+'</b><div class="sub" style="font-size:12px">'+x[2]+'</div></div>'}).join('')+'</div>';
if(j.demo&&j.demo===j.total)h+='<button class="btn s" style="margin-top:10px" onclick="dvstart(\'demo\',0)">✍️ Namuna savollarni ishlash</button>';
if(j.hist.length)h+='<div class="card" style="margin-top:12px"><b>📊 Oxirgi natijalar</b>'+j.hist.map(function(r){var nm={exam:'🎯 Imtihon',ticket:'📋 '+r.ref+'-bilet',topic:'📚 Mavzu',mist:'🔁 Xatolar',fav:'⭐ Saqlanganlar',demo:'✍️ Namuna'}[r.kind]||r.kind;return '<div class="row" style="padding:8px 0;border-top:1px solid var(--ln);margin-top:6px"><div><b style="font-size:14px">'+nm+'</b><div class="sub" style="font-size:12px">'+dmy(r.at)+' · '+Math.floor(r.secs/60)+':'+('0'+r.secs%60).slice(-2)+'</div></div><span class="tag" style="'+(+r.passed?'background:#34c75926;color:#1fa245':'background:#ff3b3022;color:#e0372d')+'">'+r.correct+'/'+r.total+(r.kind==='exam'||r.kind==='ticket'?(+r.passed?' · o\'tdi':' · yiqildi'):'')+'</span></div>'}).join('')+'</div>';
h+='<div class="card" style="margin-top:12px;cursor:pointer;display:flex;align-items:center;gap:12px" onclick="SJ.want=\'pv\';go(\'psj\')"><div style="font-size:30px">👥</div><div style="flex:1"><b>Guruh yoki kanalda birgalikda test</b><div class="sub" style="font-size:13px">Prava savollari guruhingizga so\'rovnoma bo\'lib keladi, a\'zolar ochko yig\'adi</div></div><span class="sub">›</span></div>';
}
if(v==='tickets')h+='<button class="bkb" onclick="dvgo(\'home\')">‹ Prava</button><h1 style="font-size:22px">📋 Biletlar</h1>'+(j.tickets.length?'<div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px">'+j.tickets.map(function(t){var c=t.best<0?'var(--in)':(+t.passed?'#34c75930':'#ff3b3026');return '<button onclick="dvstart(\'ticket\','+t.t+')" style="border:0;border-radius:14px;padding:12px 4px;background:'+c+';color:var(--tx);cursor:pointer"><b style="font-size:18px">'+t.t+'</b><div class="sub" style="font-size:11px">'+(t.best<0?t.n+' savol':t.best+'/'+t.n)+'</div></button>'}).join('')+'</div><p class="sub" style="margin-top:10px">🟩 o\'tilgan · 🟥 '+j.cfg.err+' tadan ko\'p xato · ⬜ hali ishlanmagan</p>':'<div class="card sub">Biletlar hali tuzilmagan.</div>');
if(v==='topics')h+='<button class="bkb" onclick="dvgo(\'home\')">‹ Prava</button><h1 style="font-size:22px">📚 Mavzular</h1>'+j.topics.map(function(t){var n=+t.n,ok=+t.ok||0,p=n?Math.round(ok*100/n):0;return '<div class="card" style="cursor:pointer;'+(n?'':'opacity:.55')+'" onclick="'+(n?'dvstart(\'topic\','+t.id+')':'toast(\'Bu mavzuda hali savol yo\\\'q\')')+'"><div class="row"><b style="font-size:15px">'+esc(t.title)+'</b><span class="sub">'+n+' savol</span></div><div style="height:6px;border-radius:3px;background:var(--in);margin-top:8px"><div style="height:6px;border-radius:3px;background:var(--g);width:'+p+'%"></div></div></div>'}).join('');
if(v==='run')return dvq();if(v==='res')return dvres();if(v==='adm')h+=dvadm();
$('dvb').innerHTML=h}
function dvstart(m,ref){api('pv_q',{mode:m,ref:ref}).then(function(j){if(!j.ok)return;DV.run={mode:m,ref:ref,list:j.list,i:0,ans:{},ok:0,bad:0,t0:Date.now(),lim:m==='exam'?j.cfg.min*60:0,err:j.cfg.err,end:0};DV.v='run';dvq();window.scrollTo(0,0);clearInterval(DV.tm);if(m==='exam')DV.tm=setInterval(function(){var e=$('dvtm');if(!e||DV.v!=='run'){clearInterval(DV.tm);return}var l=DV.run.lim-Math.floor((Date.now()-DV.run.t0)/1000);if(l<=0){clearInterval(DV.tm);DV.run.timeout=1;dvfin()}else e.textContent=Math.floor(l/60)+':'+('0'+l%60).slice(-2)},1000)})}
function dvq(){var R=DV.run,q=R.list[R.i],a=R.ans[q.id],L='ABCDE',h='';
h+='<div class="row" style="margin-bottom:10px"><button class="qzch" onclick="cf(\'Test to\\\'xtatilsinmi?\',function(y){if(y){clearInterval(DV.tm);dvgo(\'home\');dvl()}})">✕</button><b>'+(R.mode==='ticket'?R.ref+'-bilet · ':'')+'Savol '+(R.i+1)+'/'+R.list.length+'</b>'+(R.mode==='exam'?'<span class="tag">⏱ <span id="dvtm">'+Math.floor(R.lim/60)+':00</span> · ❌ '+R.bad+'/'+R.err+'</span>':'<span class="sub">✅ '+R.ok+' · ❌ '+R.bad+'</span>')+'</div>';
h+='<div style="display:flex;gap:3px;margin-bottom:12px">'+R.list.map(function(x,i){var s=R.ans[x.id];return '<div style="flex:1;height:5px;border-radius:3px;background:'+(s==null?(i===R.i?'var(--ac)':'var(--in)'):(s===x.c?'var(--g)':'var(--r)'))+'"></div>'}).join('')+'</div>';
h+='<div class="card">'+(q.img?'<img src="?pvi='+encodeURIComponent(q.img)+'" style="display:block;max-width:100%;max-height:200px;width:auto;margin:0 auto 12px;object-fit:contain;border-radius:12px;background:#fff" alt="" onerror="this.remove()">':'')+'<div style="font-weight:700;font-size:17px;line-height:1.4">'+esc(q.q)+'</div></div>';
h+=q.o.map(function(o,k){var st='';if(a!=null){if(k===q.c)st='background:#34c75926;border-color:var(--g)';else if(k===a)st='background:#ff3b3022;border-color:var(--r)'}return '<button onclick="dvans('+k+')" style="display:flex;gap:10px;align-items:flex-start;width:100%;text-align:left;border:1.5px solid var(--ln);background:var(--cd);color:var(--tx);border-radius:14px;padding:12px 14px;margin:0 0 8px;font-size:15px;cursor:pointer;'+st+'"><b style="flex:none;width:24px;height:24px;border-radius:12px;background:var(--in);display:inline-flex;align-items:center;justify-content:center;font-size:13px">'+L.charAt(k)+'</b><span>'+esc(o)+'</span></button>'}).join('');
if(a!=null&&q.note)h+='<div class="card" style="background:var(--soft)"><b>💡 Izoh</b><div style="margin-top:4px;font-size:14px">'+esc(q.note)+'</div></div>';
h+='<div style="display:flex;gap:8px"><button class="btn s" style="flex:none;width:auto" onclick="dvfav()">'+(q.fav?'⭐':'☆')+'</button>'+(R.i>0?'<button class="btn s" style="flex:none;width:auto" onclick="DV.run.i--;dvq()">‹</button>':'')+'<button class="btn" style="flex:1"'+(a==null?' disabled':'')+' onclick="dvnext()">'+(R.i<R.list.length-1?'Keyingisi ›':'Natijani ko\'rish')+'</button></div>';
$('dvb').innerHTML=h}
function dvans(k){var R=DV.run,q=R.list[R.i];if(R.ans[q.id]!=null)return;R.ans[q.id]=k;if(k===q.c)R.ok++;else R.bad++;api('pv_ans',{id:q.id,o:k});try{tg.HapticFeedback.notificationOccurred(k===q.c?'success':'error')}catch(e){}dvq();if(R.mode==='exam'&&R.bad>R.err)setTimeout(function(){toast('❌ Xatolar '+R.err+' tadan oshdi — imtihon tugadi');dvfin()},900)}
function dvnext(){var R=DV.run;if(R.i<R.list.length-1){R.i++;dvq();window.scrollTo(0,0)}else dvfin()}
function dvfav(){var q=DV.run.list[DV.run.i];q.fav=q.fav?0:1;api('pv_fav',{id:q.id,on:q.fav});dvq();toast(q.fav?'⭐ Saqlandi':'Olib tashlandi')}
function dvfin(){var R=DV.run;if(R.end)return;R.end=1;clearInterval(DV.tm);R.secs=Math.floor((Date.now()-R.t0)/1000);var n=R.mode==='exam'?R.list.length:Object.keys(R.ans).length;api('pv_done',{kind:R.mode,ref:R.ref,total:n,correct:R.ok,secs:R.secs,timeout:R.timeout?1:0}).then(function(j){R.passed=j.ok?j.passed:0;DV.v='res';dvres();dvl()})}
function dvres(){var R=DV.run,ex=R.mode==='exam'||R.mode==='ticket',W=R.list.filter(function(q){return R.ans[q.id]!=null&&R.ans[q.id]!==q.c}),h='<div class="card" style="text-align:center"><div style="font-size:54px">'+(ex?(R.passed?'🎉':'😔'):'📊')+'</div><b style="font-size:22px">'+(ex?(R.passed?'Tabriklaymiz, o\'tdingiz!':(R.timeout?'Vaqt tugadi':'Afsus, o\'tmadingiz')):'Natija')+'</b><div style="font-size:30px;font-weight:800;margin:8px 0">'+R.ok+' / '+(R.mode==='exam'?R.list.length:Object.keys(R.ans).length)+'</div><div class="sub">⏱ '+Math.floor(R.secs/60)+' daq '+R.secs%60+' son'+(ex?' · '+R.err+' tagacha xato mumkin':'')+'</div></div>';
if(W.length)h+='<div class="card"><b>❌ Xato javoblar</b>'+W.map(function(q){return '<div style="padding:8px 0;border-top:1px solid var(--ln);margin-top:6px"><div style="font-weight:600;font-size:14px">'+esc(q.q)+'</div><div class="sub" style="color:var(--r)">Siz: '+esc(q.o[R.ans[q.id]])+'</div><div class="sub" style="color:var(--g)">To\'g\'ri: '+esc(q.o[q.c])+'</div>'+(q.note?'<div class="sub">💡 '+esc(q.note)+'</div>':'')+'</div>'}).join('')+'</div>';
h+='<div style="display:grid;gap:8px"><button class="btn" onclick="dvstart(\''+R.mode+'\','+R.ref+')">🔁 Qayta ishlash</button>'+(W.length?'<button class="btn s" onclick="dvstart(\'mist\',0)">Xatolarim ustida ishlash</button>':'')+'<button class="btn s" onclick="dvgo(\'home\')">‹ Prava bosh sahifasi</button></div>';$('dvb').innerHTML=h}
/* ---- admin ---- */
function dvaq(p){var F=DV.af;F.p=p||0;api('pv_adm_list',{ticket:F.t,topic:F.tp,s:F.s,p:F.p}).then(function(j){if(j.ok){DV.al=j;if(DV.v==='adm')dvr()}})}
function dvadm(){var j=DV.d,A=DV.al,F=DV.af,c=j.cfg,h='<button class="bkb" onclick="dvgo(\'home\')">‹ Prava</button><h1 style="font-size:22px">🛠 Prava — boshqarish</h1>';
h+='<div class="card"><b>📦 Savollar bazasi: '+j.total+' ta'+(A?' · rasmlar: '+A.imgs:'')+'</b><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px"><button class="btn" onclick="dved(0)">➕ Savol</button><button class="btn" onclick="DV.ai={list:null};dvair()">🤖 YHQ matnidan</button><label class="btn s" style="cursor:pointer;text-align:center">📥 CSV import<input type="file" accept=".csv,text/csv,text/plain" style="display:none" onchange="dvimp(this)"></label><label class="btn s" style="cursor:pointer;text-align:center">🖼 Rasmlarni yuklash<input type="file" accept="image/*" multiple style="display:none" onchange="dvimgs(this)"></label><button class="btn s" onclick="api(\'pv_adm_tpl\').then(function(k){if(k.ok)toast(\'📄 Namuna botga yuborildi\')})">📄 Namuna CSV</button><button class="btn s" onclick="dvtk()">🎫 Biletlar tuzish</button><button class="btn s" onclick="dvzero()">🗑 Hammasini 0 ga tushirish</button><button class="btn s" onclick="dvseed()">♻️ Papkadan boshidan yuklash</button></div>'+(j.demo?'<button class="btn s" style="margin-top:8px" onclick="cf(\'Namuna savollar o\\\'chirilsinmi?\',function(y){if(y)api(\'pv_adm_demo\').then(function(k){if(k.ok){toast(k.n+\' ta o\\\'chirildi\');dvl();dvaq(0)}})})">🗑 '+j.demo+' ta namuna savolni o\'chirish</button>':'')+'<p class="sub" style="margin:8px 0 0">CSV: bilet; raqam; mavzu; savol; variantlar (| bilan); to\'g\'ri variant raqami (1 dan); izoh; rasm fayl nomi. Rasmlarni shu nomlar bilan yuklang.</p><div id="dvf"></div></div>';
h+='<div class="card"><b>⚙️ Imtihon qoidasi</b><div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:8px"><label class="sub">Savollar<input id="dc_n" type="number" value="'+c.n+'"></label><label class="sub">Daqiqa<input id="dc_m" type="number" value="'+c.min+'"></label><label class="sub">Ruxsat xato<input id="dc_e" type="number" value="'+c.err+'"></label></div><button class="btn s" onclick="api(\'pv_adm_cfg\',{n:+$(\'dc_n\').value,min:+$(\'dc_m\').value,err:+$(\'dc_e\').value}).then(function(k){if(k.ok){DV.d.cfg=k.cfg;toast(\'Saqlandi ✅\')}})">💾 Saqlash</button><p class="sub" style="margin:6px 0 0">Rasmiy: 20 savol, 25 daqiqa, 18 ta to\'g\'ri (2 tagacha xato).</p></div>';
if(!A)return h+'<div class="sk"></div>';
h+='<div class="card"><b>📚 Mavzular</b>'+A.topics.map(function(t){return '<div class="row" style="padding:6px 0;border-top:1px solid var(--ln);margin-top:6px"><span style="font-size:14px">'+esc(t.title)+'</span><span style="flex:none"><button class="qzch" onclick="dvtp('+t.id+')">✏️</button> <button class="qzch" onclick="dvtpd('+t.id+')">🗑</button></span></div>'}).join('')+'<button class="btn s" style="margin-top:8px" onclick="dvtp(0)">➕ Mavzu qo\'shish</button></div>';
var mx=0;(DV.d.tickets||[]).forEach(function(t){mx=Math.max(mx,t.t)});
h+='<div class="card"><div class="row"><b>📋 Savollar</b><span class="sub">'+A.n+' ta</span></div><div style="display:flex;gap:8px;margin-top:8px"><select style="flex:1;min-width:0" onchange="DV.af.t=+this.value;dvaq(0)"><option value="-1">Barcha biletlar</option><option value="0"'+(F.t===0?' selected':'')+'>Biletsiz</option>'+Array.from({length:mx},function(_,i){return '<option value="'+(i+1)+'"'+(F.t===i+1?' selected':'')+'>'+(i+1)+'-bilet</option>'}).join('')+'</select><select style="flex:1;min-width:0" onchange="DV.af.tp=+this.value;dvaq(0)"><option value="0">Barcha mavzular</option>'+A.topics.map(function(t){return '<option value="'+t.id+'"'+(F.tp==t.id?' selected':'')+'>'+esc(t.title)+'</option>'}).join('')+'</select></div><input placeholder="🔍 Qidirish..." value="'+esc(F.s)+'" onchange="DV.af.s=this.value.trim();dvaq(0)">'
+A.rows.map(function(x){var o=JSON.parse(x.opts);return '<div style="padding:10px 0;border-top:1px solid var(--ln)"><div class="row"><span class="sub">#'+x.id+(+x.ticket?' · '+x.ticket+'-bilet '+x.num+'-savol':' · biletsiz')+(+x.demo?' · namuna':'')+(x.img?' · 🖼':'')+'</span><span style="flex:none"><button class="qzch" onclick="dved('+x.id+')">✏️</button> <button class="qzch" onclick="dvdel('+x.id+')">🗑</button></span></div><div style="font-weight:600;margin:4px 0">'+esc(x.question)+'</div>'+o.map(function(v,k){return '<div class="sub" style="'+(k==x.correct?'color:var(--g);font-weight:600':'')+'">'+'ABCDE'.charAt(k)+') '+esc(v)+'</div>'}).join('')+'</div>'}).join('')
+(A.n>20?'<div class="row" style="margin-top:10px"><button class="btn s" style="width:auto"'+(A.p?'':' disabled')+' onclick="dvaq('+(A.p-1)+')">‹</button><span class="sub">'+(A.p+1)+' / '+Math.ceil(A.n/20)+'</span><button class="btn s" style="width:auto"'+((A.p+1)*20<A.n?'':' disabled')+' onclick="dvaq('+(A.p+1)+')">›</button></div>':'')+'</div>';return h}
function dved(id){var A=DV.al;if(!A)return;var x=id?A.rows.filter(function(r){return +r.id===id})[0]:{ticket:0,num:0,topic_id:A.topics.length?A.topics[0].id:0,question:'',img:'',opts:'["",""," "]',correct:0,note:''};DV.ed={id:id,img:x.img,o:JSON.parse(x.opts).map(function(s){return String(s).trim()}),c:+x.correct};if(DV.ed.o.length<2)DV.ed.o=['',''];DV.edx=x;dvedr()}
function dvedr(){var E=DV.ed,x=DV.edx,A=DV.al;$('dvf').innerHTML='<div style="margin-top:12px;padding:12px;border-radius:14px;background:var(--in)"><b>'+(E.id?'✏️ Tahrirlash':'➕ Yangi savol')+'</b><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px"><label class="sub">Bilet (0 — biletsiz)<input id="de_t" type="number" value="'+x.ticket+'"></label><label class="sub">Savol raqami<input id="de_n" type="number" value="'+x.num+'"></label></div><select id="de_tp">'+A.topics.map(function(t){return '<option value="'+t.id+'"'+(t.id==x.topic_id?' selected':'')+'>'+esc(t.title)+'</option>'}).join('')+'</select><textarea id="de_q" rows="3" maxlength="1000" placeholder="Savol matni">'+esc(x.question)+'</textarea>'+(E.img?'<img src="?pvi='+encodeURIComponent(E.img)+'" style="width:100%;border-radius:10px;margin-bottom:6px"><button class="qzch" onclick="DV.ed.img=\'\';dvedr()">🗑 Rasmni olib tashlash</button>':'<label class="btn s" style="cursor:pointer;text-align:center;margin-bottom:8px">🖼 Rasm qo\'shish (ixtiyoriy)<input type="file" accept="image/*" style="display:none" onchange="dvimg1(this)"></label>')
+'<p class="sub" style="margin:8px 0 4px">Variantlar — to\'g\'risini belgilang (2–5 ta):</p>'+E.o.map(function(o,k){return '<div style="display:flex;gap:8px;align-items:center"><input type="radio" name="de_c" style="flex:none;width:22px;height:22px;margin:0 0 10px"'+(k===E.c?' checked':'')+' onclick="DV.ed.c='+k+'"><input id="de_o'+k+'" value="'+esc(o)+'" placeholder="'+'ABCDE'.charAt(k)+') variant" oninput="DV.ed.o['+k+']=this.value" style="flex:1;min-width:0">'+(E.o.length>2?'<button class="qzch" style="margin-bottom:10px" onclick="DV.ed.o.splice('+k+',1);if(DV.ed.c>='+k+'&&DV.ed.c>0)DV.ed.c--;dvedr()">✕</button>':'')+'</div>'}).join('')+(E.o.length<5?'<button class="qzch" onclick="DV.ed.o.push(\'\');dvedr()">➕ Variant</button>':'')
+'<input id="de_note" maxlength="1000" placeholder="💡 Izoh (masalan: YHQ 10.1-band)" value="'+esc(x.note||'')+'" style="margin-top:8px"><div style="display:flex;gap:8px"><button class="btn" style="flex:1" onclick="dvsv()">💾 Saqlash</button><button class="btn s" style="flex:none;width:auto" onclick="$(\'dvf\').innerHTML=\'\'">Bekor</button></div></div>';
['t','n','q','note'].forEach(function(k){var e=$('de_'+k);if(e)e.oninput=function(){var m={t:'ticket',n:'num',q:'question',note:'note'};DV.edx[m[k]]=this.value}});$('de_tp').onchange=function(){DV.edx.topic_id=this.value}}
function dvimg1(i){var f=i.files[0];if(!f)return;imgfit(f,900,900,false,function(d){api('pv_adm_img',{data:d}).then(function(j){if(j.ok){DV.ed.img=j.name;dvedr()}})})}
function dvsv(){var E=DV.ed,x=DV.edx;api('pv_adm_save',{id:E.id,ticket:+$('de_t').value,num:+$('de_n').value,topic_id:+$('de_tp').value,question:$('de_q').value,img:E.img,opts:E.o,correct:E.c,note:$('de_note').value}).then(function(j){if(j.ok){toast('Saqlandi ✅');$('dvf').innerHTML='';dvl();dvaq(DV.af.p)}})}
function dvdel(id){cf('Savol o\'chirilsinmi?',function(y){if(y)api('pv_adm_del',{id:id}).then(function(j){if(j.ok){dvl();dvaq(DV.af.p)}})})}
function dvtp(id){var t=id?DV.al.topics.filter(function(x){return +x.id===id})[0].title:'';var nm=prompt('Mavzu nomi',t);if(nm==null||!nm.trim())return;api('pv_adm_topic',{id:id,title:nm.trim()}).then(function(j){if(j.ok){DV.al.topics=j.topics;dvl();dvr()}})}
function dvtpd(id){cf('Mavzu o\'chirilsinmi?',function(y){if(y)api('pv_adm_topic',{id:id,del:1}).then(function(j){if(j.ok){DV.al.topics=j.topics;dvl();dvr()}})})}
function dvtk(){cf('Biletsiz savollardan 20 tadan biletlar tuzilsinmi? Mavzular biletlar bo\'ylab teng taqsimlanadi.',function(y){if(y)api('pv_adm_tickets',{per:20}).then(function(j){if(j.ok){toast(j.tickets+' ta bilet tuzildi ✅');dvl();dvaq(0)}})})}
function dvzero(){cf('DIQQAT: barcha Prava savollari, biletlar, rasmlar va foydalanuvchilar natijalari o\'chiriladi. Davom etilsinmi?',function(y){if(!y)return;cf('Aniq 0 ga tushirilsinmi? Buni qaytarib bo\'lmaydi.',function(y2){if(!y2)return;api('pv_adm_reset').then(function(j){if(!j.ok)return;toast('0 ga tushirildi: '+j.n.savol+' savol, '+j.n.rasm+' rasm o\'chirildi');dvl();dvaq(0)})})})}
function dvseed(){cf('Avval hammasi 0 ga tushiriladi, so\'ng serverdagi pv_seed papkasidan savollar va rasmlar qayta yuklanadi. Davom etilsinmi?',function(y){if(!y)return;var e=$('dvf');if(e)e.innerHTML='<p class="sub" style="margin-top:10px">⏳ Yuklanmoqda, kuting…</p>';api('pv_adm_seed',{reset:1}).then(function(j){if(!j.ok){if(e)e.innerHTML='';return}dvl();dvaq(0);setTimeout(function(){var e=$('dvf');if(e)e.innerHTML='<div style="margin-top:12px;padding:12px;border-radius:12px;background:var(--in)"><b>♻️ Boshidan yuklandi: '+j.added+' ta savol, '+j.imgs+' ta rasm</b>'+(j.missing_n?'<p class="sub" style="margin:4px 0 0;color:var(--r)">🖼 '+j.missing_n+' ta rasm topilmadi: '+esc(j.missing.join(', '))+'</p>':'<p class="sub" style="margin:4px 0 0">Hamma rasm joyida ✅</p>')+(j.bad?'<p class="sub" style="margin:4px 0 0">⚠️ '+j.bad+' ta rasm fayli yaroqsiz</p>':'')+j.errors.map(function(e){return '<p class="sub" style="margin:4px 0 0">⚠️ '+esc(e)+'</p>'}).join('')+'</div>'},500)})})}
function dvimp(inp){var f=inp.files[0];if(!f)return;var r=new FileReader();r.onload=function(){api('pv_adm_import',{csv:r.result}).then(function(j){if(!j.ok)return;dvl();dvaq(0);setTimeout(function(){var e=$('dvf');if(e)e.innerHTML='<div style="margin-top:12px;padding:12px;border-radius:12px;background:var(--in)"><b>📥 '+j.added+' ta qo\'shildi, '+j.updated+' ta yangilandi, '+j.dup+' ta takror</b>'+(j.missing_n?'<p class="sub" style="margin:4px 0 0;color:var(--r)">🖼 '+j.missing_n+' ta rasm hali yuklanmagan: '+esc(j.missing.join(', '))+'</p>':'')+j.errors.map(function(e){return '<p class="sub" style="margin:4px 0 0">⚠️ '+esc(e)+'</p>'}).join('')+'</div>'},500)})};r.readAsText(f,'UTF-8');inp.value=''}
function dvimgs(inp){var F=[].slice.call(inp.files),n=0,i=0;if(!F.length)return;var e=$('dvf');var one=function(){if(i>=F.length){e.innerHTML='<p class="sub" style="margin-top:10px">🖼 '+n+' ta rasm yuklandi ✅</p>';dvaq(DV.af.p);return}var f=F[i++];e.innerHTML='<p class="sub" style="margin-top:10px">⏳ Yuklanmoqda: '+i+' / '+F.length+'</p>';imgfit(f,900,900,false,function(d){api('pv_adm_img',{data:d,name:f.name}).then(function(j){if(j.ok)n++;one()})})};one();inp.value=''}
function dvair(){var A=DV.ai,T=DV.al?DV.al.topics:[],e=$('dvf');if(!e)return;var h='<div style="margin-top:12px;padding:12px;border-radius:14px;background:var(--in)"><b>🤖 YHQ matnidan savollar</b><p class="sub" style="margin:4px 0 8px">YHQ (lex.uz) dan bitta bo\'limni nusxalab qo\'ying. AI faqat shu matn asosida savol tuzadi va izohga band raqamini yozadi. Har birini tekshirib saqlang.</p><select id="dai_t">'+T.map(function(t){return '<option value="'+t.id+'"'+(A.t==t.id?' selected':'')+'>'+esc(t.title)+'</option>'}).join('')+'</select><textarea id="dai_x" rows="6" placeholder="10. Harakat tezligi&#10;10.1. Haydovchi transport vositasini ... ">'+esc(A.x||'')+'</textarea><select id="dai_n">'+[10,15,20,30].map(function(n){return '<option'+(n===(A.n||15)?' selected':'')+'>'+n+'</option>'}).join('')+'</select><button class="btn"'+(A.busy?' disabled':'')+' onclick="dvaigo()">'+(A.busy?'⏳ Tayyorlanmoqda (2 daqiqagacha)...':'✨ Savollar tuzish')+'</button>';
if(A.list)h+=A.list.map(function(x,i){return '<label style="display:flex;gap:10px;align-items:flex-start;padding:8px 0;border-top:1px solid var(--ln)"><input type="checkbox" id="dai_c'+i+'" checked style="flex:none;margin-top:2px"><div style="min-width:0"><b style="font-size:14px">'+esc(x.question)+'</b>'+x.opts.map(function(o,k){return '<div class="sub" style="'+(k===x.correct?'color:var(--g);font-weight:600':'')+'">'+'ABCDE'.charAt(k)+') '+esc(o)+'</div>'}).join('')+(x.note?'<div class="sub">💡 '+esc(x.note)+'</div>':'')+'</div></label>'}).join('')+(A.list.length?'<button class="btn" onclick="dvaisv()">💾 Belgilanganlarni saqlash</button>':'<p class="sub">Matndan savol chiqmadi.</p>');
e.innerHTML=h+'</div>'}
function dvaigo(){var A=DV.ai;A.t=+$('dai_t').value;A.x=$('dai_x').value;A.n=+$('dai_n').value;A.busy=1;A.list=null;dvair();api('pv_adm_ai',{topic:A.t,text:A.x,n:A.n}).then(function(j){A.busy=0;if(j.ok)A.list=j.list;dvair()})}
function dvaisv(){var A=DV.ai,L=A.list.filter(function(x,i){return $('dai_c'+i).checked});if(!L.length){toast('Hech narsa belgilanmagan');return}api('pv_adm_ai_save',{topic:A.t,list:L}).then(function(j){if(j.ok){toast(j.added+' ta savol saqlandi ✅');DV.ai.list=null;DV.ai.x='';dvair();dvl();dvaq(0)}})}
/* ---- SAVOL-JAVOB: bitta sahifa — Sozlash (bo'limni bosqichma-bosqich tanlash), Reyting, Savollar bazasi (admin) ---- */
var SJ={c:0,d:null,tab:'set',cat:null,src:'qz',pvt:0,want:null,cc:null,m:'all',rc:0,bf:'',bs:'',bp:0,bl:null,ed:0,ai:null,ain:10,ail:2,tm:null};
function qzn(p){var n={k:SJ.d.tree},T=[];if(p){var a=p.split('/');for(var i=0;i<a.length;i++){if(!n.k||!n.k[a[i]])return null;n=n.k[a[i]];T.push(n.t)}}return {n:n,T:T}}
function qzc(p){var C=SJ.d.counts||{},s=0;for(var k in C)if(!p||k===p||k.indexOf(p+'/')===0)s+=+C[k];return s}
function qzlab(p){var x=qzn(p);return x&&x.T.length?x.T.join(' › '):'Barcha bo\'limlar aralash'}
function qzleaf(p){var x=qzn(p);return !!(p&&x&&!x.n.k)}
function sjl(c){if(c!=null)SJ.c=c;if(!SJ.d)$('sjb').innerHTML='<div class="sk"></div><div class="sk"></div>';api('qz_home',SJ.c?{chat:SJ.c}:{}).then(function(j){if(!j.ok)return;var my=j.groups.filter(function(g){return g.manage});if(my.length&&!my.some(function(g){return g.id===j.chat})){SJ.c=my[0].id;return sjl()}SJ.d=j;SJ.c=j.chat;if(SJ.wantTab){SJ.tab=j.admin?SJ.wantTab:'rank';SJ.wantTab=null;if(SJ.tab==='bank'&&!SJ.bl)sjq(0)}if(SJ.cc!==j.chat){SJ.cc=j.chat;SJ.cat=j.cfg?j.cfg.cat:'';SJ.src=j.cfg&&j.cfg.src==='pv'?'pv':'qz';SJ.pvt=j.cfg?(+j.cfg.pvt||0):0}if(SJ.want){SJ.src=SJ.want;SJ.want=null}if(!my.length&&SJ.tab==='set')SJ.tab=(j.admin&&ADMV)?'bank':'rank';SJ.d.off=j.now-Math.floor(Date.now()/1000);sjr()})}
function sjtab(t){SJ.tab=t;sjr();if(t==='rank')sjrk(SJ.m);if(t==='bank'&&!SJ.bl)sjq(0)}
function sjr(){var j=SJ.d,my=j.groups.filter(function(g){return g.manage}),T=[];if(my.length)T.push(['set','⚙️ Sozlash']);T.push(['rank','🏆 Reyting']);if(j.admin&&ADMV)T.push(['bank','🗂 Savollar']);
var h='<div style="display:flex;gap:6px;margin:-4px 0 12px">'+T.map(function(t){return '<button class="btn'+(SJ.tab===t[0]?'':' s')+'" style="flex:1;padding:10px 4px;font-size:14px" onclick="sjtab(\''+t[0]+'\')">'+t[1]+'</button>'}).join('')+'</div>';
if(SJ.tab==='set')h+=my.length?sjset(my):'<div class="card sub">Testlar o\'zingiz qo\'shgan kanal va guruhlarda o\'ynaladi. Avval «Kanal qo\'shish» yoki «Guruh qo\'shish» orqali qo\'shing (bot administrator bo\'lsin).</div>';
if(SJ.tab==='rank')h+=sjrank();if(SJ.tab==='bank')h+='<div id="sjbank"></div>';
$('sjb').innerHTML=h;if(SJ.tab==='bank')sjbank();sjtick()}
/* bo'lim tanlash: yuqorida yo'l (bosib orqaga qaytiladi), pastda keyingi bosqich variantlari va savollar soni */
function pk(t,cur,leaf){var x=qzn(cur)||qzn(''),a=cur?cur.split('/'):[],n=x.n,h='';
if(a.length){h+='<div style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-bottom:10px"><button class="qzch" onclick="pks(\''+t+'\',\'\')">‹ Bo\'limlar</button>';for(var i=0;i<a.length;i++){var p=a.slice(0,i+1).join('/');h+='<span class="sub">›</span><button class="qzch'+(i===a.length-1?' on':'')+'" onclick="pks(\''+t+'\',\''+p+'\')">'+esc(qzn(p).n.t)+'</button>'}h+='</div>'}
if(n.k){var K=Object.keys(n.k);
if(!a.length)h+='<div style="display:grid;gap:8px">'+(leaf?'':'<div class="qzcd'+(cur===''?' on':'')+'" onclick="pks(\''+t+'\',\'\',1)"><b>🌐 Hamma bo\'limlar aralash</b><span>Barcha bo\'lim va fanlardan tasodifiy savollar</span><i>'+qzc('')+' ta savol</i></div>')+K.map(function(k){return '<div class="qzcd" onclick="pks(\''+t+'\',\''+k+'\')"><b>'+esc(n.k[k].t)+'</b><span>'+esc(n.k[k].d||'')+'</span><i>'+qzc(k)+' ta savol</i></div>'}).join('')+'</div>';
else h+='<p class="sub" style="margin:0 0 6px">'+(a.length===1&&a[0]==='maktab'?'Sinfni tanlang':'Keyingisini tanlang')+(leaf?':':' (yoki shu bo\'limning hammasi aralash qoladi):')+'</p><div style="display:grid;grid-template-columns:repeat('+(a[0]==='maktab'&&a.length===1?4:2)+',minmax(0,1fr));gap:6px">'+K.map(function(k){var p=cur+'/'+k,c=qzc(p);return '<button class="qzch2" onclick="pks(\''+t+'\',\''+p+'\')"><b>'+esc(n.k[k].t)+'</b><small>'+(c?c+' ta':'—')+'</small></button>'}).join('')+'</div>'}
if(cur!==''||!leaf){var c=qzc(cur);h+='<div class="qzsum">'+(leaf&&!qzleaf(cur)?'👆 Fanni tanlang':'✅ '+esc(qzlab(cur))+'<br><span class="sub">'+(c?c+' ta savol':'⚠️ Bu bo\'limda hali savol yo\'q')+'</span>')+'</div>'}
return h}
function pks(t,p){if(t==='set')SJ.cat=p;if(t==='bank'){SJ.bf=p;SJ.ed=0;SJ.ai=null;sjq(0);return}sjr()}
function sjleft(){var c=SJ.d&&SJ.d.cur;return c?Math.max(0,c.ends-(Math.floor(Date.now()/1000)+SJ.d.off)):0}
function sjtick(){clearInterval(SJ.tm);if(!SJ.d||!SJ.d.cur)return;SJ.tm=setInterval(function(){var e=$('sjt');if(!e||!$('p-psj').classList.contains('on')){clearInterval(SJ.tm);return}var s=sjleft();e.textContent=s+' soniya';if(s<=0){clearInterval(SJ.tm);setTimeout(function(){if($('p-psj').classList.contains('on'))sjl()},4000)}},1000)}
function sjset(my){var j=SJ.d,c=j.cfg,h='';
h+=my.length>1?'<select onchange="sjl(+this.value)" style="margin-bottom:12px">'+my.map(function(g){return '<option value="'+g.id+'"'+(g.id===j.chat?' selected':'')+'>'+(g.on?'🟢 ':'⚪ ')+(g.ch?'📢 ':'👥 ')+esc(g.name)+'</option>'}).join('')+'</select>':'<p class="sub" style="margin:-4px 2px 12px">'+(my[0].ch?'📢 ':'👥 ')+esc(my[0].name)+'</p>';
h+='<div class="card"><div class="row" style="cursor:pointer" onclick="sjtg()"><div style="display:flex;align-items:center;gap:10px">'+ck(c.on)+'<div><b>Avtomatik test</b><div class="sub">'+(c.on?'Savollar navbat bilan yuborilmoqda':'O\'chirilgan')+'</div></div></div></div>'
+(c.on&&c.count?'<p class="sub" style="margin:8px 0 0">📊 Berilgan savollar: <b>'+c.done+' / '+c.count+'</b> — oxirida TOP-10 g\'oliblar e\'lon qilinadi</p>':'')+(c.on?'<p class="sub" style="margin:4px 0 0">📚 '+esc(c.label)+'</p>':'')
+(j.cur?'<div style="margin-top:12px;padding:12px;border-radius:14px;background:var(--in)"><div class="sub">📚 '+esc(j.cur.subject)+' · +'+j.cur.points+' ochko</div><div style="font-weight:700;margin:6px 0 10px">❓ '+esc(j.cur.question)+'</div>'+(j.cur.opts?'<div style="display:grid;gap:6px">'+j.cur.opts.map(function(o,i){return '<div style="padding:9px 12px;border-radius:12px;background:var(--cd);font-weight:600">'+'ABCD'.charAt(i)+') '+esc(o)+'</div>'}).join('')+'</div>':'')+'<div class="row" style="margin-top:8px"><span class="sub">Hozir berilmoqda</span><b>⏳ <span id="sjt">'+sjleft()+' soniya</span></b></div></div>':'')
+(c.err?'<p class="sub" style="color:var(--r);margin:8px 0 0">⚠️ '+esc(c.err)+'</p>':'')+'</div>';
h+='<div class="card"><b>🎯 Test turi</b><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px">'+[['qz','🧩','Savol-javob','Maktab, litsey, universitet…'],['pv','🚗','Prava testi','YHQ · haydovchilik imtihoni']].map(function(x){return '<div class="qzcd'+(SJ.src===x[0]?' on':'')+'" onclick="SJ.src=\''+x[0]+'\';sjr()"><b>'+x[1]+' '+x[2]+'</b><span>'+x[3]+'</span></div>'}).join('')+'</div>'+(SJ.src==='pv'?'<p class="sub" style="margin:10px 0 0">👥 Guruhda istalgan a\'zo <b>/prava</b> yozib bitta savol so\'rashi mumkin. Ochkolar Testlar reytingiga qo\'shiladi.</p>':'')+'</div>';
h+=SJ.src==='pv'?pvpick():'<div class="card"><b>1️⃣ Bo\'limni tanlang</b><div style="margin-top:10px">'+pk('set',SJ.cat,false)+'</div></div>';
h+='<div class="card"><b>2️⃣ Test sozlamalari</b><p class="sub" style="margin:6px 0 10px">Har bir savolda 4 ta variant: A, B, C, D. To\'g\'ri javob bergan har bir a\'zo ochko oladi.</p>'
+'<p class="sub" style="margin:0 0 4px">🔢 Bir o\'yindagi savollar soni (10–30)</p><input id="sj_cnt" type="number" inputmode="numeric" min="10" max="30" value="'+(c.count||10)+'">'
+'<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px"><label class="sub">Oraliq, daq<input id="sj_iv" type="number" inputmode="numeric" min="1" max="1440" value="'+c.interval+'"></label><label class="sub">Javob vaqti, son<input id="sj_sec" type="number" inputmode="numeric" min="15" max="600" value="'+c.sec+'"></label><label class="sub">Ochko<input id="sj_pts" type="number" inputmode="numeric" min="1" max="1000" value="'+c.points+'"></label></div>'
+(c.ch?'<p class="sub" style="margin:8px 0 0">ℹ️ Kanalda ovozlar anonim — obunachilar javob beradi, lekin ochko hisoblanmaydi. Reyting uchun guruhda o\'ynang.</p>':'')
+'<div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap"><button class="btn" style="flex:1" onclick="sjs()">💾 Saqlash</button><button class="btn s" style="flex:none;width:auto" onclick="sjsend()">📨 Hozir savol</button><button class="btn s" style="flex:none;width:auto" onclick="sjdg()">🔍 Tekshirish</button></div><div id="sjdgr"></div></div>';
return h}
function pvpick(){var j=SJ.d,T=(j.pv||[]).filter(function(t){return +t.n}),h='<div class="card"><b>1️⃣ Prava mavzusini tanlang</b><div style="display:grid;gap:8px;margin-top:10px"><div class="qzcd'+(!SJ.pvt?' on':'')+'" onclick="SJ.pvt=0;sjr()"><b>🌐 Hamma mavzular aralash</b><span>YHQ bo\'yicha tasodifiy savollar</span><i>'+nf(+j.pvn)+' ta savol</i></div>';
h+=T.map(function(t){return '<div class="qzcd'+(SJ.pvt===+t.id?' on':'')+'" onclick="SJ.pvt='+(+t.id)+';sjr()"><b>'+esc(t.title)+'</b><i>'+t.n+' ta savol</i></div>'}).join('');
if(!j.pvn)h+='<div class="sub">⚠️ Prava savollar bazasi hali bo\'sh — avval Prava bo\'limiga savollar yuklang.</div>';return h+'</div></div>'}
function sjs(on){var c=SJ.d.cfg,n=+$('sj_cnt').value;if(on==null)on=c.on;if(!(n>=10&&n<=30)){toast('Savollar soni 10 dan 30 gacha bo\'lsin');return}api('qz_set',{chat:SJ.c,on:on,src:SJ.src,pvt:SJ.pvt||0,cat:SJ.cat,interval:+$('sj_iv').value,sec:+$('sj_sec').value,points:+$('sj_pts').value,count:n}).then(function(j){if(j.ok){toast(on&&!c.on?'Yoqildi ✅ Birinchi savol 1 daqiqa ichida':(!on&&c.on?'O\'chirildi':'Saqlandi ✅'));sjl()}})}
function sjtg(){sjs(SJ.d.cfg.on?0:1)}
function sjsend(){api('qz_send',{chat:SJ.c}).then(function(j){if(j.ok){toast('Savol yuborildi ✅');sjl()}})}
function sjdg(){$('sjdgr').innerHTML='<div class="sk" style="margin-top:10px"></div>';api('qz_diag',{chat:SJ.c}).then(function(j){if(!j.ok){$('sjdgr').innerHTML='';return}var d=j.diag;$('sjdgr').innerHTML='<div style="margin-top:12px;padding:12px;border-radius:12px;background:var(--in)"><b>'+(d.ok?'✅ Hammasi joyida — test ishlaydi':'⚠️ Sozlash kerak')+'</b><p class="sub" style="margin:6px 0 0">Bot holati: '+esc(d.status||'—')+(d.admin?' (admin)':'')+'</p>'+d.tips.map(function(t){return '<p class="sub" style="margin:6px 0 0">• '+esc(t)+'</p>'}).join('')+'</div>'})}
function sjrank(){var j=SJ.d,m=j.me,h='<div class="card"><b>⭐ Mening natijalarim</b><div style="display:flex;gap:8px;margin-top:10px">'+[['ochko',m.total],['to\'g\'ri',m.correct],['qatnashgan',m.answered]].map(function(x){return '<div style="flex:1;padding:10px;border-radius:12px;background:var(--in);text-align:center"><b style="font-size:18px">'+x[1]+'</b><div class="sub" style="font-size:12px">'+x[0]+'</div></div>'}).join('')+'</div></div>';
h+='<div class="card"><b>🏆 Reyting</b><select style="margin-top:10px" onchange="SJ.rc=+this.value;sjrk(SJ.m)"><option value="0">🌐 Barcha guruhlar</option>'+j.groups.map(function(g){return '<option value="'+g.id+'"'+(g.id===SJ.rc?' selected':'')+'>'+(g.ch?'📢 ':'👥 ')+esc(g.name)+'</option>'}).join('')+'</select><div style="display:flex;gap:6px;overflow-x:auto;padding-bottom:4px">'+[['all','Umumiy'],['day','Bugun'],['week','Hafta'],['correct','To\'g\'ri javoblar']].map(function(t){return '<button class="qzch'+(SJ.m===t[0]?' on':'')+'" style="flex:none" onclick="sjrk(\''+t[0]+'\')">'+t[1]+'</button>'}).join('')+'</div><div id="sjrk"><div class="sk"></div></div></div>';return h}
function sjrows(R,mode){if(!R||!R.length)return '<p class="sub" style="margin:8px 0 0">Hozircha natija yo\'q.</p>';var md=['🥇','🥈','🥉'];return R.map(function(r,i){return '<div class="row" style="padding:9px 0;border-top:'+(i?'1px solid var(--ln)':'0')+'"><div style="display:flex;align-items:center;gap:10px;min-width:0"><span style="width:26px;text-align:center;font-weight:700">'+(md[i]||(i+1))+'</span><div style="min-width:0"><div style="font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+esc(r.name||'ID '+r.user_id)+'</div><div class="sub" style="font-size:12px">'+r.correct+' to\'g\'ri · '+r.answered+' javob</div></div></div><b style="white-space:nowrap">'+(+r.points)+' ochko</b></div>'}).join('')}
function sjrk(m){SJ.m=m;document.querySelectorAll('#sjb .qzch').forEach(function(b){var oc=b.getAttribute('onclick')||'';if(oc.indexOf('sjrk(')===0)b.classList.toggle('on',oc.indexOf("'"+m+"'")>0)});var e=$('sjrk');if(!e)return;e.innerHTML='<div class="sk"></div>';api('qz_rank',{chat:SJ.rc,mode:m}).then(function(j){if(j.ok&&$('sjrk'))$('sjrk').innerHTML=sjrows(j.rows,m)})}
/* ---- savollar bazasi (admin) ---- */
function sjq(p){SJ.bp=p||0;api('qz_q_list',{f:SJ.bf,s:SJ.bs,p:SJ.bp}).then(function(j){if(j.ok){SJ.bl=j;SJ.d.counts=j.counts;sjbank()}})}
function sjbank(){var e=$('sjbank');if(!e)return;if(!SJ.bl){e.innerHTML='<div class="sk"></div>';return}var j=SJ.bl,lf=qzleaf(SJ.bf),h='';
h+='<div class="card"><b>🗂 Bo\'lim</b><div style="margin-top:10px">'+pk('bank',SJ.bf,false)+'</div></div>';
h+='<div class="card"><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><button class="btn" onclick="sje(0)">➕ Savol qo\'shish</button><button class="btn" onclick="sjai()">🤖 AI bilan yaratish</button><label class="btn s" style="cursor:pointer;text-align:center">📥 CSV import<input type="file" accept=".csv,text/csv,text/plain" style="display:none" onchange="sjimp(this)"></label><button class="btn s" onclick="api(\'qz_tpl\').then(function(k){if(k.ok)toast(\'📄 Namuna va kodlar botga yuborildi\')})">📄 Namuna CSV</button></div><p class="sub" style="margin:8px 0 0">Savol qo\'shish va AI uchun bo\'limni fan darajasigacha tanlang'+(lf?' ✅':'')+'. CSV: bo\'lim; savol; to\'g\'ri javob; noto\'g\'ri variantlar (A|B|C); izoh.</p><div id="sjf"></div></div>';
h+='<div class="card"><div class="row"><b>📋 Savollar</b><span class="sub">'+j.n+' ta</span></div><input placeholder="🔍 Qidirish..." value="'+esc(SJ.bs)+'" onchange="SJ.bs=this.value.trim();sjq(0)" style="margin-top:8px">'
+(j.rows.length?j.rows.map(function(x){var o=String(x.opts||'').split('|').filter(Boolean);return '<div style="padding:10px 0;border-top:1px solid var(--ln);margin-top:8px"><div class="row"><span class="sub" style="min-width:0">#'+x.id+' · '+esc(x.label)+' · '+x.used+' marta</span><span style="white-space:nowrap;flex:none"><button class="qzch" onclick="sje('+x.id+')">✏️</button> <button class="qzch" onclick="sjd('+x.id+')">🗑</button></span></div><div style="margin:4px 0;font-weight:600">'+esc(x.question)+'</div><div class="sub" style="color:var(--g)">✅ '+esc(x.answer)+'</div>'+(o.length?'<div class="sub">❌ '+o.map(esc).join(' · ')+'</div>':'')+'</div>'}).join(''):'<p class="sub" style="margin:10px 0 0">Bu bo\'limda hali savol yo\'q.</p>')
+(j.n>20?'<div class="row" style="margin-top:10px"><button class="btn s" style="width:auto"'+(j.p?'':' disabled')+' onclick="sjq('+(j.p-1)+')">‹</button><span class="sub">'+(j.p+1)+' / '+Math.ceil(j.n/20)+'</span><button class="btn s" style="width:auto"'+((j.p+1)*20<j.n?'':' disabled')+' onclick="sjq('+(j.p+1)+')">›</button></div>':'')+'</div>';
e.innerHTML=h;if(SJ.ai)sjair()}
function sje(id){var x=id?SJ.bl.rows.filter(function(r){return +r.id===id})[0]:null,cat=x?x.cat:SJ.bf;if(!qzleaf(cat)){toast('Avval bo\'limni fan darajasigacha tanlang');return}SJ.ed=id;SJ.ai=null;x=x||{question:'',answer:'',opts:'',note:'',alts:'',level:1};SJ.ec=cat;var o=String(x.opts||'').split('|');
$('sjf').innerHTML='<div style="margin-top:12px;padding:12px;border-radius:14px;background:var(--in)"><b>'+(id?'✏️ Tahrirlash':'➕ Yangi savol')+'</b><div class="sub" style="margin:4px 0 8px">📚 '+esc(qzlab(cat))+'</div><textarea id="qe_q" rows="3" maxlength="300" placeholder="Savol matni">'+esc(x.question)+'</textarea><input id="qe_a" maxlength="60" placeholder="✅ To\'g\'ri javob" value="'+esc(x.answer)+'">'+[0,1,2].map(function(i){return '<input id="qe_o'+i+'" maxlength="100" placeholder="❌ Noto\'g\'ri variant '+(i+1)+'" value="'+esc(o[i]||'')+'">'}).join('')+'<input id="qe_n" maxlength="200" placeholder="💡 Izoh (ixtiyoriy) — javobdan keyin ko\'rsatiladi" value="'+esc(x.note||'')+'"><select id="qe_l">'+[1,2,3].map(function(l){return '<option value="'+l+'"'+(+x.level===l?' selected':'')+'>Qiyinlik: '+['oson','o\'rtacha','qiyin'][l-1]+'</option>'}).join('')+'</select><div style="display:flex;gap:8px"><button class="btn" style="flex:1" onclick="sjsv()">💾 Saqlash</button><button class="btn s" style="flex:none;width:auto" onclick="$(\'sjf\').innerHTML=\'\'">Bekor</button></div><p class="sub" style="margin:6px 0 0">Guruhda variantlar aralashtirilib A, B, C, D harflari bilan chiqadi.</p></div>';$('qe_q').focus()}
function sjsv(){var o=[0,1,2].map(function(i){return $('qe_o'+i).value.trim()}).filter(Boolean);if(o.length<3){toast('3 ta noto\'g\'ri variantni yozing');return}api('qz_q_save',{id:SJ.ed,cat:SJ.ec,question:$('qe_q').value,answer:$('qe_a').value,opts:o.join('|'),note:$('qe_n').value,level:+$('qe_l').value}).then(function(j){if(j.ok){toast('Saqlandi ✅');SJ.ed=0;sjq(SJ.bp)}})}
function sjd(id){cf('Savol o\'chirilsinmi?',function(y){if(!y)return;api('qz_q_del',{id:id}).then(function(j){if(j.ok){toast('O\'chirildi');sjq(SJ.bp)}})})}
function sjimp(inp){var f=inp.files[0];if(!f)return;if(f.size>3000000){toast('Fayl 3 MB dan katta');return}var r=new FileReader();r.onload=function(){api('qz_q_import',{csv:r.result}).then(function(j){if(!j.ok)return;toast('Qo\'shildi: '+j.added);sjq(0);setTimeout(function(){var e=$('sjf');if(e)e.innerHTML='<div style="margin-top:12px;padding:12px;border-radius:12px;background:var(--in)"><b>📥 '+j.added+' ta qo\'shildi, '+j.dup+' ta takror</b>'+j.errors.map(function(e){return '<p class="sub" style="margin:4px 0 0">⚠️ '+esc(e)+'</p>'}).join('')+'</div>'},400)})};r.readAsText(f,'UTF-8');inp.value=''}
function sjai(){if(!qzleaf(SJ.bf)){toast('Avval bo\'limni fan darajasigacha tanlang');return}SJ.ai={cat:SJ.bf,list:null,busy:0};sjair()}
function sjair(){var A=SJ.ai,e=$('sjf');if(!e)return;var h='<div style="margin-top:12px;padding:12px;border-radius:14px;background:var(--in)"><b>🤖 AI bilan savollar</b><div class="sub" style="margin:4px 0 8px">📚 '+esc(qzlab(A.cat))+'</div><div style="display:flex;gap:8px"><select id="ai_n" style="flex:1;min-width:0">'+[5,10,15,20].map(function(n){return '<option'+(n===SJ.ain?' selected':'')+'>'+n+'</option>'}).join('')+'</select><select id="ai_l" style="flex:1;min-width:0">'+[1,2,3].map(function(l){return '<option value="'+l+'"'+(l===SJ.ail?' selected':'')+'>'+['Oson','O\'rtacha','Qiyin'][l-1]+'</option>'}).join('')+'</select></div><button class="btn" '+(A.busy?'disabled':'')+' onclick="sjaigo()">'+(A.busy?'⏳ Tayyorlanmoqda (1 daqiqagacha)...':'✨ Savollarni yaratish')+'</button>';
if(A.list){h+='<p class="sub" style="margin:8px 0 4px">AI xato qilishi mumkin — har birini tekshiring va keraklilarini belgilang:</p>'+A.list.map(function(x,i){return '<label style="display:flex;gap:10px;align-items:flex-start;padding:8px 0;border-top:1px solid var(--ln)"><input type="checkbox" id="ai_c'+i+'"'+(x.dup?'':' checked')+' style="flex:none;margin-top:2px"><div style="min-width:0"><b style="font-size:14px">'+esc(x.question)+'</b><div class="sub" style="color:var(--g)">✅ '+esc(x.answer)+'</div><div class="sub">❌ '+esc(String(x.opts).split('|').join(' · '))+'</div>'+(x.note?'<div class="sub">💡 '+esc(x.note)+'</div>':'')+(x.dup?'<div class="sub" style="color:var(--r)">Bazada bor</div>':'')+'</div></label>'}).join('')+'<button class="btn" onclick="sjaisv()">💾 Belgilanganlarni saqlash</button>'}
e.innerHTML=h+'</div>'}
function sjaigo(){SJ.ain=+$('ai_n').value;SJ.ail=+$('ai_l').value;SJ.ai.busy=1;SJ.ai.list=null;sjair();api('qz_ai',{cat:SJ.ai.cat,n:SJ.ain,level:SJ.ail}).then(function(j){if(!SJ.ai)return;SJ.ai.busy=0;if(j.ok)SJ.ai.list=j.list;sjair()})}
function sjaisv(){var A=SJ.ai,L=A.list.filter(function(x,i){return $('ai_c'+i).checked});if(!L.length){toast('Hech narsa belgilanmagan');return}api('qz_ai_save',{cat:A.cat,level:SJ.ail,list:L}).then(function(j){if(j.ok){toast(j.added+' ta savol saqlandi ✅');SJ.ai=null;sjq(0)}})}
var WXC=null;
function wxl(){$('wxb').innerHTML='<div class="sk"></div>';Promise.all([api('wx'),api('wx_my')]).then(function(r){WXC={w:r[0],m:r[1]};wxr()})}
function wxt(v){return (v>0?'+':'')+v+'°'}
