e.innerHTML='<div class="sc" style="cursor:pointer" onclick="go(\'wx\')"><div class="sh2">Ob-havo <span class="sub">· '+esc(j.date)+'</span><span class="chv2">›</span></div><div class="wgr">'+j.rows.map(function(x){return '<div><span class="wi">'+x.i+'</span><span class="wn">'+esc(x.n)+'</span><span class="wt">'+x.hi+'° <span>'+x.lo+'°</span></span></div>'}).join('')+'</div></div>'})}
function wxr(){var w=WXC.w,m=WXC.m,h='';
if(w.ok&&w.rows){h+='<div class="sub" style="margin:0 2px 8px">'+esc(w.date)+' · viloyat markazlari bo\'yicha</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px">'+w.rows.map(function(x){return '<div class="card" style="margin:0;padding:12px"><div class="row"><b style="font-size:14px">'+esc(x.n)+'</b><span style="font-size:22px">'+x.i+'</span></div><div style="font-size:18px;font-weight:800;margin-top:4px">'+wxt(x.lo)+' … '+wxt(x.hi)+'</div><div class="sub">'+esc(x.d)+(x.p!=null?' · 💧'+x.p+'%':'')+'</div></div>'}).join('')+'</div>'}
else h+='<div class="card sub">Ob-havo ma\'lumoti hozircha olinmadi. Birozdan keyin qayta oching.</div>';
if(!m.ok){$('wxb').innerHTML=h;return}
if(m.cfg){var C=m.cfg;h+='<div class="card"><div class="row" style="cursor:pointer" onclick="wxo()"><div style="display:flex;align-items:center;gap:10px">'+ck(C.on)+'<div><b>Kanallarga yuborish</b><div class="sub">'+C.n+' ta kanal · oxirgi: '+esc(C.last||'—')+'</div></div></div><span class="sub">'+(C.on?'Yoqilgan':'O\'chirilgan')+'</span></div><p class="sub" style="margin:12px 0 4px">⏰ Yuborish vaqti (Toshkent)</p><input id="wx_time" type="time" value="'+esc(C.time)+'"><p class="sub" style="margin:10px 0 4px">Rasm bilan yuboriladi. Rasm ostidagi matn — sarlavha · {sana} — bugungi sana, qalin: &lt;b&gt;...&lt;/b&gt;</p><textarea id="wx_head" rows="3" maxlength="1000">'+esc(C.head)+'</textarea><p class="sub" style="margin:10px 0 4px">Pastki matn</p><textarea id="wx_foot" rows="2" maxlength="1000">'+esc(C.foot)+'</textarea><div style="display:flex;gap:8px;margin-top:10px"><button class="btn" onclick="wxs()">Saqlash</button><button class="btn s" onclick="wxs(1)">🧪 Menga yuborish</button></div></div>'}
else if(!m.on)h+='<div class="card sub">Kanallarga yuborish hozircha o\'chirilgan.</div>';
h+='<div class="row" style="margin:4px 2px 8px"><b>Kanallarimga yuborish</b><span class="sub">har kuni '+esc(m.cfg?m.cfg.time:m.time)+'</span></div>'+(m.chats.length?m.chats.map(function(c,i){return '<div class="card row" style="cursor:pointer" onclick="wxc('+i+')"><div style="display:flex;align-items:center;gap:10px">'+ck(c.wx_on==1)+'<b>'+esc(c.username)+'</b></div><span class="sub">'+esc(c.ctype)+'</span></div>'}).join(''):'<div class="card sub">Tasdiqlangan kanal yoki guruh yo\'q. Avval «Kanal qo\'shish» orqali qo\'shing.</div>');
$('wxb').innerHTML=h}
